    def _on_phase_start_dark_ritual(self, player=None, phase=None, **_kwargs) -> None:
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None:
            return
        army = player.get_army()
        if army is None:
            return

        seen = set()
        for unit in list(getattr(army, "units", []) or []):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            if root is None or not root.is_alive():
                continue
            rid = str(maybe_entity_id(root) or "")
            if rid in seen:
                continue
            seen.add(rid)
            if not self._unit_on_battlefield_for_reposition(root):
                continue
            try:
                rule = root.get_dark_ritual_rule()
            except Exception:
                rule = None
            if not rule:
                continue
            ability_key = str(rule.get("ability_key") or "dark_ritual").strip().lower() or "dark_ritual"
            if root.has_used_unit_once_per_battle(ability_key):
                continue
            if not root._unit_contains_model_with_keyword("CULT DEMAGOGUE"):
                continue
            sr = getattr(root, "special_rules", None)
            if isinstance(sr, dict) and sr.get("dark_ritual_active"):
                continue
            ability_name = str(rule.get("source", "") or "Dark Ritual").strip() or "Dark Ritual"
            unit_id = maybe_entity_id(root)
            ctx = {
                "ability_name": ability_name,
                "phase": "Command phase",
                "unit": getattr(root, "name", ""),
                "unit_id": unit_id,
                "ability_key": ability_key,
            }
            message = (
                f"Use {ability_name} for {getattr(root, 'name', 'Unit')}? (Once per battle)\n"
                "Until end of turn: can charge after Advance; +1 to Hit and Wound."
            )
            self._queue_optional_ability_confirmation(
                player=player,
                ability_key="dark_ritual",
                ability_name=ability_name,
                message=message,
                context=ctx,
                payload={"unit_id": unit_id, "ability_key": ability_key},
                instance_key=str(unit_id or ""),
            )

    def _on_phase_start_lords_of_dread_enhancements(self, player=None, phase=None, **_kwargs) -> None:
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname not in ("COMMAND_PHASE", "CHARGE_PHASE"):
            return

        for p in list(getattr(self, "players", []) or []):
            if p is None:
                continue
            if pname == "CHARGE_PHASE" and player is not None and p is not player:
                continue
            army = p.get_army()
            if army is None:
                continue
            ck_mgr = getattr(army, "chaos_knights_detachments", None)
            if ck_mgr is None or not bool(getattr(ck_mgr, "is_lords_of_dread", lambda: False)()):
                continue

            seen: set[str] = set()
            for unit in list(getattr(army, "units", []) or []):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None or not root.is_alive():
                    continue
                rid = str(maybe_entity_id(root) or "")
                if rid in seen:
                    continue
                seen.add(rid)
                if not self._unit_on_battlefield_for_reposition(root):
                    continue

                if pname == "CHARGE_PHASE":
                    can_use = getattr(root, "can_use_enhancement_charge_after_advance_once", None)
                    if not callable(can_use) or not bool(can_use()):
                        continue
                    sr = getattr(root, "special_rules", None)
                    if not isinstance(sr, dict):
                        sr = {}
                    ability_name = str(
                        sr.get("enhancement_charge_after_advance_source", "")
                        or "Throne Mechanicum of Skulls"
                    ).strip() or "Throne Mechanicum of Skulls"
                    ability_key = str(
                        sr.get("enhancement_charge_after_advance_once_key", "")
                        or "throne_mechanicum_of_skulls"
                    ).strip().lower() or "throne_mechanicum_of_skulls"
                    unit_id = maybe_entity_id(root)
                    ctx = {
                        "ability_name": ability_name,
                        "phase": "Charge phase",
                        "unit": getattr(root, "name", ""),
                        "unit_id": unit_id,
                        "ability_key": ability_key,
                    }
                    message = (
                        f"Use {ability_name} for {getattr(root, 'name', 'Unit')}? (Once per battle)\n"
                        "Until end of phase: this unit can declare a charge in a turn in which it Advanced."
                    )
                    self._queue_optional_ability_confirmation(
                        player=p,
                        ability_key="enhancement_charge_after_advance_once",
                        ability_name=ability_name,
                        message=message,
                        context=ctx,
                        payload={"unit_id": unit_id, "ability_key": ability_key},
                        instance_key=f"{unit_id}:{ability_key}",
                    )
                    continue

                can_use_putrid = getattr(root, "can_use_enhancement_putrid_carapace", None)
                if not callable(can_use_putrid) or not bool(can_use_putrid()):
                    continue
                bearer_fn = getattr(root, "_putrid_carapace_bearer_model", None)
                bearer = bearer_fn() if callable(bearer_fn) else None
                if bearer is None:
                    continue
                try:
                    base = int(getattr(bearer, "_base_wounds", getattr(bearer, "wounds", 0)) or 0)
                except Exception:
                    base = 0
                try:
                    current = int(getattr(bearer, "wounds", 0) or 0)
                except Exception:
                    current = 0
                lost = max(0, int(base - current))
                if lost <= 0:
                    continue
                sr = getattr(root, "special_rules", None)
                if not isinstance(sr, dict):
                    sr = {}
                ability_name = str(
                    sr.get("enhancement_putrid_carapace_source", "")
                    or "Putrid Carapace"
                ).strip() or "Putrid Carapace"
                ability_key = str(
                    sr.get("enhancement_putrid_carapace_once_key", "")
                    or "putrid_carapace"
                ).strip().lower() or "putrid_carapace"
                unit_id = maybe_entity_id(root)
                model_id = maybe_entity_id(bearer)
                ctx = {
                    "ability_name": ability_name,
                    "phase": "Command phase",
                    "unit": getattr(root, "name", ""),
                    "model": getattr(bearer, "name", ""),
                    "unit_id": unit_id,
                    "model_id": model_id,
                    "ability_key": ability_key,
                    "heal_roll": "D6",
                    "max_heal": int(lost),
                }
                message = (
                    f"Use {ability_name} for {getattr(bearer, 'name', 'Model')} "
                    f"({getattr(root, 'name', 'Unit')})? (Once per battle)\n"
                    "The bearer regains up to D6 lost wounds."
                )
                self._queue_optional_ability_confirmation(
                    player=p,
                    ability_key="putrid_carapace",
                    ability_name=ability_name,
                    message=message,
                    context=ctx,
                    payload={
                        "unit_id": unit_id,
                        "model_id": model_id,
                        "ability_key": ability_key,
                        "heal_roll": "D6",
                        "max_heal": int(lost),
                    },
                    instance_key=f"{unit_id}:{ability_key}",
                )

    def _on_phase_start_drukhari_enhancements(self, player=None, phase=None, **_kwargs) -> None:
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        try:
            current_turn = int(getattr(self, "turn", 0) or 0)
        except (TypeError, ValueError):
            current_turn = 0
        current_player = getattr(self, "get_current_player", lambda: None)()
        current_turn_owner_id = str(getattr(current_player, "id", "") or "")

        players = sorted(
            list(getattr(self, "players", []) or []),
            key=lambda p: str(getattr(p, "id", "") or ""),
        )
        for owner in players:
            if owner is None:
                continue
            army = self._get_player_army(owner)
            if army is None:
                continue
            dru_mgr = getattr(army, "drukhari_detachments", None)
            if dru_mgr is None or not bool(getattr(dru_mgr, "is_kabalite_cartel", lambda: False)()):
                continue

            seen: set[str] = set()
            for unit in list(getattr(army, "units", []) or []):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None or not root.is_alive():
                    continue
                rid = str(maybe_entity_id(root) or "")
                if rid in seen:
                    continue
                seen.add(rid)
                if not self._unit_on_battlefield_for_reposition(root):
                    continue

                can_use = getattr(root, "can_use_enhancement_leechbite_plate", None)
                if not callable(can_use) or not bool(can_use()):
                    continue
                bearer_fn = getattr(root, "_leechbite_plate_bearer_model", None)
                bearer = bearer_fn() if callable(bearer_fn) else None
                if bearer is None:
                    continue
                try:
                    base = int(getattr(bearer, "_base_wounds", getattr(bearer, "wounds", 0)) or 0)
                except Exception:
                    base = 0
                try:
                    current = int(getattr(bearer, "wounds", 0) or 0)
                except Exception:
                    current = 0
                lost = max(0, int(base - current))
                if lost <= 0:
                    continue

                sr = getattr(root, "special_rules", None)
                if not isinstance(sr, dict):
                    sr = {}
                ability_name = str(
                    sr.get("enhancement_leechbite_plate_source", "")
                    or "Leechbite Plate"
                ).strip() or "Leechbite Plate"
                ability_key = str(
                    sr.get("enhancement_leechbite_plate_ability_key", "")
                    or "leechbite_plate"
                ).strip().lower() or "leechbite_plate"
                try:
                    token_cost = int(sr.get("enhancement_leechbite_plate_pain_token_cost", 1) or 1)
                except (TypeError, ValueError):
                    token_cost = 1
                token_cost = max(1, int(token_cost))
                unit_id = maybe_entity_id(root)
                model_id = maybe_entity_id(bearer)
                ctx = {
                    "ability_name": ability_name,
                    "phase": "Command phase",
                    "unit": getattr(root, "name", ""),
                    "model": getattr(bearer, "name", ""),
                    "unit_id": unit_id,
                    "model_id": model_id,
                    "ability_key": ability_key,
                    "pain_token_cost": int(token_cost),
                    "heal_to_full": True,
                }
                message = (
                    f"Use {ability_name} for {getattr(bearer, 'name', 'Model')} "
                    f"({getattr(root, 'name', 'Unit')})?\n"
                    f"Spend {int(token_cost)} Pain token(s): the bearer regains all lost wounds."
                )
                self._queue_optional_ability_confirmation(
                    player=owner,
                    ability_key="leechbite_plate",
                    ability_name=ability_name,
                    message=message,
                    context=ctx,
                    payload={
                        "unit_id": unit_id,
                        "model_id": model_id,
                        "ability_key": ability_key,
                        "pain_token_cost": int(token_cost),
                    },
                    instance_key=f"{unit_id}:{ability_key}:{int(current_turn)}:{current_turn_owner_id}",
                )

        if current_player is None:
            return
        owner = current_player
        army = self._get_player_army(owner)
        if army is None:
            return
        dru_mgr = getattr(army, "drukhari_detachments", None)
        from ..decision_kinds import DECISION_CHOOSE_QUARRY
        from ..decisions import DecisionOption, DecisionRequest

        is_reapers_fn = getattr(dru_mgr, "is_reapers_wager", None) if dru_mgr is not None else None
        if bool(callable(is_reapers_fn) and is_reapers_fn()):
            queue = getattr(self, "decision_queue", None)
            owner_id = str(getattr(owner, "id", "") or "")
            pending_source_ids: set[str] = set()
            if queue is not None and hasattr(queue, "list"):
                for req in list(queue.list() or []):
                    if str(getattr(req, "decision_type", "") or "") != DECISION_CHOOSE_QUARRY:
                        continue
                    req_ctx = dict(getattr(req, "context", {}) or {})
                    if str(req_ctx.get("ability", "") or "") != "conductor_of_torment":
                        continue
                    if str(req_ctx.get("turn_owner", "") or "") != owner_id:
                        continue
                    try:
                        req_turn = int(req_ctx.get("turn", 0) or 0)
                    except (TypeError, ValueError):
                        req_turn = 0
                    if req_turn != int(current_turn or 0):
                        continue
                    source_id = str(req_ctx.get("source_unit_id", "") or "")
                    if source_id:
                        pending_source_ids.add(source_id)

            seen_roots: set[str] = set()
            for unit in list(getattr(army, "units", []) or []):
                if unit is None:
                    continue
                root = unit.get_attached_unit_root() if hasattr(unit, "get_attached_unit_root") else unit
                if root is None or not bool(getattr(root, "is_alive", lambda: False)()):
                    continue
                rid = str(maybe_entity_id(root) or "")
                if rid in seen_roots:
                    continue
                seen_roots.add(rid)
                if not self._unit_on_battlefield_for_reposition(root):
                    continue

                members = list(root.get_attached_unit_members() or []) if hasattr(root, "get_attached_unit_members") else []
                if not members:
                    members = [root]
                members = sorted(members, key=lambda m: str(maybe_entity_id(m) or ""))
                source_member = None
                source_sr = None
                for member in members:
                    sr = getattr(member, "special_rules", None)
                    if isinstance(sr, dict) and bool(sr.get("enhancement_conductor_of_torment", False)):
                        source_member = member
                        source_sr = sr
                        break
                if source_member is None or not isinstance(source_sr, dict):
                    continue

                get_bearer = getattr(source_member, "_get_enhancement_bearer_model", None)
                bearer = get_bearer() if callable(get_bearer) else None
                if bearer is None:
                    continue
                bearer_alive_attr = getattr(bearer, "is_alive", True)
                if not bool(bearer_alive_attr() if callable(bearer_alive_attr) else bearer_alive_attr):
                    continue

                source_unit_id = str(maybe_entity_id(source_member) or "")
                if not source_unit_id or source_unit_id in pending_source_ids:
                    continue

                source_name = str(
                    source_sr.get("enhancement_conductor_of_torment_source", "") or "Conductor of Torment"
                ).strip() or "Conductor of Torment"
                try:
                    gain_tokens = int(source_sr.get("enhancement_conductor_of_torment_gain_pain_tokens", 1) or 1)
                except (TypeError, ValueError):
                    gain_tokens = 1
                gain_tokens = max(0, int(gain_tokens))
                try:
                    spend_token_cost = int(source_sr.get("enhancement_conductor_of_torment_spend_pain_token_cost", 1) or 1)
                except (TypeError, ValueError):
                    spend_token_cost = 1
                spend_token_cost = max(1, int(spend_token_cost))

                current_winning_side_fn = getattr(dru_mgr, "callous_competition_current_winning_side", None)
                if callable(current_winning_side_fn):
                    current_winning_side = str(current_winning_side_fn() or "").strip().upper()
                else:
                    current_winning_side = str(getattr(dru_mgr, "callous_competition_winning_side", "") or "").strip().upper()
                harlequins_side = str(
                    getattr(dru_mgr, "CALLOUS_COMPETITION_SIDE_HARLEQUINS", "HARLEQUINS")
                ).strip().upper()
                drukhari_side = str(
                    getattr(dru_mgr, "CALLOUS_COMPETITION_SIDE_DRUKHARI", "DRUKHARI")
                ).strip().upper()

                pfp = getattr(army, "power_from_pain", None)
                available_pain = int(getattr(pfp, "tokens", 0) or 0) if pfp is not None else 0
                options = [DecisionOption.create("None", payload={"action": "skip"})]
                if current_winning_side == harlequins_side and gain_tokens > 0:
                    options.append(
                        DecisionOption.create(
                            f"Gain {gain_tokens} Pain token(s); DRUKHARI now winning",
                            payload={
                                "action": "gain_pain_token_and_switch_to_drukhari",
                                "pain_tokens_gained": int(gain_tokens),
                                "new_winning_side": drukhari_side,
                            },
                        )
                    )
                if current_winning_side == drukhari_side and available_pain >= spend_token_cost:
                    options.append(
                        DecisionOption.create(
                            f"Spend {spend_token_cost} Pain token(s); HARLEQUINS now winning",
                            payload={
                                "action": "spend_pain_token_and_switch_to_harlequins",
                                "pain_token_cost": int(spend_token_cost),
                                "new_winning_side": harlequins_side,
                            },
                        )
                    )
                if len(options) <= 1:
                    continue
                request = DecisionRequest.create(
                    DECISION_CHOOSE_QUARRY,
                    f"{source_name}: choose one option for {getattr(bearer, 'name', 'bearer')}.",
                    player_id=getattr(owner, "id", None),
                    options=options,
                    context={
                        "ability": "conductor_of_torment",
                        "ability_name": source_name,
                        "phase": "Command phase",
                        "optional": True,
                        "source_unit_id": source_unit_id,
                        "unit_id": source_unit_id,
                        "model_id": maybe_entity_id(bearer),
                        "turn_owner": owner_id,
                        "turn": int(current_turn or 0),
                        "pain_tokens_gained": int(gain_tokens),
                        "pain_token_cost": int(spend_token_cost),
                        "current_winning_side": current_winning_side,
                    },
                )
                self.request_decision(request)
                pending_source_ids.add(source_unit_id)

        is_realspace_fn = getattr(dru_mgr, "is_realspace_raiders", None) if dru_mgr is not None else None
        if not bool(callable(is_realspace_fn) and is_realspace_fn()):
            return

        queue = getattr(self, "decision_queue", None)
        owner_id = str(getattr(owner, "id", "") or "")
        if not owner_id:
            return
        pending_source_ids: set[str] = set()
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "") or "") != DECISION_CHOOSE_QUARRY:
                    continue
                req_ctx = dict(getattr(req, "context", {}) or {})
                if str(req_ctx.get("ability", "") or "") != "labyrinthine_cunning":
                    continue
                if str(req_ctx.get("turn_owner", "") or "") != owner_id:
                    continue
                try:
                    req_turn = int(req_ctx.get("turn", 0) or 0)
                except (TypeError, ValueError):
                    req_turn = 0
                if req_turn != int(current_turn or 0):
                    continue
                source_id = str(req_ctx.get("source_unit_id", "") or "")
                if source_id:
                    pending_source_ids.add(source_id)

        seen_roots: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            if unit is None:
                continue
            root = unit.get_attached_unit_root() if hasattr(unit, "get_attached_unit_root") else unit
            if root is None or not bool(getattr(root, "is_alive", lambda: False)()):
                continue
            rid = str(maybe_entity_id(root) or "")
            if rid in seen_roots:
                continue
            seen_roots.add(rid)
            if not self._unit_on_battlefield_for_reposition(root):
                continue
            members = list(root.get_attached_unit_members() or []) if hasattr(root, "get_attached_unit_members") else []
            if not members:
                members = [root]
            members = sorted(members, key=lambda m: str(maybe_entity_id(m) or ""))
            source_member = None
            source_sr = None
            for member in members:
                sr = getattr(member, "special_rules", None)
                if isinstance(sr, dict) and bool(sr.get("enhancement_labyrinthine_cunning", False)):
                    source_member = member
                    source_sr = sr
                    break
            if source_member is None or not isinstance(source_sr, dict):
                continue
            get_bearer = getattr(source_member, "_get_enhancement_bearer_model", None)
            bearer = get_bearer() if callable(get_bearer) else None
            if bearer is None:
                continue
            bearer_alive_attr = getattr(bearer, "is_alive", True)
            if not bool(bearer_alive_attr() if callable(bearer_alive_attr) else bearer_alive_attr):
                continue
            source_unit_id = str(maybe_entity_id(source_member) or "")
            if not source_unit_id or source_unit_id in pending_source_ids:
                continue
            source_name = str(
                source_sr.get("enhancement_labyrinthine_cunning_source", "") or "Labyrinthine Cunning"
            ).strip() or "Labyrinthine Cunning"
            try:
                pain_token_cost = int(source_sr.get("enhancement_labyrinthine_cunning_pain_token_cost", 1) or 1)
            except (TypeError, ValueError):
                pain_token_cost = 1
            pain_token_cost = max(1, int(pain_token_cost))
            try:
                cp_gain = int(source_sr.get("enhancement_labyrinthine_cunning_cp_gain", 1) or 1)
            except (TypeError, ValueError):
                cp_gain = 1
            cp_gain = max(0, int(cp_gain))
            try:
                success_on = int(source_sr.get("enhancement_labyrinthine_cunning_success_on", 4) or 4)
            except (TypeError, ValueError):
                success_on = 4
            success_on = min(6, max(2, int(success_on)))
            pfp = getattr(army, "power_from_pain", None)
            available_pain = int(getattr(pfp, "tokens", 0) or 0) if pfp is not None else 0
            options = [DecisionOption.create("None", payload={"action": "skip"})]
            if available_pain >= pain_token_cost:
                options.append(
                    DecisionOption.create(
                        f"Spend {pain_token_cost} Pain token (+{cp_gain}CP)",
                        payload={
                            "action": "spend_pain_token_gain_cp",
                            "pain_token_cost": int(pain_token_cost),
                            "cp_gain": int(cp_gain),
                        },
                    )
                )
            options.append(
                DecisionOption.create(
                    f"Roll D6 ({success_on}+ for +{cp_gain}CP)",
                    payload={
                        "action": "roll_d6_gain_cp",
                        "success_on": int(success_on),
                        "cp_gain": int(cp_gain),
                    },
                )
            )
            request = DecisionRequest.create(
                DECISION_CHOOSE_QUARRY,
                f"{source_name}: choose one option for {getattr(bearer, 'name', 'bearer')}.",
                player_id=getattr(owner, "id", None),
                options=options,
                context={
                    "ability": "labyrinthine_cunning",
                    "ability_name": source_name,
                    "phase": "Command phase",
                    "optional": True,
                    "source_unit_id": source_unit_id,
                    "unit_id": source_unit_id,
                    "model_id": maybe_entity_id(bearer),
                    "turn_owner": owner_id,
                    "turn": int(current_turn or 0),
                    "pain_token_cost": int(pain_token_cost),
                    "cp_gain": int(cp_gain),
                    "success_on": int(success_on),
                },
            )
            self.request_decision(request)
            pending_source_ids.add(source_unit_id)

    def _on_phase_start_drukhari_realspace_shooting_enhancements(self, player=None, phase=None, **_kwargs) -> None:
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "SHOOTING_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        current_player = getattr(self, "get_current_player", lambda: None)()
        if player is None or current_player is None or player is not current_player:
            return
        army = self._get_player_army(player)
        if army is None:
            return
        dru_mgr = getattr(army, "drukhari_detachments", None)
        is_realspace_fn = getattr(dru_mgr, "is_realspace_raiders", None) if dru_mgr is not None else None
        if not bool(callable(is_realspace_fn) and is_realspace_fn()):
            return
        game_map = getattr(self, "map", None)
        if game_map is None:
            return
        from ...utility.aura_utils import model_within_range_of_unit
        from ..decision_kinds import DECISION_CHOOSE_QUARRY
        from ..decisions import DecisionOption, DecisionRequest

        try:
            turn = int(getattr(self, "turn", 0) or 0)
        except (TypeError, ValueError):
            turn = 0
        owner_id = str(getattr(player, "id", "") or "")
        if turn <= 0 or not owner_id:
            return
        queue = getattr(self, "decision_queue", None)
        pending_source_ids: set[str] = set()
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "") or "") != DECISION_CHOOSE_QUARRY:
                    continue
                req_ctx = dict(getattr(req, "context", {}) or {})
                if str(req_ctx.get("ability", "") or "") != "crucible_of_malediction":
                    continue
                if str(req_ctx.get("turn_owner", "") or "") != owner_id:
                    continue
                try:
                    req_turn = int(req_ctx.get("turn", 0) or 0)
                except (TypeError, ValueError):
                    req_turn = 0
                if req_turn != int(turn or 0):
                    continue
                source_id = str(req_ctx.get("source_unit_id", "") or "")
                if source_id:
                    pending_source_ids.add(source_id)

        seen_roots: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            if unit is None:
                continue
            root = unit.get_attached_unit_root() if hasattr(unit, "get_attached_unit_root") else unit
            if root is None or not bool(getattr(root, "is_alive", lambda: False)()):
                continue
            rid = str(maybe_entity_id(root) or "")
            if rid in seen_roots:
                continue
            seen_roots.add(rid)
            if not self._unit_on_battlefield_for_reposition(root):
                continue
            members = list(root.get_attached_unit_members() or []) if hasattr(root, "get_attached_unit_members") else []
            if not members:
                members = [root]
            members = sorted(members, key=lambda m: str(maybe_entity_id(m) or ""))
            source_member = None
            source_sr = None
            for member in members:
                sr = getattr(member, "special_rules", None)
                if isinstance(sr, dict) and bool(sr.get("enhancement_crucible_of_malediction", False)):
                    source_member = member
                    source_sr = sr
                    break
            if source_member is None or not isinstance(source_sr, dict):
                continue
            once_key = str(
                source_sr.get("enhancement_crucible_of_malediction_once_key", "") or "crucible_of_malediction"
            ).strip().lower() or "crucible_of_malediction"
            used_once = getattr(source_member, "has_used_unit_once_per_battle", None)
            if callable(used_once) and bool(used_once(once_key)):
                continue
            get_bearer = getattr(source_member, "_get_enhancement_bearer_model", None)
            bearer = get_bearer() if callable(get_bearer) else None
            if bearer is None:
                continue
            bearer_alive_attr = getattr(bearer, "is_alive", True)
            if not bool(bearer_alive_attr() if callable(bearer_alive_attr) else bearer_alive_attr):
                continue
            source_unit_id = str(maybe_entity_id(source_member) or "")
            if not source_unit_id or source_unit_id in pending_source_ids:
                continue
            try:
                range_in = float(source_sr.get("enhancement_crucible_of_malediction_range", 12.0) or 12.0)
            except (TypeError, ValueError):
                range_in = 12.0
            range_in = max(0.0, float(range_in))
            if range_in <= 0.0:
                continue
            candidate_units: list[object] = []
            seen_enemy_ids: set[str] = set()
            for enemy in list(game_map.get_enemy_units(root) or []):
                if enemy is None:
                    continue
                enemy_root = enemy.get_attached_unit_root() if hasattr(enemy, "get_attached_unit_root") else enemy
                if enemy_root is None:
                    continue
                enemy_id = str(maybe_entity_id(enemy_root) or "")
                if not enemy_id or enemy_id in seen_enemy_ids:
                    continue
                seen_enemy_ids.add(enemy_id)
                if not bool(getattr(enemy_root, "is_alive", lambda: False)()):
                    continue
                if not bool(getattr(enemy_root, "deployed", True)):
                    continue
                in_reserves_fn = getattr(enemy_root, "is_in_reserves", None)
                in_reserves = bool(in_reserves_fn()) if callable(in_reserves_fn) else (
                    str(getattr(enemy_root, "reserve_status", "deployed") or "deployed").strip().lower()
                    in {"reserves", "strategic_reserves"}
                )
                if in_reserves or bool(getattr(enemy_root, "is_embarked", False)):
                    continue
                if getattr(enemy_root, "embarked_in", None) is not None:
                    continue
                if not bool(model_within_range_of_unit(bearer, enemy_root, float(range_in), use_attached_aggregate=True)):
                    continue
                candidate_units.append(enemy_root)
            if not candidate_units:
                continue
            candidate_units = sorted(candidate_units, key=lambda u: str(maybe_entity_id(u) or ""))
            candidate_unit_ids = [str(maybe_entity_id(u) or "") for u in candidate_units if str(maybe_entity_id(u) or "")]
            if not candidate_unit_ids:
                continue
            source_name = str(
                source_sr.get("enhancement_crucible_of_malediction_source", "") or "Crucible of Malediction"
            ).strip() or "Crucible of Malediction"
            try:
                pain_token_cost = int(source_sr.get("enhancement_crucible_of_malediction_pain_token_cost", 1) or 1)
            except (TypeError, ValueError):
                pain_token_cost = 1
            pain_token_cost = max(1, int(pain_token_cost))
            try:
                modifier_if_spent = int(
                    source_sr.get("enhancement_crucible_of_malediction_battleshock_modifier_if_spent", -1) or -1
                )
            except (TypeError, ValueError):
                modifier_if_spent = -1
            try:
                mortal_wounds = int(
                    source_sr.get("enhancement_crucible_of_malediction_psyker_fail_mortal_wounds", 3) or 3
                )
            except (TypeError, ValueError):
                mortal_wounds = 3
            mortal_wounds = max(0, int(mortal_wounds))
            pfp = getattr(army, "power_from_pain", None)
            available_pain = int(getattr(pfp, "tokens", 0) or 0) if pfp is not None else 0
            options = [
                DecisionOption.create("None", payload={"action": "skip"}),
                DecisionOption.create("Use Crucible", payload={"action": "use"}),
            ]
            if available_pain >= pain_token_cost:
                options.append(
                    DecisionOption.create(
                        f"Use + spend {pain_token_cost} Pain token",
                        payload={
                            "action": "use_and_spend_pain_token",
                            "pain_token_cost": int(pain_token_cost),
                        },
                    )
                )
            request = DecisionRequest.create(
                DECISION_CHOOSE_QUARRY,
                (
                    f"{source_name}: each enemy unit within {int(range_in)}\" of {getattr(bearer, 'name', 'the bearer')} "
                    "must take a Battle-shock test."
                ),
                player_id=getattr(player, "id", None),
                options=options,
                context={
                    "ability": "crucible_of_malediction",
                    "ability_name": source_name,
                    "phase": "Shooting phase",
                    "optional": True,
                    "source_unit_id": source_unit_id,
                    "unit_id": source_unit_id,
                    "model_id": maybe_entity_id(bearer),
                    "turn_owner": owner_id,
                    "turn": int(turn or 0),
                    "range": float(range_in),
                    "pain_token_cost": int(pain_token_cost),
                    "battle_shock_test_modifier_if_spent": int(modifier_if_spent),
                    "psyker_fail_mortal_wounds": int(mortal_wounds),
                    "candidate_unit_ids": list(candidate_unit_ids),
                    "once_key": once_key,
                },
            )
            self.request_decision(request)
            pending_source_ids.add(source_unit_id)

    def _on_phase_start_post_shoot_leadership_debuff_cleanup(self, player=None, phase=None, **_kwargs) -> None:
        """Clear post-shoot Leadership/Battle-shock debuffs at the start of the owner's Shooting phase."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "SHOOTING_PHASE":
            return
        if player is None:
            return
        owner_id = str(getattr(player, "id", "") or "")
        if not owner_id:
            return
        for p in list(self.players or []):
            if p is None:
                raise RuntimeError("Post-shoot debuff cleanup requires players.")
            army = p.get_army()
            if army is None:
                raise RuntimeError(f"Post-shoot debuff cleanup requires an army for {p.name}.")
            for unit in list(army.units):
                sr = getattr(unit, "special_rules", None)
                if not isinstance(sr, dict):
                    continue
                if str(sr.get("post_shoot_leadership_debuff_owner", "") or "") != owner_id:
                    continue
                if sr.get("post_shoot_leadership_debuff_active"):
                    unit.clear_post_shoot_leadership_debuff()

    def _on_phase_start_post_shoot_duration_cleanup(self, player=None, phase=None, **_kwargs) -> None:
        """Clear owner-next-phase post-shoot markers."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname not in ("SHOOTING_PHASE", "COMMAND_PHASE"):
            return
        if player is None:
            return
        owner_id = str(getattr(player, "id", "") or "")
        if not owner_id:
            return
        for p in list(self.players or []):
            if p is None:
                raise RuntimeError("Post-shoot duration cleanup requires players.")
            army = p.get_army()
            if army is None:
                raise RuntimeError(f"Post-shoot duration cleanup requires an army for {p.name}.")
            for unit in list(army.units):
                sr = getattr(unit, "special_rules", None)
                if not isinstance(sr, dict):
                    continue
                expires_timing = str(sr.get("post_shoot_no_cover_expires_timing", "") or "").strip().upper()
                should_clear_no_cover = (
                    str(sr.get("post_shoot_no_cover_owner", "") or "") == owner_id
                    and (
                        (expires_timing == "OWNER_NEXT_SHOOTING_START" and pname == "SHOOTING_PHASE")
                        or (expires_timing == "OWNER_NEXT_COMMAND_START" and pname == "COMMAND_PHASE")
                    )
                )
                if should_clear_no_cover:
                    for key in (
                        "post_shoot_no_cover_active",
                        "post_shoot_no_cover_expires_timing",
                        "post_shoot_no_cover_source",
                        "post_shoot_no_cover_owner",
                        "post_shoot_no_cover_turn",
                    ):
                        sr.pop(key, None)
                if str(sr.get("post_shoot_no_overwatch_owner", "") or "") == owner_id:
                    for key in (
                        "post_shoot_no_overwatch_active",
                        "post_shoot_no_overwatch_source",
                        "post_shoot_no_overwatch_owner",
                        "post_shoot_no_overwatch_turn",
                    ):
                        sr.pop(key, None)
                if (
                    pname == "SHOOTING_PHASE"
                    and str(sr.get("atavistic_instigation_duck_owner", "") or "") == owner_id
                    and sr.get("atavistic_instigation_duck_active")
                ):
                    for key in (
                        "atavistic_instigation_duck_active",
                        "atavistic_instigation_duck_owner",
                        "atavistic_instigation_duck_turn",
                        "atavistic_instigation_duck_source",
                        "atavistic_instigation_duck_hit_roll_penalty",
                        "atavistic_instigation_duck_expires_timing",
                    ):
                        sr.pop(key, None)
                if (
                    pname == "SHOOTING_PHASE"
                    and str(sr.get("gsc_starfall_shells_owner", "") or "") == owner_id
                    and bool(sr.get("gsc_starfall_shells_active"))
                ):
                    for key in (
                        "gsc_starfall_shells_active",
                        "gsc_starfall_shells_owner",
                        "gsc_starfall_shells_turn",
                        "gsc_starfall_shells_source",
                        "gsc_starfall_shells_hit_roll_penalty",
                        "gsc_starfall_shells_expires_timing",
                    ):
                        sr.pop(key, None)
                if (
                    pname == "SHOOTING_PHASE"
                    and str(sr.get("shocked_owner", "") or "") == owner_id
                    and str(sr.get("shocked_expires_timing", "") or "").strip().upper() == "OWNER_NEXT_SHOOTING_START"
                    and bool(sr.get("shocked_active"))
                ):
                    clear_fn = getattr(unit, "clear_shocked", None)
                    if callable(clear_fn):
                        clear_fn()
                        continue
                if (
                    pname == "SHOOTING_PHASE"
                    and str(sr.get("post_shoot_staggered_oc_owner", "") or "") == owner_id
                    and bool(sr.get("post_shoot_staggered_oc_active"))
                ):
                    try:
                        marked_turn = int(sr.get("post_shoot_staggered_oc_turn", 0) or 0)
                    except Exception:
                        marked_turn = 0
                    try:
                        current_turn = int(getattr(self, "turn", 0) or 0)
                    except Exception:
                        current_turn = 0
                    if current_turn > marked_turn:
                        clear_fn = getattr(unit, "clear_post_shoot_staggered_oc", None)
                        if callable(clear_fn):
                            clear_fn()
                            continue
                unit.special_rules = sr

    def _on_phase_start_wracked_with_agonies_cleanup(self, player=None, phase=None, **_kwargs) -> None:
        """Clear Wracked with Agonies effects at the start of the owner's Command phase."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None:
            return
        owner_id = str(getattr(player, "id", "") or "")
        if not owner_id:
            return
        for p in list(self.players or []):
            if p is None:
                raise RuntimeError("Wracked with Agonies cleanup requires players.")
            army = p.get_army()
            if army is None:
                raise RuntimeError(f"Wracked with Agonies cleanup requires an army for {p.name}.")
