    def _on_phase_start_spirit_mark_cleanup(self, player=None, phase=None, **_kwargs) -> None:
        """Clear Spirit Mark effects at the start of the owner's Movement phase."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        if player is None:
            return
        owner_id = str(getattr(player, "id", "") or "")
        if not owner_id:
            return
        try:
            turn = int(getattr(self, "turn", 0) or 0)
        except Exception:
            turn = 0
        army = player.get_army()
        if army is None:
            raise RuntimeError(f"Spirit Mark cleanup requires an army for {getattr(player, 'name', 'player')}.")
        for unit in list(getattr(army, "units", []) or []):
            sr = getattr(unit, "special_rules", None)
            if not isinstance(sr, dict):
                continue
            if not sr.get("spirit_mark_active"):
                continue
            if str(sr.get("spirit_mark_owner", "") or "") != owner_id:
                continue
            try:
                mark_turn = int(sr.get("spirit_mark_turn", 0) or 0)
            except Exception:
                mark_turn = 0
            if mark_turn == int(turn or 0):
                continue
            for key in (
                "spirit_mark_active",
                "spirit_mark_owner",
                "spirit_mark_turn",
                "spirit_mark_source",
                "spirit_mark_target_id",
                "spirit_mark_sustained_hits_value",
                "spirit_mark_keyword",
            ):
                sr.pop(key, None)
            unit.special_rules = sr

    def _on_phase_start_engagement_battleshock(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase: enemy units within Engagement Range of a model must take Battle-shock tests."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        game_map = self.map
        if game_map is None:
            raise RuntimeError("Engagement Battle-shock requires a game map.")

        from ...utility.aura_utils import model_within_engagement_range_of_unit

        def _apply_battleshock(target_unit, *, modifier: int = 0, reason: str = "") -> None:
            if target_unit is None:
                return
            sr = getattr(target_unit, "special_rules", None)
            if not isinstance(sr, dict):
                sr = {}
            if modifier:
                current = int(sr.get("battle_shock_test_modifier", 0) or 0)
                sr["battle_shock_test_modifier"] = current + int(modifier)
                if reason:
                    reasons = list(sr.get("battle_shock_test_modifier_reasons", []) or [])
                    reasons.append(reason)
                    sr["battle_shock_test_modifier_reasons"] = reasons
            target_unit.special_rules = sr
            target_unit.take_battle_shock_test(int(getattr(self, "turn", 0) or 1))

        def _unit_in_engagement_with_unit(source_unit, target_unit) -> bool:
            if source_unit is None or target_unit is None:
                return False
            within_fn = getattr(game_map, "is_within_engagement_range", None)
            if callable(within_fn):
                try:
                    return bool(within_fn(source_unit, target_unit))
                except Exception:
                    return False
            for model in list(getattr(source_unit, "models", []) or []):
                try:
                    if model_within_engagement_range_of_unit(model, target_unit):
                        return True
                except Exception:
                    continue
            return False

        for p in list(self.players or []):
            if p is None:
                raise RuntimeError("Engagement Battle-shock requires players.")
            army = p.get_army()
            if army is None:
                raise RuntimeError(f"Engagement Battle-shock requires an army for {p.name}.")
            tested_units: set[tuple[str, str]] = set()
            for unit in list(army.units):
                if unit is None:
                    continue
                if not unit.is_alive() or not getattr(unit, "deployed", True):
                    continue
                if unit.is_in_reserves():
                    continue
                if unit.is_embarked:
                    continue

                enemy_roots = []
                seen_enemy = set()
                for enemy in game_map.get_enemy_units(unit):
                    if enemy is None:
                        continue
                    root = enemy.get_attached_unit_root()
                    key = get_entity_id(root)
                    if key in seen_enemy:
                        continue
                    seen_enemy.add(key)
                    if not root.is_alive() or not getattr(root, "deployed", True):
                        continue
                    if root.is_in_reserves():
                        continue
                    if root.is_embarked:
                        continue
                    enemy_roots.append(root)

                if not enemy_roots:
                    continue

                unit_specs = unit.unit_start_fight_phase_engagement_battleshock_specs() or []
                for spec in unit_specs:
                    source = str(spec.get("source", "") or "Fight phase Battle-shock").strip()
                    penalty = 0
                    try:
                        penalty = int(spec.get("penalty", 0) or 0)
                    except Exception:
                        penalty = 0
                    apply_when_below_half = bool(spec.get("penalty_applies_when_below_half", True))
                    for enemy_root in enemy_roots:
                        if not _unit_in_engagement_with_unit(unit, enemy_root):
                            continue
                        key = (str(get_entity_id(enemy_root)), source.lower())
                        if key in tested_units:
                            continue
                        tested_units.add(key)
                        mod = 0
                        reason = ""
                        if penalty:
                            if apply_when_below_half:
                                if enemy_root.is_below_half_strength():
                                    mod = -abs(int(penalty))
                                    reason = "Below Half-strength"
                            else:
                                mod = int(penalty)
                                reason = "Ability modifier"
                        _apply_battleshock(enemy_root, modifier=mod, reason=reason)
                        from ...utility.event_bus import append_action
                        if p is not None:
                            label = f"{getattr(unit, 'name', 'Unit')} {source}".strip()
                            append_action(
                                p,
                                f"{label}: {getattr(enemy_root, 'name', 'Unit')} takes a Battle-shock test.",
                            )

                for model in list(unit.models or []):
                    if not getattr(model, "is_alive", False):
                        continue
                    specs = unit.model_start_fight_phase_engagement_battleshock_specs(model)
                    if specs:
                        for spec in specs:
                            source = str(spec.get("source", "") or "Fight phase Battle-shock").strip()
                            penalty = 0
                            try:
                                penalty = int(spec.get("penalty", 0) or 0)
                            except Exception:
                                penalty = 0
                            apply_when_below_half = bool(spec.get("penalty_applies_when_below_half", True))
                            for enemy_root in enemy_roots:
                                if not model_within_engagement_range_of_unit(model, enemy_root):
                                    continue
                                mod = 0
                                reason = ""
                                if penalty:
                                    if apply_when_below_half:
                                        if enemy_root.is_below_half_strength():
                                            mod = -abs(int(penalty))
                                            reason = "Below Half-strength"
                                    else:
                                        mod = int(penalty)
                                        reason = "Ability modifier"
                                _apply_battleshock(enemy_root, modifier=mod, reason=reason)
                                from ...utility.event_bus import append_action
                                if p is not None:
                                    label = f"{getattr(model, 'name', 'Model')} {source}".strip()
                                    append_action(
                                        p,
                                        f"{label}: {getattr(enemy_root, 'name', 'Unit')} takes a Battle-shock test.",
                                    )

                    aura_specs = []
                    try:
                        aura_specs = unit.model_start_fight_phase_aura_battleshock_specs(model) or []
                    except Exception:
                        aura_specs = []
                    for spec in aura_specs:
                        source = str(spec.get("source", "") or "Fight phase Battle-shock").strip()
                        try:
                            range_value = int(spec.get("range", 0) or 0)
                        except Exception:
                            range_value = 0
                        try:
                            penalty = int(spec.get("penalty", 0) or 0)
                        except Exception:
                            penalty = 0
                        if range_value <= 0:
                            continue
                        required_keywords = [
                            str(value or "").strip().upper()
                            for value in list(spec.get("required_keywords", []) or [])
                            if str(value or "").strip()
                        ]
                        required_keyword_mode = str(spec.get("required_keyword_mode", "all") or "all").strip().lower()
                        exclude_keywords = list(spec.get("exclude_keywords", []) or [])
                        for enemy_root in enemy_roots:
                            if required_keywords:
                                try:
                                    enemy_keywords = {str(k).upper() for k in list(getattr(enemy_root, "keywords", []) or [])}
                                except Exception:
                                    enemy_keywords = set()
                                if required_keyword_mode == "any":
                                    if set(required_keywords).isdisjoint(enemy_keywords):
                                        continue
                                else:
                                    if not set(required_keywords).issubset(enemy_keywords):
                                        continue
                            try:
                                excluded = any(enemy_root.has_any_keyword(kw) for kw in exclude_keywords)
                            except Exception:
                                excluded = False
                            if excluded:
                                continue
                            try:
                                if not unit._model_within_range_of_unit(model, enemy_root, float(range_value)):
                                    continue
                            except Exception:
                                continue
                            modifier = -abs(int(penalty)) if penalty else 0
                            reason = f"{source} modifier" if modifier else ""
                            _apply_battleshock(enemy_root, modifier=modifier, reason=reason)
                            from ...utility.event_bus import append_action
                            if p is not None:
                                label = f"{getattr(model, 'name', 'Model')} {source}".strip()
                                append_action(
                                    p,
                                    f"{label}: {getattr(enemy_root, 'name', 'Unit')} takes a Battle-shock test.",
                                )

    def _on_phase_start_fight_phase_select_engagement_battleshock(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase: select one enemy unit in Engagement Range to take a Battle-shock test."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        queue_fn = getattr(self, "_queue_start_phase_select_enemy_battleshock", None)
        if not callable(queue_fn):
            return

        from ...utility.aura_utils import model_within_engagement_range_of_unit

        def _unit_sort_key(unit):
            unit_id = str(get_entity_id(unit) or "").strip()
            if unit_id:
                return unit_id
            return str(getattr(unit, "name", "") or "")

        def _model_sort_key(model):
            model_id = str(get_entity_id(model) or "").strip()
            if model_id:
                return model_id
            return str(getattr(model, "name", "") or "")

        try:
            current_turn = int(getattr(self, "turn", 0) or 0)
        except (TypeError, ValueError):
            current_turn = 0

        for p in list(getattr(self, "players", []) or []):
            if p is None:
                raise RuntimeError("Fight phase select Engagement Battle-shock requires players.")
            army = p.get_army()
            if army is None:
                raise RuntimeError(f"Fight phase select Engagement Battle-shock requires an army for {p.name}.")
            enemy_roots = list(self._collect_enemy_unit_roots(p) or [])
            if not enemy_roots:
                continue

            seen_roots: set[str] = set()
            for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
                if unit is None:
                    continue
                root = unit.get_attached_unit_root() if hasattr(unit, "get_attached_unit_root") else unit
                if root is None:
                    continue
                root_id = str(get_entity_id(root) or "").strip()
                if not root_id or root_id in seen_roots:
                    continue
                seen_roots.add(root_id)
                root_is_alive_fn = getattr(root, "is_alive", None)
                root_alive = bool(root_is_alive_fn()) if callable(root_is_alive_fn) else bool(root_is_alive_fn)
                if not root_alive:
                    continue
                if not bool(getattr(root, "deployed", False)):
                    continue
                root_is_in_reserves_fn = getattr(root, "is_in_reserves", None)
                if callable(root_is_in_reserves_fn) and bool(root_is_in_reserves_fn()):
                    continue
                if bool(getattr(root, "is_embarked", False)):
                    continue

                spec_fn = getattr(root, "model_start_fight_phase_select_engagement_battleshock_specs", None)
                if not callable(spec_fn):
                    continue
                models = (
                    list(root.get_attached_unit_models() or [])
                    if hasattr(root, "get_attached_unit_models")
                    else list(getattr(root, "models", []) or [])
                )
                if not models:
                    continue

                for model in sorted(list(models or []), key=_model_sort_key):
                    model_is_alive_attr = getattr(model, "is_alive", True)
                    model_alive = bool(model_is_alive_attr() if callable(model_is_alive_attr) else model_is_alive_attr)
                    if not model_alive:
                        continue
                    specs = list(spec_fn(model) or [])
                    if not specs:
                        continue
                    source_unit = getattr(model, "parent_unit", None) or root
                    for spec in list(specs or []):
                        ability_key = str(spec.get("ability_key", "") or "").strip().lower()
                        once_per_turn = bool(spec.get("once_per_turn", False))
                        if once_per_turn and ability_key and current_turn > 0:
                            has_used_fn = getattr(model, "has_used_once_per_battle_round", None)
                            if callable(has_used_fn) and bool(has_used_fn(ability_key, battle_round=int(current_turn))):
                                continue

                        candidates: list = []
                        for enemy_root in list(enemy_roots or []):
                            if enemy_root is None:
                                continue
                            if model_within_engagement_range_of_unit(model, enemy_root):
                                candidates.append(enemy_root)
                        if not candidates:
                            continue
                        queue_fn(
                            player=p,
                            source_unit=source_unit,
                            model=model,
                            candidates=list(candidates),
                            spec=dict(spec),
                            phase_name=pname,
                        )

    def _on_phase_start_fight_phase_select_engagement_mortal_table(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase: select one enemy unit in Engagement Range and resolve a model-driven mortal-wound table."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        from ...utility.aura_utils import model_within_engagement_range_of_unit
        from ..decision_kinds import DECISION_CHOOSE_QUARRY
        from ..decisions import DecisionOption, DecisionRequest

        def _unit_sort_key(unit):
            unit_id = str(get_entity_id(unit) or "").strip()
            if unit_id:
                return unit_id
            return str(getattr(unit, "name", "") or "")

        def _model_sort_key(model):
            model_id = str(get_entity_id(model) or "").strip()
            if model_id:
                return model_id
            return str(getattr(model, "name", "") or "")

        try:
            current_turn = int(getattr(self, "turn", 0) or 0)
        except (TypeError, ValueError):
            current_turn = 0

        queue = getattr(self, "decision_queue", None)
        pending_model_ids: set[str] = set()
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "") or "") != DECISION_CHOOSE_QUARRY:
                    continue
                ctx = dict(getattr(req, "context", {}) or {})
                if str(ctx.get("ability", "") or "") != "fight_phase_select_engagement_mortal_table":
                    continue
                model_id = str(ctx.get("model_id", "") or "")
                if model_id:
                    pending_model_ids.add(model_id)

        for p in list(getattr(self, "players", []) or []):
            if p is None:
                continue
            army = p.get_army()
            if army is None:
                continue
            enemy_roots = list(self._collect_enemy_unit_roots(p) or [])
            if not enemy_roots:
                continue

            seen_roots: set[str] = set()
            for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
                if unit is None:
                    continue
                root = unit.get_attached_unit_root() if hasattr(unit, "get_attached_unit_root") else unit
                if root is None:
                    continue
                root_id = str(get_entity_id(root) or "").strip()
                if not root_id or root_id in seen_roots:
                    continue
                seen_roots.add(root_id)
                root_is_alive_fn = getattr(root, "is_alive", None)
                root_alive = bool(root_is_alive_fn()) if callable(root_is_alive_fn) else bool(root_is_alive_fn)
                if not root_alive:
                    continue
                if not bool(getattr(root, "deployed", False)):
                    continue
                root_is_in_reserves_fn = getattr(root, "is_in_reserves", None)
                if callable(root_is_in_reserves_fn) and bool(root_is_in_reserves_fn()):
                    continue
                if bool(getattr(root, "is_embarked", False)):
                    continue

                try:
                    models = list(root.get_attached_unit_models() or [])
                except Exception:
                    models = list(getattr(root, "models", []) or [])
                if not models:
                    continue

                for model in sorted(list(models or []), key=_model_sort_key):
                    model_is_alive_attr = getattr(model, "is_alive", True)
                    model_alive = bool(model_is_alive_attr() if callable(model_is_alive_attr) else model_is_alive_attr)
                    if not model_alive:
                        continue
                    model_id = str(get_entity_id(model) or "")
                    if model_id and model_id in pending_model_ids:
                        continue
                    source_unit = getattr(model, "parent_unit", None) or root
                    spec_fn = getattr(source_unit, "model_start_fight_phase_engagement_mortal_table_specs", None)
                    specs = list(spec_fn(model) or []) if callable(spec_fn) else []
                    if not specs:
                        continue
                    for spec in list(specs or []):
                        engagement_scope = str(spec.get("engagement_scope", "unit") or "unit").strip().lower() or "unit"
                        candidates = []
                        seen_targets: set[str] = set()
                        for enemy_root in list(enemy_roots or []):
                            if enemy_root is None:
                                continue
                            enemy_id = str(get_entity_id(enemy_root) or "")
                            if not enemy_id or enemy_id in seen_targets:
                                continue
                            seen_targets.add(enemy_id)
                            if engagement_scope == "model":
                                if not model_within_engagement_range_of_unit(model, enemy_root):
                                    continue
                            else:
                                try:
                                    if not bool(getattr(self.map, "is_within_engagement_range")(root, enemy_root)):
                                        continue
                                except Exception:
                                    continue
                            candidates.append(enemy_root)
                        if not candidates:
                            continue

                        ability_name = (
                            str(spec.get("source", "") or "Fight phase engagement mortal table").strip()
                            or "Fight phase engagement mortal table"
                        )
                        ability_key = (
                            str(spec.get("ability_key", "") or "fight_phase_engagement_mortal_table").strip().lower()
                            or "fight_phase_engagement_mortal_table"
                        )
                        options = []
                        candidate_ids = []
                        for cand in sorted(list(candidates or []), key=_unit_sort_key):
                            target_id = str(get_entity_id(cand) or "")
                            if not target_id:
                                continue
                            candidate_ids.append(target_id)
                            options.append(
                                DecisionOption.create(
                                    str(getattr(cand, "name", "Unit") or "Unit"),
                                    payload={"target_unit_id": target_id},
                                )
                            )
                        if not options:
                            continue

                        self.request_decision(
                            DecisionRequest.create(
                                DECISION_CHOOSE_QUARRY,
                                f"{ability_name}: select one enemy unit within Engagement Range.",
                                player_id=getattr(p, "id", None),
                                options=options,
                                context={
                                    "ability": str(spec.get("context_ability", "") or "fight_phase_select_engagement_mortal_table"),
                                    "ability_name": ability_name,
                                    "ability_key": ability_key,
                                    "phase_name": pname,
                                    "turn": int(current_turn),
                                    "source_unit_id": str(get_entity_id(source_unit) or ""),
                                    "unit_id": root_id,
                                    "model_id": model_id,
                                    "engagement_only": True,
                                    "engagement_scope": engagement_scope,
                                    "candidate_unit_ids": list(candidate_ids),
                                    "roll_bonus_per_models": int(spec.get("roll_bonus_per_models", 0) or 0),
                                    "roll_bonus_per_step": int(spec.get("roll_bonus_per_step", 0) or 0),
                                    "results": list(spec.get("results", []) or []),
                                },
                            )
                        )
                        if model_id:
                            pending_model_ids.add(model_id)
                        break

    def _on_phase_start_fight_phase_select_enemy_melee_hit_penalty(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase: select one enemy unit in Engagement Range to suffer a melee hit-roll penalty."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        queue_fn = getattr(self, "_queue_start_fight_phase_select_enemy_melee_hit_penalty", None)
        if not callable(queue_fn):
            return

        from ...utility.aura_utils import model_within_engagement_range_of_unit

        def _unit_sort_key(unit):
            unit_id = str(get_entity_id(unit) or "").strip()
            if unit_id:
                return unit_id
            return str(getattr(unit, "name", "") or "")

        def _model_sort_key(model):
            model_id = str(get_entity_id(model) or "").strip()
            if model_id:
                return model_id
            return str(getattr(model, "name", "") or "")

        try:
            current_turn = int(getattr(self, "turn", 0) or 0)
        except (TypeError, ValueError):
            current_turn = 0

        for p in list(getattr(self, "players", []) or []):
            if p is None:
                continue
            army = p.get_army()
            if army is None:
                continue
            enemy_roots = list(self._collect_enemy_unit_roots(p) or [])
            if not enemy_roots:
                continue

            seen_roots: set[str] = set()
            for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
                if unit is None:
                    continue
                root = unit.get_attached_unit_root() if hasattr(unit, "get_attached_unit_root") else unit
                if root is None:
                    continue
                root_id = str(get_entity_id(root) or "").strip()
                if not root_id or root_id in seen_roots:
                    continue
                seen_roots.add(root_id)
                root_is_alive_fn = getattr(root, "is_alive", None)
                root_alive = bool(root_is_alive_fn()) if callable(root_is_alive_fn) else bool(root_is_alive_fn)
                if not root_alive:
                    continue
                if not bool(getattr(root, "deployed", False)):
                    continue
                root_is_in_reserves_fn = getattr(root, "is_in_reserves", None)
                if callable(root_is_in_reserves_fn) and bool(root_is_in_reserves_fn()):
                    continue
                if bool(getattr(root, "is_embarked", False)):
                    continue

                spec_fn = getattr(root, "model_start_fight_phase_select_enemy_melee_hit_penalty_specs", None)
                if not callable(spec_fn):
                    continue
                models = (
                    list(root.get_attached_unit_models() or [])
                    if hasattr(root, "get_attached_unit_models")
                    else list(getattr(root, "models", []) or [])
                )
                if not models:
                    continue

                for model in sorted(list(models or []), key=_model_sort_key):
                    model_is_alive_attr = getattr(model, "is_alive", True)
                    model_alive = bool(model_is_alive_attr() if callable(model_is_alive_attr) else model_is_alive_attr)
                    if not model_alive:
                        continue
                    specs = list(spec_fn(model) or [])
                    if not specs:
                        continue
                    source_unit = getattr(model, "parent_unit", None) or root
                    for spec in list(specs or []):
                        ability_key = str(spec.get("ability_key", "") or "").strip().lower()
                        once_per_turn = bool(spec.get("once_per_turn", False))
                        if once_per_turn and ability_key and current_turn > 0:
                            has_used_fn = getattr(model, "has_used_once_per_battle_round", None)
                            if callable(has_used_fn) and bool(has_used_fn(ability_key, battle_round=int(current_turn))):
                                continue

                        candidates: list = []
                        for enemy_root in list(enemy_roots or []):
                            if enemy_root is None:
                                continue
                            if model_within_engagement_range_of_unit(model, enemy_root):
                                candidates.append(enemy_root)
                        if not candidates:
                            continue
                        queue_fn(
                            player=p,
                            source_unit=source_unit,
                            model=model,
                            candidates=list(candidates),
                            spec=dict(spec),
                            phase_name=pname,
                        )

    def _on_phase_start_paragon_of_sanctity(self, player=None, phase=None, **_kwargs) -> None:
        """Warpbane Task Force: optional once-per-battle Hallowed Ground proxy selection."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if not pname:
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        queue = getattr(self, "decision_queue", None)
        pending_source_ids: set[str] = set()
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                    continue
                ctx = dict(getattr(req, "context", {}) or {})
                if str(ctx.get("ability", "") or "") != "paragon_of_sanctity":
                    continue
                sid = str(ctx.get("source_unit_id", "") or "")
                if sid:
                    pending_source_ids.add(sid)

        def _unit_sort_key(unit) -> str:
            return str(get_entity_id(unit) or "")

        game_map = getattr(self, "map", None)
        for p in list(getattr(self, "players", []) or []):
            if p is None:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue
            gk_mgr = getattr(army, "grey_knights_detachments", None)
            if gk_mgr is None or not bool(getattr(gk_mgr, "is_warpbane_task_force", lambda: False)()):
                continue

            seen_roots: set[str] = set()
            for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
                if unit is None:
                    continue
                root = unit.get_attached_unit_root() if hasattr(unit, "get_attached_unit_root") else unit
                if root is None:
                    continue
                root_id = str(get_entity_id(root) or "")
                if not root_id or root_id in seen_roots:
                    continue
                seen_roots.add(root_id)

                if root_id in pending_source_ids:
                    continue
                if not bool(getattr(root, "is_alive", lambda: False)()):
                    continue
                if not bool(getattr(root, "deployed", False)):
                    continue
                if bool(getattr(root, "is_in_reserves", lambda: False)()):
                    continue
                if bool(getattr(root, "is_embarked", False)) or getattr(root, "embarked_in", None) is not None:
                    continue

                sr = getattr(root, "special_rules", None)
                if not isinstance(sr, dict) or not sr.get("enhancement_paragon_of_sanctity"):
                    continue
                ability_key = str(sr.get("enhancement_paragon_of_sanctity_once_key", "") or "paragon_of_sanctity").strip().lower()
                if not ability_key:
                    ability_key = "paragon_of_sanctity"
                if root.has_used_unit_once_per_battle(ability_key):
                    continue

                get_bearer = getattr(root, "_get_enhancement_bearer_model", None)
                if not callable(get_bearer):
                    continue
                bearer = get_bearer()
                if bearer is None or not getattr(bearer, "is_alive", True):
                    continue

                candidates = []
                candidate_seen: set[str] = set()
                for cand in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
                    if cand is None:
                        continue
                    cand_root = cand.get_attached_unit_root() if hasattr(cand, "get_attached_unit_root") else cand
                    if cand_root is None:
                        continue
                    cid = str(get_entity_id(cand_root) or "")
                    if not cid or cid in candidate_seen:
                        continue
                    candidate_seen.add(cid)
                    if not bool(getattr(cand_root, "is_alive", lambda: False)()):
                        continue
                    if not bool(getattr(cand_root, "deployed", False)):
                        continue
                    if bool(getattr(cand_root, "is_in_reserves", lambda: False)()):
                        continue
                    if bool(getattr(cand_root, "is_embarked", False)) or getattr(cand_root, "embarked_in", None) is not None:
                        continue
                    if not bool(getattr(gk_mgr, "_is_grey_knights_unit", lambda _u: False)(cand_root)):
                        continue
                    if not bool(getattr(root, "_model_within_range_of_unit", lambda *_a, **_k: False)(bearer, cand_root, 18.0)):
                        continue

                    visible = True
                    if game_map is not None and hasattr(game_map, "can_model_see_model"):
                        visible = False
                        target_models = list(getattr(cand_root, "get_models_for_collision", lambda: [])() or [])
                        if not target_models:
                            target_models = list(getattr(cand_root, "models", []) or [])
                        for target_model in target_models:
                            if target_model is None or not getattr(target_model, "is_alive", True):
                                continue
                            if game_map.can_model_see_model(bearer, target_model):
                                visible = True
                                break
                    if not visible:
                        continue
                    candidates.append(cand_root)

                if not candidates:
                    continue

                options = [DecisionOption.create("None", payload={"action": "skip"})]
                for cand in sorted(list(candidates), key=_unit_sort_key):
                    options.append(
                        DecisionOption.create(
                            str(getattr(cand, "name", "Unit") or "Unit"),
                            payload={"target_unit_id": get_entity_id(cand)},
                        )
                    )
                if len(options) <= 1:
                    continue

                request = DecisionRequest.create(
                    DECISION_CHOOSE_QUARRY,
                    "Paragon of Sanctity: select one friendly GREY KNIGHTS unit within 18\" and visible (or None).",
                    player_id=getattr(p, "id", None),
                    options=options,
                    context={
                        "ability": "paragon_of_sanctity",
                        "ability_name": "Paragon of Sanctity",
                        "phase": pname.replace("_", " ").title(),
                        "source_unit_id": root_id,
                        "unit_id": root_id,
                        "model_id": str(get_entity_id(bearer) or ""),
                        "ability_key": ability_key,
                        "range": 18,
                        "optional": True,
                    },
                )
                self.request_decision(request)

    def _on_phase_start_blinding_spray(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase start: optional once-per-battle Blinding Spray selection (single dialog with None)."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        from ..decision_kinds import DECISION_CHOOSE_QUARRY
        from ..decisions import DecisionOption, DecisionRequest

        queue = getattr(self, "decision_queue", None)
        pending_players: set[str] = set()
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                    continue
                ctx = dict(getattr(req, "context", {}) or {})
                if str(ctx.get("ability", "") or "") != "blinding_spray":
                    continue
                pid = str(getattr(req, "player_id", "") or "")
                if pid:
                    pending_players.add(pid)

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        def _model_sort_key(m):
            try:
                return str(get_entity_id(m))
            except Exception:
                return str(getattr(m, "name", "") or "")

        def _unit_has_keyword(unit, keyword: str) -> bool:
            kw = str(keyword or "").strip().upper()
            if unit is None or not kw:
                return False
            has_any = getattr(unit, "has_any_keyword", None)
            if callable(has_any):
                try:
                    return bool(has_any(kw))
                except Exception:
                    pass
            try:
                all_keywords = list(getattr(unit, "keywords", []) or []) + list(getattr(unit, "faction_keywords", []) or [])
            except Exception:
                all_keywords = []
            normalized = {str(v or "").strip().upper() for v in all_keywords}
            return kw in normalized

        def _model_alive(model) -> bool:
            if model is None:
                return False
            try:
                alive_attr = getattr(model, "is_alive", True)
                return bool(alive_attr() if callable(alive_attr) else alive_attr)
            except Exception:
                return False

        for p in list(getattr(self, "players", []) or []):
            if p is None:
                continue
            pid = str(getattr(p, "id", "") or "")
            if pid and pid in pending_players:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue

            seen_roots: set[str] = set()
            seen_models: set[str] = set()
            eligible: list[dict] = []

            for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None:
                    continue
                rid = str(get_entity_id(root) or "")
                if not rid or rid in seen_roots:
                    continue
                seen_roots.add(rid)
                if not bool(getattr(root, "is_alive", lambda: False)()):
                    continue
                if not bool(getattr(root, "deployed", False)):
                    continue
                try:
                    if root.is_in_reserves() or root.is_embarked:
                        continue
                except Exception:
                    pass

                try:
                    models = list(root.get_attached_unit_models() or [])
                except Exception:
                    models = list(getattr(root, "models", []) or [])
                for model in sorted([m for m in list(models or []) if getattr(m, "is_alive", False)], key=_model_sort_key):
                    mid = str(get_entity_id(model) or "")
                    if not mid or mid in seen_models:
                        continue
                    spec_fn = getattr(root, "model_start_fight_phase_blinding_spray_specs", None)
                    specs = list(spec_fn(model) or []) if callable(spec_fn) else []
                    if not specs:
                        continue
                    spec = dict(specs[0] or {})
                    ability_key = str(spec.get("ability_key", "") or "").strip().lower()
                    if not ability_key:
                        ability_key = f"blinding_spray:{mid}"
                    if getattr(model, "has_used_once_per_battle", lambda _k: False)(ability_key):
                        continue
                    seen_models.add(mid)
                    eligible.append(
                        {
                            "model_id": mid,
                            "model_name": str(getattr(model, "name", "Model") or "Model"),
                            "unit_id": rid,
                            "unit_name": str(getattr(root, "name", "Unit") or "Unit"),
                            "ability_key": ability_key,
                            "ability_name": str(spec.get("source", "") or "Blinding Spray").strip() or "Blinding Spray",
                        }
                    )

            if not eligible:
                continue

            options = [DecisionOption.create("None", payload={"action": "skip"})]
            for entry in sorted(list(eligible), key=lambda e: str(e.get("model_id", ""))):
                options.append(
                    DecisionOption.create(
                        f"{entry['model_name']} ({entry['unit_name']})",
                        payload={
                            "model_id": entry["model_id"],
                            "unit_id": entry["unit_id"],
                            "source_unit_id": entry["unit_id"],
                            "ability_key": entry["ability_key"],
                            "ability_name": entry["ability_name"],
                        },
                    )
                )
            if len(options) <= 1:
                continue

            request = DecisionRequest.create(
                DECISION_CHOOSE_QUARRY,
                "Blinding Spray: select one model to activate this phase (or None).",
                player_id=getattr(p, "id", None),
                options=options,
                context={
                    "ability": "blinding_spray",
                    "ability_name": "Blinding Spray",
                    "phase": "Fight phase",
                    "optional": True,
                },
            )
            self.request_decision(request)

    def _on_phase_start_decoy_targets(self, player=None, phase=None, **_kwargs) -> None:
        """Movement phase start: optional Decoy Targets selection (single dialog with None)."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        from ...utility.aura_utils import model_within_engagement_range_of_unit
        from ..decision_kinds import DECISION_CHOOSE_QUARRY
        from ..decisions import DecisionOption, DecisionRequest

        queue = getattr(self, "decision_queue", None)
        pending_source_unit_ids: set[str] = set()
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                    continue
                ctx = dict(getattr(req, "context", {}) or {})
                if str(ctx.get("ability", "") or "") != "decoy_targets":
                    continue
                src_id = str(ctx.get("source_unit_id", "") or ctx.get("unit_id", "") or "")
                if src_id:
                    pending_source_unit_ids.add(src_id)

        army = self._get_player_army(player)
        if army is None:
            return

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        def _model_sort_key(m):
            try:
                return str(get_entity_id(m))
            except Exception:
                return str(getattr(m, "name", "") or "")

        def _model_alive(model) -> bool:
            if model is None:
                return False
            try:
                alive_attr = getattr(model, "is_alive", True)
                return bool(alive_attr() if callable(alive_attr) else alive_attr)
            except Exception:
                return False

        try:
            current_turn = int(getattr(self, "turn", 0) or 0)
        except Exception:
            current_turn = 0

        seen_source_roots: set[str] = set()
        for source_unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
            if source_unit is None:
                continue
            try:
                source_root = source_unit.get_attached_unit_root()
            except Exception:
                source_root = source_unit
            if source_root is None:
                continue
            source_root_id = str(get_entity_id(source_root) or "")
            if not source_root_id or source_root_id in seen_source_roots:
                continue
            seen_source_roots.add(source_root_id)
            if source_root_id in pending_source_unit_ids:
                continue
            if not self._unit_on_battlefield_for_reposition(source_root):
                continue

            try:
                source_members = list(source_root.get_attached_unit_members() or [])
            except Exception:
                source_members = [source_root]
            if not source_members:
                source_members = [source_root]

            enhancement_source = None
            enhancement_sr = None
            for member in list(source_members or []):
                if member is None:
                    continue
                sr = getattr(member, "special_rules", None)
                if not isinstance(sr, dict):
                    continue
                if not bool(sr.get("enhancement_decoy_targets", False)):
                    continue
                enhancement_source = member
                enhancement_sr = sr
                break
            if enhancement_source is None or not isinstance(enhancement_sr, dict):
                continue

            try:
                max_uses = int(enhancement_sr.get("enhancement_decoy_targets_max_uses", 2) or 2)
            except Exception:
                max_uses = 2
            if max_uses <= 0:
                continue
            try:
                used_count = int(enhancement_sr.get("enhancement_decoy_targets_used_count", 0) or 0)
            except Exception:
                used_count = 0
            if used_count >= max_uses:
                continue
            try:
                per_round_limit = int(enhancement_sr.get("enhancement_decoy_targets_per_battle_round_limit", 1) or 1)
            except Exception:
                per_round_limit = 1
            if per_round_limit <= 0:
                continue
            try:
                used_round = int(enhancement_sr.get("enhancement_decoy_targets_used_battle_round", 0) or 0)
            except Exception:
                used_round = 0
            if used_round == current_turn:
                try:
                    round_count = int(
                        enhancement_sr.get("enhancement_decoy_targets_used_this_battle_round_count", 0) or 0
                    )
                except Exception:
                    round_count = 0
            else:
                round_count = 0
            if round_count >= per_round_limit:
                continue

            bearer_model = None
            bearer_model_id = str(enhancement_sr.get("enhancement_bearer_model_id", "") or "")
            if bearer_model_id:
                for model in list(getattr(enhancement_source, "models", []) or []):
                    model_id = str(get_entity_id(model) or getattr(model, "id", getattr(model, "_id", "")) or "")
                    if model_id == bearer_model_id:
                        bearer_model = model
                        break
            if bearer_model is None:
                get_bearer = getattr(enhancement_source, "_get_enhancement_bearer_model", None)
                if callable(get_bearer):
                    try:
                        bearer_model = get_bearer()
                    except Exception:
                        bearer_model = None
            if not _model_alive(bearer_model):
                continue
            bearer_model_id = str(
                get_entity_id(bearer_model) or getattr(bearer_model, "id", getattr(bearer_model, "_id", "")) or ""
            )
            if not bearer_model_id:
                continue

            try:
                models = [m for m in list(getattr(source_root, "models", []) or []) if _model_alive(m)]
            except Exception:
                models = []
            if len(models) != 1:
                continue

            candidate_entries: list[dict] = []
            seen_target_models: set[str] = set()
            seen_target_roots: set[str] = set()
            for target_unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
                if target_unit is None:
                    continue
                try:
                    target_root = target_unit.get_attached_unit_root()
                except Exception:
                    target_root = target_unit
                if target_root is None:
                    continue
                target_root_id = str(get_entity_id(target_root) or "")
                if not target_root_id or target_root_id in seen_target_roots:
                    continue
                seen_target_roots.add(target_root_id)
                if not self._unit_on_battlefield_for_reposition(target_root):
                    continue
                has_infantry = False
                try:
                    has_infantry = bool(target_root.has_any_keyword("INFANTRY"))
                except Exception:
                    try:
                        has_infantry = bool(target_root.has_keyword("INFANTRY"))
                    except Exception:
                        has_infantry = False
                if not has_infantry:
                    continue

                try:
                    target_models = list(target_root.get_attached_unit_models() or [])
                except Exception:
                    target_models = list(getattr(target_root, "models", []) or [])
                for target_model in sorted(
                    [m for m in list(target_models or []) if _model_alive(m)],
                    key=_model_sort_key,
                ):
                    target_model_id = str(
                        get_entity_id(target_model)
                        or getattr(target_model, "id", getattr(target_model, "_id", ""))
                        or ""
                    )
                    if not target_model_id or target_model_id in seen_target_models:
                        continue
                    seen_target_models.add(target_model_id)
                    if target_model_id == bearer_model_id:
                        continue
                    engaged = False
                    game_map = getattr(self, "map", None)
                    if game_map is not None and hasattr(game_map, "get_enemy_units"):
                        try:
                            enemy_units = list(game_map.get_enemy_units(target_root) or [])
                        except Exception:
                            enemy_units = []
                    else:
                        enemy_units = []
                    for enemy in list(enemy_units or []):
                        if enemy is None:
                            continue
                        try:
                            enemy_root = enemy.get_attached_unit_root()
                        except Exception:
                            enemy_root = enemy
                        if enemy_root is None:
                            continue
                        if not self._unit_on_battlefield_for_reposition(enemy_root):
                            continue
                        if model_within_engagement_range_of_unit(target_model, enemy_root):
                            engaged = True
                            break
                    if engaged:
                        continue

                    candidate_entries.append(
                        {
                            "target_model_id": target_model_id,
                            "target_model_name": str(getattr(target_model, "name", "Model") or "Model"),
                            "target_unit_id": target_root_id,
                            "target_unit_name": str(getattr(target_root, "name", "Unit") or "Unit"),
                        }
                    )

            if not candidate_entries:
                continue

            enhancement = getattr(enhancement_source, "enhancement", None)
            ability_name = str(getattr(enhancement, "name", "") or "Decoy Targets").strip() or "Decoy Targets"
            options = [DecisionOption.create("None", payload={"action": "skip"})]
            for entry in sorted(list(candidate_entries), key=lambda item: str(item.get("target_model_id", ""))):
                options.append(
                    DecisionOption.create(
                        f"{entry['target_model_name']} ({entry['target_unit_name']})",
                        payload={
                            "source_unit_id": source_root_id,
                            "source_model_id": bearer_model_id,
                            "target_model_id": entry["target_model_id"],
                            "target_unit_id": entry["target_unit_id"],
                            "ability_name": ability_name,
                        },
                    )
                )
            if len(options) <= 1:
                continue

            source_name = str(getattr(bearer_model, "name", "Model") or "Model")
            request = DecisionRequest.create(
                DECISION_CHOOSE_QUARRY,
                f"{ability_name}: select one other friendly INFANTRY model for {source_name} (or None).",
                player_id=getattr(player, "id", None),
                options=options,
                context={
                    "ability": "decoy_targets",
                    "ability_name": ability_name,
                    "phase": "Movement phase",
                    "source_unit_id": source_root_id,
                    "source_model_id": bearer_model_id,
                    "max_uses": int(max_uses),
                    "per_battle_round_limit": int(per_round_limit),
                    "optional": True,
                },
            )
            self.request_decision(request)

    def _on_phase_start_vanguard_of_dark_city(self, player=None, phase=None, **_kwargs) -> None:
        """Command phase start: Raider Vanguard of the Dark City mode selection."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        army = self._get_player_army(player)
        if army is None:
            return

        queue = getattr(self, "decision_queue", None)
        pending_sources: set[str] = set()
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                    continue
                ctx = dict(getattr(req, "context", {}) or {})
                if str(ctx.get("ability", "") or "") != "vanguard_of_dark_city":
                    continue
                source_id = str(ctx.get("source_unit_id", "") or "")
                if source_id:
                    pending_sources.add(source_id)

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        seen_roots: set[str] = set()
        for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            if root is None:
                continue
            root_id = str(get_entity_id(root) or "")
            if not root_id or root_id in seen_roots:
                continue
            seen_roots.add(root_id)
            if root_id in pending_sources:
                continue
            if not bool(getattr(root, "is_alive", lambda: False)()):
                continue
            if not bool(getattr(root, "deployed", False)):
                continue
            try:
                if root.is_in_reserves() or root.is_embarked:
                    continue
            except Exception:
                pass
            has_vanguard = getattr(root, "has_vanguard_of_dark_city", None)
            if not callable(has_vanguard) or not bool(has_vanguard()):
                continue

            options = [
                DecisionOption.create(
                    "Masters of the Shadowed Sky",
                    payload={"vanguard_mode": "masters_of_the_shadowed_sky"},
                ),
                DecisionOption.create(
                    "Speed of the Kill",
                    payload={"vanguard_mode": "speed_of_the_kill"},
                ),
                DecisionOption.create(
                    "Visions of Butchery",
                    payload={"vanguard_mode": "visions_of_butchery"},
                ),
            ]
            request = DecisionRequest.create(
                DECISION_CHOOSE_QUARRY,
                "Vanguard of the Dark City: select one mode for this model until your next Command phase.",
                player_id=getattr(player, "id", None),
                options=options,
                context={
                    "ability": "vanguard_of_dark_city",
                    "ability_name": "Vanguard of the Dark City",
                    "phase": "Command phase",
                    "source_unit_id": root_id,
                    "unit_id": root_id,
                    "optional": False,
                },
            )
            self.request_decision(request)

    def _on_phase_start_space_marines_temple_relics(self, player=None, phase=None, **_kwargs) -> None:
        """Command phase start: Chaplain Grimaldus selects one Temple Relic while a Cenobyte Servitor remains."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        army = self._get_player_army(player)
        if army is None:
            return

        from ...rules.space_marines_temple_relics import (
            KEY_BANNER_OF_THE_EMPEROR_VICTORIOUS,
            KEY_COLUMN_FROM_THE_MAJOR_ALTAR,
            KEY_WATER_FROM_THE_STOUP_OF_ELUCIDATION,
            clear_active_temple_relics,
        )

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        queue = getattr(self, "decision_queue", None)
        pending_sources: set[str] = set()
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                    continue
                ctx = dict(getattr(req, "context", {}) or {})
                if str(ctx.get("ability", "") or "") != "space_marines_temple_relics":
                    continue
                source_id = str(ctx.get("source_unit_id", "") or "")
                if source_id:
                    pending_sources.add(source_id)

        seen_roots: set[str] = set()
        for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            if root is None:
                continue
            root_id = str(get_entity_id(root) or "")
            if not root_id or root_id in seen_roots:
                continue
            seen_roots.add(root_id)
            if not bool(getattr(root, "is_alive", lambda: False)()):
                continue
            if not bool(getattr(root, "deployed", False)):
                continue
            try:
                if root.is_in_reserves() or root.is_embarked:
                    continue
            except Exception:
                pass

            source_unit_fn = getattr(root, "get_temple_relics_source_unit", None)
            source_unit = source_unit_fn() if callable(source_unit_fn) else None
            if source_unit is None:
                continue

            clear_active_temple_relics(root)
            refresh_modifiers = getattr(root, "_refresh_bearer_unit_common_modifiers", None)
            if callable(refresh_modifiers):
                refresh_modifiers()

            if root_id in pending_sources:
                continue
            can_select_fn = getattr(root, "temple_relics_can_select", None)
            if not callable(can_select_fn) or not bool(can_select_fn()):
                continue

            source_member_id = str(get_entity_id(source_unit) or "")
            options = [
                DecisionOption.create(
                    "Banner of the Emperor Victorious",
                    payload={
                        "temple_relics_mode": "banner_of_the_emperor_victorious",
                        "temple_relics_mode_key": str(KEY_BANNER_OF_THE_EMPEROR_VICTORIOUS),
                    },
                ),
                DecisionOption.create(
                    "Column from the Major Altar",
                    payload={
                        "temple_relics_mode": "column_from_the_major_altar",
                        "temple_relics_mode_key": str(KEY_COLUMN_FROM_THE_MAJOR_ALTAR),
                    },
                ),
                DecisionOption.create(
                    "Water from the Stoup of Elucidation",
                    payload={
                        "temple_relics_mode": "water_from_the_stoup_of_elucidation",
                        "temple_relics_mode_key": str(KEY_WATER_FROM_THE_STOUP_OF_ELUCIDATION),
                    },
                ),
            ]
            request = DecisionRequest.create(
                DECISION_CHOOSE_QUARRY,
                "Temple Relics: select one relic ability for Chaplain Grimaldus until your next Command phase.",
                player_id=getattr(player, "id", None),
                options=options,
                context={
                    "ability": "space_marines_temple_relics",
                    "ability_name": "Temple Relics",
                    "phase": "Command phase",
                    "source_unit_id": root_id,
                    "source_member_unit_id": source_member_id,
                    "unit_id": root_id,
                    "allowed_modes": [
                        "banner_of_the_emperor_victorious",
                        "column_from_the_major_altar",
                        "water_from_the_stoup_of_elucidation",
                    ],
                    "optional": False,
                },
            )
            self.request_decision(request)

    def _on_phase_start_battle_protocols(self, player=None, phase=None, **_kwargs) -> None:
        """Command phase start: Cybernetica Datasmith Battle Protocols handling."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        try:
            battle_round = int(getattr(self, "turn", 0) or 0)
        except Exception:
            battle_round = 0

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        # Start of battle: if a Datasmith is leading KASTELAN ROBOTS, that unit enters Aegis Protocol.
        if battle_round == 1 and not bool(getattr(self, "_battle_protocols_start_of_battle_initialized", False)):
            for p in list(getattr(self, "players", []) or []):
                if p is None:
                    continue
                army_obj = self._get_player_army(p)
                if army_obj is None:
                    continue
                seen_roots: set[str] = set()
                for unit in sorted(list(getattr(army_obj, "units", []) or []), key=_unit_sort_key):
                    if unit is None:
                        continue
                    try:
                        root = unit.get_attached_unit_root()
                    except Exception:
                        root = unit
                    if root is None:
                        continue
                    root_id = str(get_entity_id(root) or "")
                    if root_id and root_id in seen_roots:
                        continue
                    if root_id:
                        seen_roots.add(root_id)
                    if not bool(getattr(root, "is_alive", lambda: False)()):
                        continue
                    eligible_fn = getattr(root, "battle_protocols_source_is_eligible", None)
                    if not callable(eligible_fn) or not bool(eligible_fn()):
                        continue
                    sr = getattr(root, "special_rules", None)
                    if not isinstance(sr, dict):
                        sr = {}
                    current_mode = str(sr.get("battle_protocols_selected_mode", "") or "").strip().lower()
                    if current_mode in ("protector_protocol", "conqueror_protocol", "aegis_protocol"):
                        continue
                    sr = dict(sr)
                    sr["battle_protocols_selected_mode"] = "aegis_protocol"
                    sr["battle_protocols_selected_mode_key"] = "AEGIS_PROTOCOL"
                    root.special_rules = sr
                    invalidate = getattr(root, "_invalidate_ability_activity_cache", None)
                    if callable(invalidate):
                        invalidate()
            self._battle_protocols_start_of_battle_initialized = True

        army = self._get_player_army(player)
        if army is None:
            return

        queue = getattr(self, "decision_queue", None)
        pending_sources: set[str] = set()
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                    continue
                ctx = dict(getattr(req, "context", {}) or {})
                if str(ctx.get("ability", "") or "") != "battle_protocols":
                    continue
                source_id = str(ctx.get("source_unit_id", "") or "")
                if source_id:
                    pending_sources.add(source_id)

        seen_roots: set[str] = set()
        for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            if root is None:
                continue
            root_id = str(get_entity_id(root) or "")
            if not root_id or root_id in seen_roots:
                continue
            seen_roots.add(root_id)
            if root_id in pending_sources:
                continue
            if not bool(getattr(root, "is_alive", lambda: False)()):
                continue
            if not bool(getattr(root, "deployed", False)):
                continue
            try:
                if root.is_in_reserves() or root.is_embarked:
                    continue
            except Exception:
                pass
            eligible_fn = getattr(root, "battle_protocols_source_is_eligible", None)
            if not callable(eligible_fn) or not bool(eligible_fn()):
                continue

            options = [
                DecisionOption.create("None (keep current protocol)", payload={"battle_protocols_mode": "none"}),
                DecisionOption.create("Protector Protocol", payload={"battle_protocols_mode": "protector_protocol"}),
                DecisionOption.create("Conqueror Protocol", payload={"battle_protocols_mode": "conqueror_protocol"}),
                DecisionOption.create("Aegis Protocol", payload={"battle_protocols_mode": "aegis_protocol"}),
            ]
            current_mode_fn = getattr(root, "get_battle_protocols_selected_mode", None)
            current_mode = str(current_mode_fn() if callable(current_mode_fn) else "").strip().lower()

            request = DecisionRequest.create(
                DECISION_CHOOSE_QUARRY,
                "Battle Protocols: select one protocol for this unit (or None to keep the current protocol).",
                player_id=getattr(player, "id", None),
                options=options,
                context={
                    "ability": "battle_protocols",
                    "ability_name": "Battle Protocols",
                    "phase": "Command phase",
                    "source_unit_id": root_id,
                    "unit_id": root_id,
                    "allowed_modes": [
                        "none",
                        "protector_protocol",
                        "conqueror_protocol",
                        "aegis_protocol",
                    ],
                    "current_mode": current_mode,
                    "optional": True,
                },
            )
            self.request_decision(request)

    def _on_phase_start_canticles_of_the_omnissiah(self, player=None, phase=None, **_kwargs) -> None:
        """Command phase start: Belisarius Cawl selects one Canticles of the Omnissiah mode."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        army = self._get_player_army(player)
        if army is None:
            return

        from ...rules.adeptus_mechanicus_canticles import (
            KEY_INVOCATION_OF_MACHINE_VENGEANCE,
            KEY_MANTRA_OF_DISCIPLINE,
            KEY_SHROUDPSALM,
            unit_has_canticles_of_the_omnissiah_ability,
        )

        owner_id = str(getattr(player, "id", "") or "")
        if not owner_id:
            return

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        # Expire previous Invocation of Machine Vengeance target marks at the start
        # of this player's Command phase.
        for p in list(getattr(self, "players", []) or []):
            if p is None:
                continue
            opp_army = self._get_player_army(p)
            if opp_army is None:
                continue
            seen_target_roots: set[str] = set()
            for unit in sorted(list(getattr(opp_army, "units", []) or []), key=_unit_sort_key):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None:
                    continue
                root_id = str(get_entity_id(root) or "")
                if root_id and root_id in seen_target_roots:
                    continue
                if root_id:
                    seen_target_roots.add(root_id)
                sr = getattr(root, "special_rules", None)
                if not isinstance(sr, dict):
                    continue
                if str(sr.get("canticles_machine_vengeance_owner", "") or "") != owner_id:
                    continue
                sr = dict(sr)
                for key in (
                    "canticles_machine_vengeance_active",
                    "canticles_machine_vengeance_owner",
                    "canticles_machine_vengeance_source_unit_id",
                    "canticles_machine_vengeance_source",
                    "canticles_machine_vengeance_keyword",
                ):
                    sr.pop(key, None)
                root.special_rules = sr

        queue = getattr(self, "decision_queue", None)
        pending_sources: set[str] = set()
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                    continue
                ctx = dict(getattr(req, "context", {}) or {})
                if str(ctx.get("ability", "") or "") != "canticles_of_the_omnissiah":
                    continue
                source_id = str(ctx.get("source_unit_id", "") or "")
                if source_id:
                    pending_sources.add(source_id)

        seen_roots: set[str] = set()
        for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            if root is None:
                continue
            root_id = str(get_entity_id(root) or "")
            if not root_id or root_id in seen_roots:
                continue
            seen_roots.add(root_id)
            if root_id in pending_sources:
                continue
            if not bool(getattr(root, "is_alive", lambda: False)()):
                continue
            if not bool(getattr(root, "deployed", False)):
                continue
            try:
                if root.is_in_reserves() or root.is_embarked:
                    continue
            except Exception:
                pass
            if not bool(unit_has_canticles_of_the_omnissiah_ability(root)):
                continue

            # Active Canticles expire at the start of this unit's next Command phase.
            try:
                members = list(root.get_attached_unit_members() or [])
            except Exception:
                members = [root]
            if not members:
                members = [root]
            for member in list(members or []):
                sr = getattr(member, "special_rules", None)
                if not isinstance(sr, dict):
                    continue
                sr = dict(sr)
                changed = False
                for key in (
                    "canticles_of_the_omnissiah_selected_mode",
                    "canticles_of_the_omnissiah_selected_mode_key",
                    "canticles_machine_vengeance_target_unit_id",
                ):
                    if key in sr:
                        sr.pop(key, None)
                        changed = True
                if changed:
                    member.special_rules = sr
                    invalidate = getattr(member, "_invalidate_ability_activity_cache", None)
                    if callable(invalidate):
                        invalidate()

            options = [
                DecisionOption.create(
                    "Invocation of Machine Vengeance",
                    payload={
                        "canticles_mode": "invocation_of_machine_vengeance",
                        "canticles_mode_key": str(KEY_INVOCATION_OF_MACHINE_VENGEANCE),
                    },
                ),
                DecisionOption.create(
                    "Mantra of Discipline",
                    payload={
                        "canticles_mode": "mantra_of_discipline",
                        "canticles_mode_key": str(KEY_MANTRA_OF_DISCIPLINE),
                    },
                ),
                DecisionOption.create(
                    "Shroudpsalm (Aura)",
                    payload={
                        "canticles_mode": "shroudpsalm",
                        "canticles_mode_key": str(KEY_SHROUDPSALM),
                    },
                ),
            ]

            request = DecisionRequest.create(
                DECISION_CHOOSE_QUARRY,
                "Canticles of the Omnissiah: select one Canticle until your next Command phase.",
                player_id=getattr(player, "id", None),
                options=options,
                context={
                    "ability": "canticles_of_the_omnissiah",
                    "ability_name": "Canticles of the Omnissiah",
                    "phase": "Command phase",
                    "source_unit_id": root_id,
                    "unit_id": root_id,
                    "optional": False,
                },
            )
            self.request_decision(request)

    def _on_phase_start_tocsin_of_misery(self, player=None, phase=None, **_kwargs) -> None:
        """Opponent Command phase: below-Starting enemy units in range must take Battle-shock (Tocsin of Misery)."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        current_army = self._get_player_army(player)
        if current_army is None:
            return

        from ...utility.event_bus import append_action

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        def _model_sort_key(m):
            try:
                return str(get_entity_id(m))
            except Exception:
                return str(getattr(m, "name", "") or "")

        def _apply_battleshock_test_modifier(target_root, modifier: int, reason: str) -> None:
            if int(modifier or 0) == 0:
                return
            sr = getattr(target_root, "special_rules", None)
            if not isinstance(sr, dict):
                sr = {}
            try:
                existing = int(sr.get("battle_shock_test_modifier", 0) or 0)
            except (TypeError, ValueError):
                existing = 0
            sr["battle_shock_test_modifier"] = int(existing + int(modifier))
            reasons = list(sr.get("battle_shock_test_modifier_reasons", []) or [])
            reason_text = str(reason or "").strip()
            if reason_text:
                reasons.append(reason_text)
            sr["battle_shock_test_modifier_reasons"] = reasons
            target_root.special_rules = sr

        try:
            turn = int(getattr(self, "turn", 0) or 0)
        except Exception:
            turn = 0

        tested_targets: set[str] = set()

        for opp in list(getattr(self, "players", []) or []):
            if opp is None or opp is player:
                continue
            opp_army = self._get_player_army(opp)
            if opp_army is None:
                continue
            seen_source_roots: set[str] = set()
            for source_unit in sorted(list(getattr(opp_army, "units", []) or []), key=_unit_sort_key):
                if source_unit is None:
                    continue
                try:
                    source_root = source_unit.get_attached_unit_root()
                except Exception:
                    source_root = source_unit
                if source_root is None:
                    continue
                source_root_id = str(get_entity_id(source_root) or "")
                if not source_root_id or source_root_id in seen_source_roots:
                    continue
                seen_source_roots.add(source_root_id)
                if not bool(getattr(source_root, "is_alive", lambda: False)()):
                    continue
                if not bool(getattr(source_root, "deployed", False)):
                    continue
                try:
                    if source_root.is_in_reserves() or source_root.is_embarked:
                        continue
                except Exception:
                    pass

                try:
                    source_models = list(source_root.get_attached_unit_models() or [])
                except Exception:
                    source_models = list(getattr(source_root, "models", []) or [])
                source_models = [m for m in list(source_models or []) if getattr(m, "is_alive", False)]
                for source_model in sorted(source_models, key=_model_sort_key):
                    spec_fn = getattr(source_root, "model_opponent_command_phase_below_starting_battleshock_specs", None)
                    specs = list(spec_fn(source_model) or []) if callable(spec_fn) else []
                    if not specs:
                        continue
                    for spec in specs:
                        try:
                            range_value = float(int(spec.get("range", 0) or 0))
                        except (TypeError, ValueError):
                            range_value = 0.0
                        try:
                            test_penalty = int(spec.get("test_penalty", 0) or 0)
                        except (TypeError, ValueError):
                            test_penalty = 0
                        try:
                            psyker_penalty = int(spec.get("psyker_penalty", 0) or 0)
                        except (TypeError, ValueError):
                            psyker_penalty = 0
                        if range_value <= 0:
                            continue
                        source_name = str(spec.get("source", "") or "Tocsin of Misery").strip() or "Tocsin of Misery"

                        seen_targets_in_army: set[str] = set()
                        for target_unit in sorted(list(getattr(current_army, "units", []) or []), key=_unit_sort_key):
                            if target_unit is None:
                                continue
                            try:
                                target_root = target_unit.get_attached_unit_root()
                            except Exception:
                                target_root = target_unit
                            if target_root is None:
                                continue
                            target_id = str(get_entity_id(target_root) or "")
                            if not target_id or target_id in seen_targets_in_army or target_id in tested_targets:
                                continue
                            seen_targets_in_army.add(target_id)
                            if not bool(getattr(target_root, "is_alive", lambda: False)()):
                                continue
                            if not bool(getattr(target_root, "deployed", False)):
                                continue
                            try:
                                if target_root.is_in_reserves() or target_root.is_embarked:
                                    continue
                            except Exception:
                                pass
                            try:
                                if not target_root.is_below_starting_strength():
                                    continue
                            except Exception:
                                continue
                            try:
                                in_range = bool(source_root._model_within_range_of_unit(source_model, target_root, range_value))
                            except Exception:
                                in_range = False
                            if not in_range:
                                continue

                            if test_penalty > 0:
                                _apply_battleshock_test_modifier(
                                    target_root,
                                    -abs(int(test_penalty)),
                                    f"{source_name}: -{abs(int(test_penalty))}",
                                )

                            is_psyker = False
                            if psyker_penalty > 0:
                                try:
                                    is_psyker = bool(target_root.has_any_keyword("PSYKER"))
                                except Exception:
                                    try:
                                        is_psyker = bool(target_root.has_keyword("PSYKER"))
                                    except Exception:
                                        is_psyker = False
                            if is_psyker and psyker_penalty > 0:
                                _apply_battleshock_test_modifier(
                                    target_root,
                                    -abs(int(psyker_penalty)),
                                    f"{source_name}: -{abs(int(psyker_penalty))} vs PSYKER",
                                )

                            try:
                                target_root.take_battle_shock_test(int(turn or 1))
                            except Exception:
                                continue
                            append_action(
                                player,
                                f"{source_name}: {getattr(target_root, 'name', 'Unit')} takes a Battle-shock test.",
                            )
                            tested_targets.add(target_id)

    def _on_phase_start_soulless_horror(self, player=None, phase=None, **_kwargs) -> None:
        """Any Command phase: queue optional Soulless Horror activations."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        try:
            current_turn = int(getattr(self, "turn", 0) or 0)
        except (TypeError, ValueError):
            current_turn = 0
        current_turn_owner_id = str(getattr(player, "id", "") or "").strip()

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        def _model_sort_key(m):
            try:
                return str(get_entity_id(m))
            except Exception:
                return str(getattr(m, "name", "") or "")

        def _objective_sort_key(obj):
            try:
                return str(get_entity_id(obj))
            except (AttributeError, TypeError, ValueError):
                return str(getattr(obj, "name", "") or "")

        def _is_model_within_objective_selection_range(model, objective, *, range_value: float) -> bool:
            if model is None or objective is None:
                return False
            within_fn = getattr(self, "_model_within_range_of_objective_marker", None)
            if callable(within_fn):
                return bool(within_fn(model, objective, range_value=range_value))
            location = getattr(objective, "location", None)
            if location is None:
                return False
            get_location = getattr(model, "get_location", None)
            model_location = get_location() if callable(get_location) else None
            if not model_location or len(model_location) < 3:
                return False
            base_radius_fn = getattr(getattr(model, "model_base", None), "get_radius", None)
            try:
                base_radius = float(base_radius_fn() if callable(base_radius_fn) else 0.0)
            except (TypeError, ValueError):
                base_radius = 0.0
            try:
                mx = float(model_location[0])
                my = float(model_location[1])
                mz = float(model_location[2])
            except (TypeError, ValueError):
                return False
            if hasattr(location, "x") and hasattr(location, "y"):
                try:
                    ox = float(getattr(location, "x", 0.0) or 0.0)
                    oy = float(getattr(location, "y", 0.0) or 0.0)
                    oz = float(getattr(location, "z", 0.0) or 0.0)
                except (TypeError, ValueError):
                    return False
            elif isinstance(location, (tuple, list)) and len(location) >= 2:
                try:
                    ox = float(location[0])
                    oy = float(location[1])
                    oz = float(location[2]) if len(location) >= 3 else 0.0
                except (TypeError, ValueError):
                    return False
            else:
                return False
            dx = mx - ox
            dy = my - oy
            dz = mz - oz
            return ((dx * dx) + (dy * dy) + (dz * dz)) ** 0.5 <= float(range_value) + float(base_radius) + 1e-6

        def _collect_targeted_objective_ids_for_turn(turn: int, *, turn_owner_id: str = "") -> set[str]:
            if turn <= 0:
                return set()
            targeted: set[str] = set()
            normalized_turn_owner = str(turn_owner_id or "").strip()
            for owner in list(getattr(self, "players", []) or []):
                if owner is None:
                    continue
                owner_army = self._get_player_army(owner)
                if owner_army is None:
                    continue
                seen_owner_roots: set[str] = set()
                for owner_unit in list(getattr(owner_army, "units", []) or []):
                    if owner_unit is None:
                        continue
                    owner_get_root = getattr(owner_unit, "get_attached_unit_root", None)
                    owner_root = owner_get_root() if callable(owner_get_root) else owner_unit
                    if owner_root is None:
                        continue
                    owner_root_id = str(get_entity_id(owner_root) or "")
                    if owner_root_id and owner_root_id in seen_owner_roots:
                        continue
                    if owner_root_id:
                        seen_owner_roots.add(owner_root_id)
                    owner_sr = getattr(owner_root, "special_rules", None)
                    if not isinstance(owner_sr, dict):
                        continue
                    try:
                        used_turn = int(owner_sr.get("start_any_command_phase_objective_battleshock_turn", 0) or 0)
                    except (TypeError, ValueError):
                        used_turn = 0
                    if int(used_turn) != int(turn):
                        continue
                    used_turn_owner = str(
                        owner_sr.get("start_any_command_phase_objective_battleshock_turn_owner_id", "")
                        or owner_sr.get("start_any_command_phase_objective_battleshock_turn_owner", "")
                        or ""
                    ).strip()
                    if normalized_turn_owner and used_turn_owner and used_turn_owner != normalized_turn_owner:
                        continue
                    for objective_id in list(owner_sr.get("start_any_command_phase_objective_battleshock_objective_ids", []) or []):
                        objective_key = str(objective_id or "").strip()
                        if objective_key:
                            targeted.add(objective_key)
            return targeted

        objective_pool: list = []
        objective_seen: set[str] = set()
        for objective in list(getattr(getattr(self, "map", None), "objectives", []) or []):
            if objective is None:
                continue
            objective_id = str(get_entity_id(objective) or "").strip()
            if not objective_id or objective_id in objective_seen:
                continue
            location = getattr(objective, "location", None)
            if location is None:
                continue
            if bool(getattr(location, "removed", False)):
                continue
            objective_seen.add(objective_id)
            objective_pool.append(objective)
        objective_pool = sorted(list(objective_pool or []), key=_objective_sort_key)
        targeted_objective_ids = _collect_targeted_objective_ids_for_turn(
            int(current_turn),
            turn_owner_id=current_turn_owner_id,
        )

        for owner in sorted(list(getattr(self, "players", []) or []), key=lambda p: str(getattr(p, "id", "") or "")):
            if owner is None:
                continue
            army = self._get_player_army(owner)
            if army is None:
                continue
            ia_mgr = getattr(army, "imperial_agents_detachments", None)
            grant_fn = getattr(ia_mgr, "apply_extremis_sanction_extra_uses", None) if ia_mgr is not None else None

            seen_roots: set[str] = set()
            for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None:
                    continue
                root_id = str(get_entity_id(root) or "")
                if not root_id or root_id in seen_roots:
                    continue
                seen_roots.add(root_id)
                if not bool(getattr(root, "is_alive", lambda: False)()):
                    continue
                if not bool(getattr(root, "deployed", False)):
                    continue
                try:
                    if root.is_in_reserves() or root.is_embarked:
                        continue
                except Exception:
                    pass
                if callable(grant_fn):
                    grant_fn(root)

                try:
                    models = list(root.get_attached_unit_models() or [])
                except Exception:
                    models = list(getattr(root, "models", []) or [])
                for model in sorted([m for m in list(models or []) if getattr(m, "is_alive", False)], key=_model_sort_key):
                    objective_specs = root.model_start_any_command_phase_objective_battleshock_specs(model) or []
                    queue_objective_fn = getattr(self, "_queue_start_any_command_phase_objective_battleshock", None)
                    if objective_specs and callable(queue_objective_fn):
                        for objective_spec in list(objective_specs or []):
                            objective_ability_key = str(
                                objective_spec.get("ability_key", "") or "start_any_command_phase_objective_battleshock"
                            ).strip().lower()
                            if not objective_ability_key:
                                objective_ability_key = "start_any_command_phase_objective_battleshock"
                            if getattr(model, "has_used_once_per_battle", lambda _k: False)(objective_ability_key):
                                continue
                            try:
                                objective_selection_range = int(objective_spec.get("objective_selection_range", 0) or 0)
                            except (TypeError, ValueError):
                                objective_selection_range = 0
                            if objective_selection_range <= 0:
                                continue
                            per_objective_once_per_turn = bool(objective_spec.get("per_objective_once_per_turn", False))
                            candidate_objectives = []
                            for objective in list(objective_pool or []):
                                objective_id = str(get_entity_id(objective) or "").strip()
                                if not objective_id:
                                    continue
                                if per_objective_once_per_turn and objective_id in targeted_objective_ids:
                                    continue
                                if not _is_model_within_objective_selection_range(
                                    model,
                                    objective,
                                    range_value=float(objective_selection_range),
                                ):
                                    continue
                                candidate_objectives.append(objective)
                            if not candidate_objectives:
                                continue
                            source_unit = getattr(model, "parent_unit", None) or root
                            queue_objective_fn(
                                player=owner,
                                source_unit=source_unit,
                                model=model,
                                objectives=list(candidate_objectives),
                                spec=dict(objective_spec),
                                turn_owner_id=current_turn_owner_id,
                            )

                    specs = root.model_start_any_command_phase_battleshock_specs(model) or []
                    if not specs:
                        continue
                    for spec in list(specs or []):
                        ability_key = str(spec.get("ability_key", "") or "soulless_horror").strip().lower()
                        if not ability_key:
                            ability_key = "soulless_horror"
                        if getattr(model, "has_used_once_per_battle", lambda _k: False)(ability_key):
                            continue
                        try:
                            range_value = int(spec.get("range", 0) or 0)
                        except Exception:
                            range_value = 0
                        try:
                            penalty = int(spec.get("test_penalty", 0) or 0)
                        except Exception:
                            penalty = 0
                        try:
                            psyker_penalty = int(spec.get("psyker_test_penalty", 0) or 0)
                        except Exception:
                            psyker_penalty = 0
                        if range_value <= 0 or penalty <= 0:
                            continue
                        if psyker_penalty <= 0:
                            psyker_penalty = int(penalty)
                        ability_name = str(spec.get("source", "") or "Soulless Horror").strip() or "Soulless Horror"
                        ctx = {
                            "ability": "soulless_horror",
                            "ability_key": ability_key,
                            "ability_name": ability_name,
                            "phase": "Command phase",
                            "unit": getattr(root, "name", "") or "",
                            "unit_id": root_id,
                            "model": getattr(model, "name", "") or "",
                            "model_id": str(get_entity_id(model) or ""),
                            "range": int(range_value),
                            "test_penalty": int(penalty),
                            "psyker_test_penalty": int(psyker_penalty),
                        }
                        message = f"Activate {ability_name} for {getattr(model, 'name', 'Model')}?"
                        self._queue_optional_ability_confirmation(
                            player=owner,
                            ability_key="soulless_horror",
                            ability_name=ability_name,
                            message=message,
                            context=ctx,
                            payload={
                                "unit_id": root_id,
                                "model_id": str(get_entity_id(model) or ""),
                                "ability_key": ability_key,
                                "range": int(range_value),
                                "test_penalty": int(penalty),
                                "psyker_test_penalty": int(psyker_penalty),
                            },
                            instance_key=f"{str(get_entity_id(model) or '')}:{ability_key}",
                        )

    def _on_phase_start_oath_of_rynn(self, player=None, phase=None, **_kwargs) -> None:
        """Command phase: Pedro Kantor can activate Oath of Rynn at the start of either player's Command phase."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        def _is_alive(entity):
            alive_attr = getattr(entity, "is_alive", False)
            return bool(alive_attr() if callable(alive_attr) else alive_attr)

        def _unit_sort_key(unit):
            try:
                root = unit.get_attached_unit_root() if hasattr(unit, "get_attached_unit_root") else unit
            except Exception:
                root = unit
            return str(get_entity_id(root) or "")

        def _model_sort_key(model):
            try:
                return str(get_entity_id(model) or "")
            except Exception:
                return str(getattr(model, "name", "") or "")

        pending_model_ids: set[str] = set()
        queue = getattr(self, "decision_queue", None)
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "") or "") != DECISION_CONFIRM_YES_NO:
                    continue
                ctx = dict(getattr(req, "context", {}) or {})
                if str(ctx.get("ability", "") or "").strip().lower() != "oath_of_rynn":
                    continue
                model_id = str(ctx.get("model_id", "") or "").strip()
                if model_id:
                    pending_model_ids.add(model_id)

        for owner in sorted(list(getattr(self, "players", []) or []), key=lambda p: str(getattr(p, "id", "") or "")):
            if owner is None:
                continue
            army = self._get_player_army(owner)
            if army is None:
                continue

            seen_roots: set[str] = set()
            for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None:
                    continue
                root_id = str(get_entity_id(root) or "")
                if not root_id or root_id in seen_roots:
                    continue
                seen_roots.add(root_id)
                if not _is_alive(root):
                    continue
                if not bool(getattr(root, "deployed", False)):
                    continue
                try:
                    if root.is_in_reserves() or root.is_embarked:
                        continue
                except Exception:
                    pass

                try:
                    models = list(root.get_attached_unit_models() or [])
                except Exception:
                    models = list(getattr(root, "models", []) or [])
                alive_models = [m for m in list(models or []) if _is_alive(m)]
                for model in sorted(alive_models, key=_model_sort_key):
                    model_id = str(get_entity_id(model) or "")
                    if not model_id or model_id in pending_model_ids:
                        continue
                    specs = root.model_start_either_command_phase_unit_weapon_attacks_bonus_specs(model) or []
                    if not specs:
                        continue
                    for spec in list(specs or []):
                        ability_key = str(spec.get("ability_key", "") or "oath_of_rynn").strip().lower() or "oath_of_rynn"
                        if getattr(model, "has_used_once_per_battle", lambda _k: False)(ability_key):
                            continue
                        try:
                            attacks_bonus = int(spec.get("attacks_bonus", 0) or 0)
                        except (TypeError, ValueError):
                            attacks_bonus = 0
                        if attacks_bonus <= 0:
                            continue
                        ability_name = str(spec.get("source", "") or "Oath of Rynn").strip() or "Oath of Rynn"
                        expires_phase = str(spec.get("expires_phase", "") or "FIGHT_PHASE").strip().upper() or "FIGHT_PHASE"
                        ctx = {
                            "ability": "oath_of_rynn",
                            "ability_key": ability_key,
                            "ability_name": ability_name,
                            "phase": "Command phase",
                            "unit": getattr(root, "name", "") or "",
                            "unit_id": root_id,
                            "model": getattr(model, "name", "") or "",
                            "model_id": model_id,
                            "attacks_bonus": int(attacks_bonus),
                            "expires_phase": expires_phase,
                        }
                        message = f"Activate {ability_name} for {getattr(model, 'name', 'Model')}?"
                        self._queue_optional_ability_confirmation(
                            player=owner,
                            ability_key="oath_of_rynn",
                            ability_name=ability_name,
                            message=message,
                            context=ctx,
                            payload={
                                "unit_id": root_id,
                                "model_id": model_id,
                                "ability_key": ability_key,
                                "attacks_bonus": int(attacks_bonus),
                                "expires_phase": expires_phase,
                            },
                            instance_key=f"{model_id}:{ability_key}",
                        )

    def _on_phase_start_command_phase_enemy_no_cover(self, player=None, phase=None, **_kwargs) -> None:
        """Command phase: optionally select an enemy unit that cannot gain Benefit of Cover until next Command phase."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        queue_fn = getattr(self, "_queue_command_phase_enemy_no_cover", None)
        if not callable(queue_fn):
            return
        army = self._get_player_army(player)
        if army is None:
            return
        enemy_roots = list(self._collect_enemy_unit_roots(player) or [])
        if not enemy_roots:
            return

        def _unit_sort_key(unit):
            try:
                return str(get_entity_id(unit))
            except Exception:
                return str(getattr(unit, "name", "") or "")

        def _model_sort_key(model):
            try:
                return str(get_entity_id(model))
            except Exception:
                return str(getattr(model, "name", "") or "")

        seen_roots: set[str] = set()
        for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            if root is None:
                continue
            root_id = str(get_entity_id(root) or "")
            if not root_id or root_id in seen_roots:
                continue
            seen_roots.add(root_id)
            if not bool(getattr(root, "is_alive", lambda: False)()):
                continue
            if not bool(getattr(root, "deployed", False)):
                continue
            try:
                if root.is_in_reserves() or root.is_embarked:
                    continue
            except Exception:
                pass

            spec_fn = getattr(root, "model_command_phase_enemy_no_cover_specs", None)
            if not callable(spec_fn):
                continue
            try:
                models = list(root.get_attached_unit_models() or [])
            except Exception:
                models = list(getattr(root, "models", []) or [])
            for model in sorted(list(models or []), key=_model_sort_key):
                is_alive_attr = getattr(model, "is_alive", True)
                model_alive = bool(is_alive_attr() if callable(is_alive_attr) else is_alive_attr)
                if not model_alive:
                    continue
                specs = list(spec_fn(model) or [])
                if not specs:
                    continue
                for spec in list(specs or []):
                    try:
                        range_value = int(spec.get("range", 0) or 0)
                    except (TypeError, ValueError):
                        range_value = 0
                    if range_value <= 0:
                        continue
                    candidates = self._enemy_candidates_within_range_of_model(
                        model=model,
                        enemy_roots=enemy_roots,
                        range_value=float(range_value),
                    )
                    if not candidates:
                        continue
                    source_unit = getattr(model, "parent_unit", None) or root
                    queue_fn(
                        player=player,
                        source_unit=source_unit,
                        model=model,
                        candidates=list(candidates),
                        spec=dict(spec),
                    )

    def _on_phase_start_neuroloids_cleanup(self, player=None, phase=None, **_kwargs) -> None:
        """Start of the owner's Command phase: clear Neuroloids Synapse-range markers."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        owner_id = str(getattr(player, "id", "") or "").strip()
        if not owner_id:
            return
        army = self._get_player_army(player)
        if army is None:
            return

        def _unit_sort_key(unit):
            try:
                return str(get_entity_id(unit))
            except Exception:
                return str(getattr(unit, "name", "") or "")

        seen_roots: set[str] = set()
        for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            if root is None:
                continue
            root_id = str(get_entity_id(root) or "")
            if not root_id or root_id in seen_roots:
                continue
            seen_roots.add(root_id)
            sr = getattr(root, "special_rules", None)
            if not isinstance(sr, dict):
                continue
            if not bool(sr.get("neuroloids_synapse_active", False)):
                continue
            marker_owner = str(sr.get("neuroloids_synapse_owner", "") or "").strip()
            if marker_owner and marker_owner != owner_id:
                continue
            for key in (
                "neuroloids_synapse_active",
                "neuroloids_synapse_owner",
                "neuroloids_synapse_turn",
                "neuroloids_synapse_source_unit_id",
                "neuroloids_synapse_source",
            ):
                sr.pop(key, None)
            root.special_rules = sr

    def _on_phase_start_neuroloids(self, player=None, phase=None, **_kwargs) -> None:
        """Command phase: Neuroloids selection of up to two friendly TYRANIDS units to count as in Synapse Range."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        army = self._get_player_army(player)
        if army is None:
            return
        try:
            from ..decision_kinds import DECISION_CHOOSE_QUARRY
            from ..decisions import DecisionOption, DecisionRequest
        except Exception:
            return
        from itertools import combinations

        try:
            current_turn = int(getattr(self, "turn", 0) or 0)
        except (TypeError, ValueError):
            current_turn = 0
        queue = getattr(self, "decision_queue", None)

        def _unit_sort_key(unit):
            try:
                return str(get_entity_id(unit))
            except Exception:
                return str(getattr(unit, "name", "") or "")

        def _model_sort_key(model):
            try:
                return str(get_entity_id(model))
            except Exception:
                return str(getattr(model, "name", "") or "")

        def _on_battlefield(unit) -> bool:
            if unit is None:
                return False
            if not bool(getattr(unit, "is_alive", lambda: False)()):
                return False
            if not bool(getattr(unit, "deployed", False)):
                return False
            try:
                if unit.is_in_reserves():
                    return False
            except Exception:
                pass
            return True

        seen_roots: set[str] = set()
        for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            if root is None:
                continue
            root_id = str(get_entity_id(root) or "")
            if not root_id or root_id in seen_roots:
                continue
            seen_roots.add(root_id)
            if not _on_battlefield(root):
                continue

            spec_fn = getattr(root, "model_command_phase_select_friendly_synapse_units_specs", None)
            if not callable(spec_fn):
                continue
            try:
                models = list(root.get_attached_unit_models() or [])
            except Exception:
                models = list(getattr(root, "models", []) or [])
            for model in sorted(list(models or []), key=_model_sort_key):
                is_alive_attr = getattr(model, "is_alive", True)
                model_alive = bool(is_alive_attr() if callable(is_alive_attr) else is_alive_attr)
                if not model_alive:
                    continue
                specs = list(spec_fn(model) or [])
                if not specs:
                    continue
                for spec in list(specs or []):
                    try:
                        range_value = int(spec.get("range", 0) or 0)
                    except (TypeError, ValueError):
                        range_value = 0
                    try:
                        max_targets = int(spec.get("max_targets", 0) or 0)
                    except (TypeError, ValueError):
                        max_targets = 0
                    if range_value <= 0 or max_targets <= 0:
                        continue
                    friendly_keyword_phrase = str(spec.get("friendly_keyword_phrase", "") or "").strip()
                    ability_name = str(spec.get("source", "") or "Neuroloids").strip() or "Neuroloids"
                    ability_key = str(spec.get("ability_key", "") or "").strip().lower()
                    if not ability_key:
                        ability_key = "command_phase_select_friendly_synapse_units:neuroloids"
                    model_id = str(get_entity_id(model) or "")
                    source_unit = getattr(model, "parent_unit", None) or root
                    source_root = (
                        source_unit.get_attached_unit_root()
                        if hasattr(source_unit, "get_attached_unit_root")
                        else source_unit
                    )
                    if source_root is None:
                        continue
                    source_root_id = str(get_entity_id(source_root) or "")
                    if not model_id or not source_root_id:
                        continue

                    if queue is not None and hasattr(queue, "list"):
                        duplicate = False
                        for req in list(queue.list() or []):
                            if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                                continue
                            ctx = dict(getattr(req, "context", {}) or {})
                            if str(ctx.get("ability", "") or "").strip().lower() != "neuroloids":
                                continue
                            if str(ctx.get("model_id", "") or "") != model_id:
                                continue
                            if str(ctx.get("ability_key", "") or "").strip().lower() != ability_key:
                                continue
                            try:
                                queued_turn = int(ctx.get("turn", 0) or 0)
                            except (TypeError, ValueError):
                                queued_turn = 0
                            if queued_turn and current_turn and queued_turn != current_turn:
                                continue
                            duplicate = True
                            break
                        if duplicate:
                            continue

                    candidates: list[object] = []
                    candidate_ids: list[str] = []
                    candidate_name_by_id: dict[str, str] = {}
                    seen_candidate_ids: set[str] = set()
                    for candidate in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
                        if candidate is None:
                            continue
                        try:
                            candidate_root = candidate.get_attached_unit_root()
                        except Exception:
                            candidate_root = candidate
                        if candidate_root is None:
                            continue
                        candidate_id = str(get_entity_id(candidate_root) or "")
                        if not candidate_id or candidate_id in seen_candidate_ids:
                            continue
                        if not _on_battlefield(candidate_root):
                            continue
                        if friendly_keyword_phrase:
                            has_any_keyword = getattr(candidate_root, "has_any_keyword", None)
                            if not callable(has_any_keyword) or not bool(has_any_keyword(friendly_keyword_phrase)):
                                continue
                        in_range_fn = getattr(self, "_unit_within_range_of_model", None)
                        if callable(in_range_fn):
                            if not bool(in_range_fn(model, candidate_root, range_value=float(range_value))):
                                continue
                        else:
                            local_in_range = getattr(source_root, "_model_within_range_of_unit", None)
                            if not callable(local_in_range):
                                continue
                            if not bool(local_in_range(model, candidate_root, float(range_value))):
                                continue
                        candidates.append(candidate_root)
                        candidate_ids.append(candidate_id)
                        candidate_name_by_id[candidate_id] = str(getattr(candidate_root, "name", "Unit") or "Unit")
                        seen_candidate_ids.add(candidate_id)

                    if not candidate_ids:
                        continue

                    max_select = min(int(max_targets), len(candidate_ids))
                    if max_select <= 0:
                        continue
                    options = [DecisionOption.create("None", payload={"action": "skip", "selected_unit_ids": []})]
                    for count in range(1, max_select + 1):
                        for combo_ids in combinations(candidate_ids, count):
                            labels = [candidate_name_by_id.get(unit_id, unit_id) for unit_id in combo_ids]
                            label = " + ".join(labels) if labels else ", ".join(combo_ids)
                            payload = {
                                "selected_unit_ids": list(combo_ids),
                                "unit_id": source_root_id,
                                "source_unit_id": source_root_id,
                                "model_id": model_id,
                                "ability_key": ability_key,
                            }
                            options.append(DecisionOption.create(label, payload=payload))

                    request = DecisionRequest.create(
                        DECISION_CHOOSE_QUARRY,
                        (
                            f"{ability_name}: select up to {int(max_targets)} friendly {friendly_keyword_phrase.upper()} unit(s) "
                            f"within {int(range_value)}\" to count as within Synapse Range until your next Command phase."
                        ),
                        player_id=getattr(player, "id", None),
                        options=options,
                        context={
                            "ability": "neuroloids",
                            "ability_name": ability_name,
                            "ability_key": ability_key,
                            "phase": "Command phase",
                            "source_unit_id": source_root_id,
                            "unit_id": source_root_id,
                            "model_id": model_id,
                            "range": int(range_value),
                            "max_targets": int(max_targets),
                            "friendly_keyword_phrase": friendly_keyword_phrase,
                            "candidate_unit_ids": list(candidate_ids),
                            "optional": True,
                            "turn": int(current_turn or 0),
                            "expires_timing": str(spec.get("expires_timing", "owner_next_command_start") or "owner_next_command_start"),
                        },
                    )
                    self.request_decision(request)

    def _on_phase_start_imperial_agents_psychic_veil_cleanup(self, player=None, phase=None, **_kwargs) -> None:
        """Start of Command phase: clear prior Psychic Veil effects for the active player."""
