    def _on_phase_start_paroxysm(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase start: optional Paroxysm target selection."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        game_map = self.map
        if game_map is None:
            return

        from ...utility.aura_utils import model_within_range_of_unit

        pending_models = set()
        try:
            queue = getattr(self, "decision_queue", None)
            if queue is not None and hasattr(queue, "list"):
                for req in list(queue.list() or []):
                    if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                        continue
                    ctx = dict(getattr(req, "context", {}) or {})
                    if str(ctx.get("ability", "") or "") != "paroxysm":
                        continue
                    mid = str(ctx.get("model_id", "") or "")
                    if mid:
                        pending_models.add(mid)
        except Exception:
            pending_models = set()

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        def _model_sort_key(m):
            try:
                return str(get_entity_id(m))
            except Exception:
                return str(getattr(m, "name", "") or "")

        can_see_fn = getattr(game_map, "can_model_see_model", None)
        for p in list(getattr(self, "players", []) or []):
            if p is None:
                continue
            army = p.get_army()
            if army is None:
                continue
            for unit in sorted(list(army.units or []), key=_unit_sort_key):
                if unit is None:
                    continue
                if not unit.is_alive() or not getattr(unit, "deployed", True):
                    continue
                try:
                    if unit.is_in_reserves():
                        continue
                except Exception:
                    pass
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None or not root.is_alive():
                    continue
                try:
                    models = list(root.get_attached_unit_models() or [])
                except Exception:
                    models = list(getattr(root, "models", []) or [])
                if not models:
                    continue

                for model in sorted([m for m in models if getattr(m, "is_alive", True)], key=_model_sort_key):
                    model_id = str(get_entity_id(model) or "")
                    if model_id and model_id in pending_models:
                        continue
                    spec_fn = getattr(root, "model_start_fight_phase_paroxysm_specs", None)
                    if not callable(spec_fn):
                        continue
                    specs = list(spec_fn(model) or [])
                    if not specs:
                        continue
                    spec = dict(specs[0] or {})
                    ability_name = str(spec.get("source", "") or "Paroxysm").strip() or "Paroxysm"
                    try:
                        range_value = int(spec.get("range", 0) or 0)
                    except Exception:
                        range_value = 0
                    if range_value <= 0:
                        continue
                    try:
                        success_threshold = int(spec.get("success_threshold", 2) or 2)
                    except Exception:
                        success_threshold = 2
                    success_threshold = max(2, min(6, int(success_threshold)))
                    self_mw = str(spec.get("self_mortal_wounds", "D3") or "D3").strip().upper() or "D3"
                    try:
                        attacks_penalty = int(spec.get("attacks_penalty", 1) or 1)
                    except Exception:
                        attacks_penalty = 1
                    attacks_penalty = max(1, int(attacks_penalty))

                    candidates = []
                    seen_enemy = set()
                    for enemy in list(game_map.get_enemy_units(root) or []):
                        if enemy is None:
                            continue
                        try:
                            enemy_root = enemy.get_attached_unit_root()
                        except Exception:
                            enemy_root = enemy
                        if enemy_root is None or not enemy_root.is_alive():
                            continue
                        try:
                            if not getattr(enemy_root, "deployed", True):
                                continue
                            if enemy_root.is_in_reserves() or enemy_root.is_embarked:
                                continue
                        except Exception:
                            pass
                        eid = str(get_entity_id(enemy_root) or "")
                        if not eid or eid in seen_enemy:
                            continue
                        seen_enemy.add(eid)
                        if not model_within_range_of_unit(model, enemy_root, float(range_value)):
                            continue
                        if callable(can_see_fn):
                            visible = False
                            try:
                                enemy_models = list(enemy_root.get_attached_unit_models() or [])
                            except Exception:
                                enemy_models = list(getattr(enemy_root, "models", []) or [])
                            for enemy_model in list(enemy_models or []):
                                if enemy_model is None:
                                    continue
                                alive_attr = getattr(enemy_model, "is_alive", True)
                                enemy_alive = bool(alive_attr() if callable(alive_attr) else alive_attr)
                                if not enemy_alive:
                                    continue
                                if can_see_fn(model, enemy_model):
                                    visible = True
                                    break
                            if not visible:
                                continue
                        candidates.append(enemy_root)
                    if not candidates:
                        continue
                    try:
                        candidates = sorted(candidates, key=_unit_sort_key)
                    except Exception:
                        pass

                    options = [
                        DecisionOption.create("None", payload={"action": "skip"}),
                    ]
                    for cand in candidates:
                        options.append(
                            DecisionOption.create(
                                str(getattr(cand, "name", "Unit") or "Unit"),
                                payload={"target_unit_id": get_entity_id(cand)},
                            )
                        )
                    request = DecisionRequest.create(
                        DECISION_CHOOSE_QUARRY,
                        f"{ability_name}: select one visible enemy unit within {int(range_value)}\" (or None).",
                        player_id=getattr(p, "id", None),
                        options=options,
                        context={
                            "ability": "paroxysm",
                            "ability_name": ability_name,
                            "source_unit_id": get_entity_id(root),
                            "attacker_unit_id": get_entity_id(root),
                            "model_id": model_id,
                            "range": int(range_value),
                            "success_threshold": int(success_threshold),
                            "self_mortal_wounds": str(self_mw),
                            "attacks_penalty": int(attacks_penalty),
                            "optional": True,
                        },
                    )
                    self.request_decision(request)
                    if model_id:
                        pending_models.add(model_id)

    def _on_phase_start_accelerator_mandible(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase start: optional Accelerator Mandible target selection for a nearby friendly CANOPTEK unit."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        game_map = self.map
        if game_map is None:
            return

        pending_models = set()
        try:
            queue = getattr(self, "decision_queue", None)
            if queue is not None and hasattr(queue, "list"):
                for req in list(queue.list() or []):
                    if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                        continue
                    ctx = dict(getattr(req, "context", {}) or {})
                    if str(ctx.get("ability", "") or "") != "accelerator_mandible":
                        continue
                    mid = str(ctx.get("model_id", "") or "")
                    if mid:
                        pending_models.add(mid)
        except Exception:
            pending_models = set()

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        def _model_sort_key(m):
            try:
                return str(get_entity_id(m))
            except Exception:
                return str(getattr(m, "name", "") or "")

        for p in list(getattr(self, "players", []) or []):
            if p is None:
                continue
            army = p.get_army()
            if army is None:
                continue
            friendly_roots = []
            seen_friendly = set()
            for candidate in list(army.units or []):
                if candidate is None:
                    continue
                try:
                    croot = candidate.get_attached_unit_root()
                except Exception:
                    croot = candidate
                if croot is None or not croot.is_alive() or not getattr(croot, "deployed", True):
                    continue
                try:
                    if croot.is_in_reserves() or croot.is_embarked:
                        continue
                except Exception:
                    pass
                cid = str(get_entity_id(croot) or "")
                if not cid or cid in seen_friendly:
                    continue
                seen_friendly.add(cid)
                friendly_roots.append(croot)
            if not friendly_roots:
                continue
            try:
                friendly_roots = sorted(friendly_roots, key=_unit_sort_key)
            except Exception:
                pass
            for unit in sorted(list(army.units or []), key=_unit_sort_key):
                if unit is None:
                    continue
                if not unit.is_alive() or not getattr(unit, "deployed", True):
                    continue
                try:
                    if unit.is_in_reserves():
                        continue
                except Exception:
                    pass
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None or not root.is_alive():
                    continue
                try:
                    models = list(root.get_attached_unit_models() or [])
                except Exception:
                    models = list(getattr(root, "models", []) or [])
                if not models:
                    continue
                for model in sorted([m for m in models if getattr(m, "is_alive", True)], key=_model_sort_key):
                    model_id = str(get_entity_id(model) or "")
                    if model_id and model_id in pending_models:
                        continue
                    spec_fn = getattr(root, "model_start_fight_phase_friendly_melee_ws_bonus_specs", None)
                    if not callable(spec_fn):
                        continue
                    specs = spec_fn(model) or []
                    if not specs:
                        continue
                    spec = specs[0]
                    ability_name = str(spec.get("source", "") or "Accelerator Mandible").strip() or "Accelerator Mandible"
                    keyword = str(spec.get("keyword", "") or "canoptek").strip()
                    try:
                        range_value = int(spec.get("range", 3) or 3)
                    except Exception:
                        range_value = 3
                    try:
                        ws_bonus = int(spec.get("ws_bonus", 1) or 1)
                    except Exception:
                        ws_bonus = 1
                    if range_value <= 0 or ws_bonus <= 0:
                        continue

                    candidates = []
                    seen_candidates = set()
                    for candidate_root in list(friendly_roots):
                        if candidate_root is None:
                            continue
                        cid = str(get_entity_id(candidate_root) or "")
                        if not cid or cid in seen_candidates:
                            continue
                        seen_candidates.add(cid)
                        keyword_match = False
                        if keyword:
                            try:
                                keyword_match = bool(candidate_root.has_any_keyword(keyword))
                            except Exception:
                                keyword_match = False
                            if not keyword_match:
                                try:
                                    keyword_match = bool(candidate_root.has_keyword(keyword))
                                except Exception:
                                    keyword_match = False
                        if not keyword_match:
                            continue
                        in_range = False
                        try:
                            in_range = bool(
                                float(game_map.get_distance_between_units(root, candidate_root))
                                <= float(range_value)
                            )
                        except Exception:
                            in_range = False
                        if not in_range:
                            continue
                        candidates.append(candidate_root)
                    if not candidates:
                        continue
                    try:
                        candidates = sorted(candidates, key=_unit_sort_key)
                    except Exception:
                        pass

                    options = [
                        DecisionOption.create("None", payload={"action": "skip"}),
                    ]
                    for cand in candidates:
                        options.append(
                            DecisionOption.create(
                                str(getattr(cand, "name", "Unit") or "Unit"),
                                payload={"target_unit_id": get_entity_id(cand)},
                            )
                        )
                    request = DecisionRequest.create(
                        DECISION_CHOOSE_QUARRY,
                        f"{ability_name}: select a friendly {keyword.upper()} unit (or None).",
                        player_id=getattr(p, "id", None),
                        options=options,
                        context={
                            "ability": "accelerator_mandible",
                            "ability_name": ability_name,
                            "source_unit_id": get_entity_id(root),
                            "unit_id": get_entity_id(root),
                            "model_id": model_id,
                            "keyword": keyword,
                            "range": int(range_value),
                            "ws_bonus": int(ws_bonus),
                            "optional": True,
                        },
                    )
                    self.request_decision(request)
                    if model_id:
                        pending_models.add(model_id)

    def _on_phase_start_spirit_of_gork(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase start: optional Spirit of Gork target selection for Kill Rig."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        game_map = self.map
        if game_map is None:
            return

        try:
            from ...utility.aura_utils import model_within_range_of_unit
        except ImportError:
            return

        pending_models = set()
        try:
            queue = getattr(self, "decision_queue", None)
            if queue is not None and hasattr(queue, "list"):
                for req in list(queue.list() or []):
                    if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                        continue
                    ctx = dict(getattr(req, "context", {}) or {})
                    if str(ctx.get("ability", "") or "") != "spirit_of_gork":
                        continue
                    mid = str(ctx.get("model_id", "") or "")
                    if mid:
                        pending_models.add(mid)
        except Exception:
            pending_models = set()

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        def _first_alive_model(unit):
            models = list(getattr(unit, "models", []) or [])
            models = sorted(models, key=lambda m: str(get_entity_id(m) or ""))
            for model in models:
                alive_attr = getattr(model, "is_alive", True)
                if bool(alive_attr() if callable(alive_attr) else alive_attr):
                    return model
            return None

        def _unit_active(unit) -> bool:
            if unit is None:
                return False
            if not bool(getattr(unit, "is_alive", lambda: False)()):
                return False
            if not bool(getattr(unit, "deployed", True)):
                return False
            try:
                if unit.is_in_reserves() or unit.is_embarked:
                    return False
            except Exception:
                pass
            return True

        def _unit_has_ability_named(unit, ability_name: str) -> bool:
            target = str(ability_name or "").replace("\u2019", "'").strip().lower()
            if not target or unit is None:
                return False
            try:
                for ab in list(getattr(unit, "possible_abilities", []) or []):
                    name = str(getattr(ab, "name", "") or "").replace("\u2019", "'").strip().lower()
                    if name == target:
                        return True
            except Exception:
                return False
            return False

        for p in list(getattr(self, "players", []) or []):
            if p is None:
                continue
            army = p.get_army()
            if army is None:
                continue

            friendly_roots = []
            seen_friendly = set()
            for candidate in list(army.units or []):
                if candidate is None:
                    continue
                try:
                    croot = candidate.get_attached_unit_root()
                except Exception:
                    croot = candidate
                if croot is None or not _unit_active(croot):
                    continue
                cid = str(get_entity_id(croot) or "")
                if cid and cid in seen_friendly:
                    continue
                if cid:
                    seen_friendly.add(cid)
                friendly_roots.append(croot)
            if not friendly_roots:
                continue
            try:
                friendly_roots = sorted(friendly_roots, key=_unit_sort_key)
            except Exception:
                pass

            for unit in sorted(list(army.units or []), key=_unit_sort_key):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None or not _unit_active(root):
                    continue
                if not _unit_has_ability_named(root, "Spirit of Gork (Psychic)"):
                    continue
                source_model = _first_alive_model(root)
                if source_model is None:
                    continue
                model_id = str(get_entity_id(source_model) or "")
                if model_id and model_id in pending_models:
                    continue

                candidates = []
                candidate_ids: list[str] = []
                for candidate_root in list(friendly_roots):
                    if candidate_root is None:
                        continue
                    try:
                        if not bool(candidate_root.has_any_keyword("ORKS")):
                            continue
                    except Exception:
                        continue
                    if not bool(model_within_range_of_unit(source_model, candidate_root, 12.0)):
                        continue
                    candidates.append(candidate_root)
                    cid = str(get_entity_id(candidate_root) or "")
                    if cid:
                        candidate_ids.append(cid)
                if not candidates:
                    continue

                options = [DecisionOption.create("None", payload={"action": "skip"})]
                for cand in sorted(list(candidates), key=_unit_sort_key):
                    options.append(
                        DecisionOption.create(
                            str(getattr(cand, "name", "Unit") or "Unit"),
                            payload={"target_unit_id": get_entity_id(cand)},
                        )
                    )

                request = DecisionRequest.create(
                    DECISION_CHOOSE_QUARRY,
                    "Spirit of Gork (Psychic): select one friendly ORKS unit within 12\" (or None).",
                    player_id=getattr(p, "id", None),
                    options=options,
                    context={
                        "ability": "spirit_of_gork",
                        "ability_name": "Spirit of Gork (Psychic)",
                        "source_unit_id": get_entity_id(root),
                        "unit_id": get_entity_id(root),
                        "model_id": model_id,
                        "range": 12,
                        "strength_bonus": 1,
                        "self_mortal_wounds": "D3",
                        "candidate_unit_ids": list(candidate_ids),
                        "optional": True,
                    },
                )
                self.request_decision(request)
                if model_id:
                    pending_models.add(model_id)

    def _on_phase_start_fight_phase_target_attack_bonus(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase start: select an enemy unit to mark for attack bonuses (e.g., Blood Throne, The Eternal Dance)."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        game_map = self.map
        if game_map is None:
            return

        pending_models = set()
        try:
            queue = getattr(self, "decision_queue", None)
            if queue is not None and hasattr(queue, "list"):
                for req in list(queue.list() or []):
                    if str(getattr(req, "decision_type", "")) != DECISION_CHOOSE_QUARRY:
                        continue
                    ctx = dict(getattr(req, "context", {}) or {})
                    if str(ctx.get("ability", "") or "") != "fight_phase_target_attack_bonus":
                        continue
                    mid = str(ctx.get("model_id", "") or "")
                    if mid:
                        pending_models.add(mid)
        except Exception:
            pending_models = set()

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        def _model_sort_key(m):
            try:
                return str(get_entity_id(m))
            except Exception:
                return str(getattr(m, "name", "") or "")

        for p in list(getattr(self, "players", []) or []):
            if p is None:
                continue
            army = p.get_army()
            if army is None:
                continue
            enemy_roots = self._collect_enemy_unit_roots(p)
            if not enemy_roots:
                continue
            enemy_roots.sort(key=_unit_sort_key)
            for unit in sorted(list(army.units or []), key=_unit_sort_key):
                if unit is None:
                    continue
                if not unit.is_alive() or not getattr(unit, "deployed", True):
                    continue
                try:
                    if unit.is_in_reserves():
                        continue
                except Exception:
                    pass
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None or not root.is_alive():
                    continue
                try:
                    models = list(root.get_attached_unit_models() or [])
                except Exception:
                    models = list(getattr(root, "models", []) or [])
                if not models:
                    continue
                for model in sorted([m for m in models if getattr(m, "is_alive", True)], key=_model_sort_key):
                    model_id = str(get_entity_id(model) or "")
                    if model_id and model_id in pending_models:
                        continue
                    specs = root.model_start_fight_phase_target_attack_bonus_specs(model) or []
                    if not specs:
                        continue
                    for spec in specs:
                        try:
                            range_value = int(spec.get("range", 0) or 0)
                        except Exception:
                            range_value = 0
                        if range_value <= 0:
                            continue
                        requires_visibility = bool(spec.get("requires_visibility", False))
                        if requires_visibility:
                            candidates = self._visible_enemy_candidates_for_model(
                                source_unit=root,
                                model=model,
                                enemy_roots=enemy_roots,
                                range_value=float(range_value),
                                game_map=game_map,
                            )
                        else:
                            candidates = self._enemy_candidates_within_range_of_model(
                                model=model,
                                enemy_roots=enemy_roots,
                                range_value=float(range_value),
                            )
                        if not candidates:
                            continue
                        self._queue_fight_phase_target_attack_bonus(
                            player=p,
                            source_unit=root,
                            model=model,
                            candidates=candidates,
                            spec=spec,
                        )

