    def _on_phase_end_seed_the_garden_of_nurgle(self, player=None, phase=None, **_kwargs) -> None:
        """Movement phase end: if within Area Terrain, mark terrain as within Shadow of Chaos (Seed the Garden)."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        army = self._get_player_army(player)
        if army is None:
            return
        game_map = self.map
        if game_map is None:
            return
        try:
            from ...battlefield.map import TerrainType
        except Exception:
            TerrainType = None

        area_types = set()
        if TerrainType is not None:
            area_types = {
                TerrainType.CRATER_AND_RUBBLE,
                TerrainType.DEBRIS_AND_STATUARY,
                TerrainType.HILLS_AND_SEALED_BUILDINGS,
                TerrainType.WOODS,
                TerrainType.RUINS,
            }

        def _model_in_area_terrain(model):
            if model is None:
                return []
            base = getattr(model, "model_base", None)
            if base is None:
                return []
            try:
                base_shape = base.get_base_shape()
            except Exception:
                return []
            matches = []
            for terrain in list(getattr(game_map, "terrain_features", []) or []):
                if TerrainType is not None and getattr(terrain, "terrain_type", None) not in area_types:
                    continue
                footprint = getattr(terrain, "footprint", None)
                if footprint is None:
                    continue
                try:
                    if footprint.intersects(base_shape):
                        matches.append(terrain)
                except Exception:
                    continue
            return matches

        owner_id = str(getattr(player, "id", "") or "")
        if not owner_id:
            return
        from ...utility.entity_ids import get_entity_id
        for unit in list(army.units):
            if unit is None:
                continue
            try:
                if not getattr(unit, "is_alive", lambda: False)():
                    continue
            except Exception:
                continue
            if not getattr(unit, "deployed", True):
                continue
            try:
                if unit.is_in_reserves():
                    continue
            except Exception:
                pass
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            try:
                models = list(root.get_attached_unit_models() or [])
            except Exception:
                models = list(getattr(root, "models", []) or [])
            if not models:
                continue
            for model in list(models or []):
                if not getattr(model, "is_alive", True):
                    continue
                spec_fn = getattr(root, "model_movement_phase_end_shadow_of_chaos_terrain_specs", None)
                if not callable(spec_fn):
                    continue
                specs = spec_fn(model) or []
                if not specs:
                    continue
                terrain_matches = _model_in_area_terrain(model)
                if not terrain_matches:
                    continue
                terrain_matches.sort(key=lambda t: str(get_entity_id(t)))
                terrain = terrain_matches[0]
                try:
                    owners = getattr(terrain, "shadow_of_chaos_owner_ids", None)
                    if not isinstance(owners, set):
                        owners = set(owners or [])
                    if owner_id in owners:
                        continue
                    owners.add(owner_id)
                    terrain.shadow_of_chaos_owner_ids = owners
                except Exception:
                    continue
                try:
                    from ...utility.event_bus import append_action
                    ability_name = str(specs[0].get("source", "") or "Seed the Garden of Nurgle").strip()
                    append_action(
                        player,
                        f"{ability_name}: area terrain seeded with Shadow of Chaos.",
                    )
                except Exception:
                    pass

    def _on_phase_end_movement_phase_symphony_of_pain(self, player=None, phase=None, **_kwargs) -> None:
        """Movement phase end: select a Battle-shocked enemy within range for full hit/wound rerolls (Symphony of Pain)."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        army = self._get_player_army(player)
        if army is None:
            return
        game_map = self.map
        if game_map is None:
            return

        from ...utility.entity_ids import get_entity_id

        enemy_roots = self._collect_enemy_unit_roots(player)
        if not enemy_roots:
            return

        owner_id = str(getattr(player, "id", "") or "")
        try:
            turn = int(getattr(self, "turn", 0) or 0)
        except Exception:
            turn = 0

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        enemy_roots.sort(key=_unit_sort_key)

        for unit in sorted(list(army.units or []), key=_unit_sort_key):
            if unit is None:
                continue
            if not getattr(unit, "is_alive", lambda: False)():
                continue
            if not getattr(unit, "deployed", True):
                continue
            try:
                if unit.is_in_reserves():
                    continue
            except Exception:
                pass
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            try:
                models = list(root.get_attached_unit_models() or [])
            except Exception:
                models = list(getattr(root, "models", []) or [])
            if not models:
                continue

            def _model_sort_key(m):
                try:
                    return str(get_entity_id(m))
                except Exception:
                    return str(getattr(m, "name", "") or "")

            for model in sorted([m for m in models if getattr(m, "is_alive", True)], key=_model_sort_key):
                spec_fn = getattr(root, "model_movement_phase_end_battleshock_reroll_specs", None)
                if not callable(spec_fn):
                    continue
                specs = spec_fn(model) or []
                if not specs:
                    continue
                source_unit = getattr(model, "parent_unit", None) or root
                for spec in specs:
                    try:
                        range_value = int(spec.get("range", 0) or 0)
                    except Exception:
                        range_value = 0
                    if range_value <= 0:
                        continue
                    candidates = []
                    for enemy in list(enemy_roots or []):
                        if enemy is None:
                            continue
                        try:
                            if not enemy.is_battle_shocked():
                                continue
                        except Exception:
                            continue
                        try:
                            sr = getattr(enemy, "special_rules", None)
                        except Exception:
                            sr = None
                        if isinstance(sr, dict):
                            if bool(sr.get("symphony_of_pain_active")):
                                if str(sr.get("symphony_of_pain_owner", "") or "") == owner_id and int(sr.get("symphony_of_pain_turn", 0) or 0) == int(turn or 0):
                                    continue
                        if enemy in self._enemy_candidates_within_range_of_model(
                            model=model,
                            enemy_roots=[enemy],
                            range_value=float(range_value),
                        ):
                            candidates.append(enemy)
                    if not candidates:
                        continue
                    self._queue_symphony_of_pain(
                        player=player,
                        source_unit=source_unit,
                        model=model,
                        candidates=candidates,
                        spec=spec,
                    )

    def _on_phase_end_grotesque_regeneration(self, player=None, phase=None, **_kwargs) -> None:
        """End of each phase: Beasts of Nurgle models regain all lost wounds."""
        if not bool(getattr(self, "is_authoritative", True)):
            return

        from ...utility.entity_ids import get_entity_id
        from ...utility.event_bus import append_action

        def _unit_has_regen(unit) -> bool:
            for ab in unit._iter_active_possible_abilities():
                if isinstance(ab, str):
                    name = ab
                else:
                    name = getattr(ab, "name", "")
                if str(name or "").strip().lower() == "grotesque regeneration":
                    return True
            return False

        for owner in list(getattr(self, "players", []) or []):
            if owner is None:
                continue
            army = self._get_player_army(owner)
            if army is None:
                continue
            seen: set[str] = set()
            for unit in list(getattr(army, "units", []) or []):
                if unit is None:
                    continue
                root = unit.get_attached_unit_root() if hasattr(unit, "get_attached_unit_root") else unit
                uid = get_entity_id(root)
                if uid in seen:
                    continue
                seen.add(uid)
                if not getattr(root, "is_alive", lambda: False)():
                    continue
                if not bool(getattr(root, "deployed", True)):
                    continue
                if str(getattr(root, "reserve_status", "deployed")) != "deployed":
                    continue
                in_reserves = False
                fn = getattr(root, "is_in_reserves", None)
                if callable(fn):
                    in_reserves = bool(fn())
                else:
                    in_reserves = str(getattr(root, "reserve_status", "deployed")) in ("reserves", "strategic_reserves")
                if in_reserves:
                    continue
                if bool(getattr(root, "embarked_in", None)) or bool(getattr(root, "is_embarked", False)):
                    continue
                if not _unit_has_regen(root):
                    continue

                models = list(getattr(root, "models", []) or [])
                healed = 0
                for model in models:
                    if not bool(getattr(model, "is_alive", True)):
                        continue
                    base_wounds = int(getattr(model, "_base_wounds", getattr(model, "wounds", 0)) or 0)
                    if base_wounds <= 0:
                        continue
                    current = int(getattr(model, "wounds", 0) or 0)
                    if current < base_wounds:
                        model.wounds = base_wounds
                        healed += 1
                if healed > 0:
                    append_action(owner, f"Grotesque Regeneration: {getattr(root, 'name', 'Unit')} fully healed ({healed} model(s)).")

    def _on_phase_end_ds8_support_turret(self, player=None, phase=None, **_kwargs) -> None:
        """Movement phase end: if eligible unit remained stationary, apply DS8 Support Turret virtual weapon."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        army = self._get_player_army(player)
        if army is None:
            return

        seen: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            if root is None:
                continue
            uid = str(get_entity_id(root) or "")
            if uid and uid in seen:
                continue
            if uid:
                seen.add(uid)
            if not bool(getattr(root, "is_alive", lambda: False)()):
                continue
            if not bool(getattr(root, "deployed", True)):
                continue
            try:
                if root.is_in_reserves() or root.is_embarked:
                    continue
            except Exception:
                pass
            if not bool(getattr(getattr(root, "round_state", None), "remained_stationary_this_round", False)):
                continue
            has_rule = getattr(root, "has_ds8_support_turret_ability", None)
            if not callable(has_rule) or not bool(has_rule()):
                continue
            activate_fn = getattr(root, "activate_ds8_support_turret_wargear", None)
            if callable(activate_fn):
                activate_fn()

    def _on_phase_end_movement_phase_mortal_table(self, player=None, phase=None, **_kwargs) -> None:
        """Movement phase end: roll a D6 for each enemy unit within range of this model; apply mortal wound table."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        army = self._get_player_army(player)
        if army is None:
            return
        enemy_roots = self._collect_enemy_unit_roots(player)
        if not enemy_roots:
            return
        game_map = getattr(self, "map", None)

        from ...utility.entity_ids import get_entity_id
        from ...utility.dice import get_roll
        from ...utility.event_bus import append_action, append_dice

        def _unit_sort_key(u):
            try:
                return str(get_entity_id(u))
            except Exception:
                return str(getattr(u, "name", "") or "")

        def _resolve_mortal_roll(spec: dict, roll: int, *, target_unit=None) -> tuple[int, str]:
            d3_roll = None
            d6_roll = None
            total_mw = 0
            try:
                afflicted_roll_bonus = int(spec.get("afflicted_roll_bonus", 0) or 0)
            except Exception:
                afflicted_roll_bonus = 0
            applied_bonus = 0
            if afflicted_roll_bonus > 0 and target_unit is not None:
                try:
                    from ...rules.nurgles_gift import NurglesGiftManager
                except Exception:
                    NurglesGiftManager = None
                if NurglesGiftManager is not None:
                    try:
                        is_afflicted = bool(
                            NurglesGiftManager.get_afflicted_plague_for_unit(
                                target_unit,
                                game=self,
                                game_map=game_map,
                            )
                            is not None
                        )
                    except Exception:
                        is_afflicted = False
                    if is_afflicted:
                        applied_bonus = int(afflicted_roll_bonus)
            effective_roll = int(roll) + int(applied_bonus)
            threshold = spec.get("threshold")
            if threshold is not None:
                try:
                    threshold = int(threshold or 0)
                except Exception:
                    threshold = 0
                if effective_roll >= int(threshold or 0):
                    mw = spec.get("mortal_wounds")
                    mw_norm = str(mw).strip().lower()
                    if mw_norm == "d3":
                        d3_roll = int(get_roll("D3") or 0)
                        total_mw = int(d3_roll or 0)
                    elif mw_norm == "d6":
                        d6_roll = int(get_roll("D6") or 0)
                        total_mw = int(d6_roll or 0)
                    else:
                        try:
                            total_mw = int(mw or 0)
                        except Exception:
                            total_mw = 0
            else:
                if 2 <= roll <= 3:
                    total_mw = 1
                elif 4 <= roll <= 5:
                    d3_roll = int(get_roll("D3") or 0)
                    total_mw = int(d3_roll or 0)
                elif roll >= 6:
                    d6_roll = int(get_roll("D6") or 0)
                    total_mw = int(d6_roll or 0)
            roll_note = f"roll={int(roll)}"
            if applied_bonus:
                roll_note += f", afflicted_bonus=+{int(applied_bonus)}, effective={int(effective_roll)}"
            if d3_roll is not None:
                roll_note += f", d3={int(d3_roll)}"
            if d6_roll is not None:
                roll_note += f", d6={int(d6_roll)}"
            return int(total_mw), roll_note

        def _apply_mortal_rolls(source_unit, targets: list, spec: dict, ability_name: str) -> None:
            if not targets:
                return
            for target_unit in targets:
                roll = int(get_roll("D6") or 0)
                total_mw, roll_note = _resolve_mortal_roll(spec, roll, target_unit=target_unit)
                if total_mw > 0 and hasattr(source_unit, "_apply_mortal_wounds_to_unit"):
                    source_unit._apply_mortal_wounds_to_unit(target_unit, int(total_mw), game_map=game_map)
                append_dice(
                    player,
                    f"{ability_name}: {getattr(target_unit, 'name', 'Target')} ({roll_note}) => {int(total_mw)} mortal wounds.",
                )
                append_action(
                    player,
                    f"{ability_name}: {getattr(target_unit, 'name', 'Target')} suffered {int(total_mw)} mortal wounds.",
                )

            if bool(spec.get("battle_shock")):
                for target_unit in targets:
                    try:
                        target_unit.take_battle_shock_test(int(getattr(self, "turn", 0) or 1))
                    except Exception:
                        continue

        enemy_roots.sort(key=_unit_sort_key)
        processed_unit_roots: set[str] = set()

        for unit in sorted(list(army.units or []), key=_unit_sort_key):
            if unit is None:
                continue
            if not getattr(unit, "is_alive", lambda: False)():
                continue
            if not getattr(unit, "deployed", True):
                continue
            try:
                if unit.is_in_reserves():
                    continue
            except Exception:
                pass
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            try:
                models = list(root.get_attached_unit_models() or [])
            except Exception:
                models = list(getattr(root, "models", []) or [])
            alive_models = [m for m in models if getattr(m, "is_alive", True)]
            if not alive_models:
                continue

            def _model_sort_key(m):
                try:
                    return str(get_entity_id(m))
                except Exception:
                    return str(getattr(m, "name", "") or "")

            root_id = str(get_entity_id(root) or "")
            if root_id and root_id not in processed_unit_roots:
                processed_unit_roots.add(root_id)
                unit_specs = []
                try:
                    unit_specs = list(root.unit_movement_phase_end_enemy_within_range_mortal_threshold_specs() or [])
                except Exception:
                    unit_specs = []
                if unit_specs:
                    for spec in unit_specs:
                        try:
                            range_value = int(spec.get("range", 0) or 0)
                        except Exception:
                            range_value = 0
                        if range_value <= 0:
                            continue
                        candidates = []
                        seen_enemy = set()
                        for enemy_root in enemy_roots:
                            if enemy_root is None:
                                continue
                            eid = str(get_entity_id(enemy_root) or "")
                            if not eid or eid in seen_enemy:
                                continue
                            seen_enemy.add(eid)
                            in_range = False
                            for model in alive_models:
                                if self._unit_within_range_of_model(model, enemy_root, range_value=float(range_value)):
                                    in_range = True
                                    break
                            if not in_range:
                                continue
                            candidates.append(enemy_root)
                        if not candidates:
                            continue
                        candidates.sort(key=_unit_sort_key)
                        ability_name = str(spec.get("source", "") or "Movement phase mortals").strip() or "Movement phase mortals"
                        _apply_mortal_rolls(root, candidates, spec, ability_name)

            for model in sorted(alive_models, key=_model_sort_key):
                spec_fn = getattr(root, "model_movement_phase_end_enemy_within_range_mortal_table_specs", None)
                if not callable(spec_fn):
                    continue
                specs = spec_fn(model) or []
                if not specs:
                    continue
                source_unit = getattr(model, "parent_unit", None) or root
                for spec in specs:
                    try:
                        range_value = int(spec.get("range", 0) or 0)
                    except Exception:
                        range_value = 0
                    if range_value <= 0:
                        continue
                    candidates = []
                    for enemy_root in enemy_roots:
                        if enemy_root is None:
                            continue
                        if not self._unit_within_range_of_model(model, enemy_root, range_value=float(range_value)):
                            continue
                        candidates.append(enemy_root)
                    if not candidates:
                        continue
                    candidates.sort(key=_unit_sort_key)
                    ability_name = str(spec.get("source", "") or "Movement phase mortals").strip() or "Movement phase mortals"
                    _apply_mortal_rolls(source_unit, candidates, spec, ability_name)

    def _on_phase_end_transport_end_of_fight_embark(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase end: optional embark for empty transports with datasheet abilities."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        game_map = self.map
        if game_map is None:
            return
        try:
            from ...utility.aura_utils import unit_wholly_within_range_of_unit
        except Exception:
            return

        for p in list(self.players or []):
            if p is None:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue
            for transport in list(army.units or []):
                if transport is None:
                    continue
                if not transport.is_alive() or not getattr(transport, "deployed", True):
                    continue
                try:
                    if transport.is_in_reserves() or transport.is_embarked:
                        continue
                except Exception:
                    pass
                if list(getattr(transport, "transport_passengers", []) or []):
                    continue
                try:
                    specs = list(transport.unit_end_of_fight_embark_specs() or [])
                except Exception:
                    specs = []
                if not specs:
                    continue
                for spec in specs:
                    try:
                        max_models = int(spec.get("max_models", 0) or 0)
                    except Exception:
                        max_models = 0
                    try:
                        range_value = float(spec.get("range", 0) or 0)
                    except Exception:
                        range_value = 0.0
                    if range_value <= 0:
                        continue
                    keyword = str(spec.get("keyword", "") or "").strip()
                    candidates = []
                    for unit in list(army.units or []):
                        if unit is None or unit is transport:
                            continue
                        if not unit.is_alive() or not getattr(unit, "deployed", True):
                            continue
                        try:
                            if unit.is_in_reserves():
                                continue
                        except Exception:
                            pass
                        if not getattr(unit, "is_infantry", False):
                            continue
                        if keyword and not unit.has_any_keyword(keyword):
                            continue
                        if max_models > 0:
                            try:
                                models = list(unit.get_attached_unit_models() or [])
                            except Exception:
                                models = list(getattr(unit, "models", []) or [])
                            alive = [m for m in models if getattr(m, "is_alive", True)]
                            if len(alive) > max_models:
                                continue
                        if getattr(unit.round_state, "disembarked_this_round", False):
                            continue
                        sr = getattr(unit, "special_rules", None)
                        if isinstance(sr, dict) and sr.get("fire_and_fade_no_embark_turn_owner"):
                            owner = str(sr.get("fire_and_fade_no_embark_turn_owner") or "")
                            turn = int(sr.get("fire_and_fade_no_embark_turn", 0) or 0)
                            if owner and owner == str(getattr(p, "id", "") or "") and int(getattr(self, "turn", 0) or 0) == turn:
                                continue
                        try:
                            if not transport.can_transport(unit):
                                continue
                        except Exception:
                            continue
                        if not unit_wholly_within_range_of_unit(transport, unit, range_value):
                            continue
                        # Must not be within Engagement Range of any enemy units.
                        enemies = list(game_map.get_enemy_units(unit) or [])
                        engaged = False
                        for enemy in enemies:
                            if enemy is None or not enemy.is_alive():
                                continue
                            if game_map.is_within_engagement_range(unit, enemy):
                                engaged = True
                                break
                        if engaged:
                            continue
                        candidates.append(unit)
                    if not candidates:
                        continue
                    self._queue_end_of_fight_embark_decision(
                        player=p,
                        transport=transport,
                        candidates=candidates,
                        spec=spec,
                    )

    def _on_phase_end_transport_opponent_movement_embark(self, player=None, phase=None, **_kwargs) -> None:
        """End of opponent's Movement phase: optional embark for empty transports with Mount Up!-style abilities."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        turn_ending_player = player
        if turn_ending_player is None:
            return
        game_map = self.map
        if game_map is None:
            return
        try:
            from ...utility.aura_utils import unit_wholly_within_range_of_unit
        except Exception:
            return

        for opp in list(self.players or []):
            if opp is None or opp is turn_ending_player:
                continue
            army = self._get_player_army(opp)
            if army is None:
                continue
            seen_transports: set[str] = set()
            for transport in list(army.units or []):
                if transport is None:
                    continue
                try:
                    transport = transport.get_attached_unit_root()
                except Exception:
                    pass
                transport_id = str(get_entity_id(transport) or "")
                if transport is None or not transport_id or transport_id in seen_transports:
                    continue
                seen_transports.add(transport_id)
                if not transport.is_alive() or not getattr(transport, "deployed", True):
                    continue
                try:
                    if transport.is_in_reserves() or transport.is_embarked:
                        continue
                except Exception:
                    pass
                if list(getattr(transport, "transport_passengers", []) or []):
                    continue
                try:
                    specs = list(transport.unit_end_of_opponent_movement_embark_specs() or [])
                except Exception:
                    specs = []
                if not specs:
                    continue
                for spec in specs:
                    try:
                        range_value = float(spec.get("range", 0) or 0)
                    except Exception:
                        range_value = 0.0
                    if range_value <= 0:
                        continue
                    keyword = str(spec.get("keyword", "") or "").strip()
                    exclude_keywords = [
                        str(value or "").strip().upper()
                        for value in list(spec.get("exclude_keywords_any", []) or [])
                        if str(value or "").strip()
                    ]
                    candidates = []
                    seen_candidates: set[str] = set()
                    for unit in list(army.units or []):
                        if unit is None or unit is transport:
                            continue
                        try:
                            unit = unit.get_attached_unit_root()
                        except Exception:
                            pass
                        unit_id = str(get_entity_id(unit) or "")
                        if unit is None or not unit_id or unit_id in seen_candidates:
                            continue
                        seen_candidates.add(unit_id)
                        if not unit.is_alive() or not getattr(unit, "deployed", True):
                            continue
                        try:
                            if unit.is_in_reserves():
                                continue
                        except Exception:
                            pass
                        if not getattr(unit, "is_infantry", False):
                            continue
                        if keyword and not unit.has_any_keyword(keyword):
                            continue
                        if exclude_keywords and any(bool(unit.has_any_keyword(value)) for value in exclude_keywords):
                            continue
                        if getattr(unit.round_state, "disembarked_this_round", False):
                            continue
                        sr = getattr(unit, "special_rules", None)
                        if isinstance(sr, dict) and sr.get("fire_and_fade_no_embark_turn_owner"):
                            owner = str(sr.get("fire_and_fade_no_embark_turn_owner") or "")
                            turn = int(sr.get("fire_and_fade_no_embark_turn", 0) or 0)
                            if owner and owner == str(getattr(opp, "id", "") or "") and int(getattr(self, "turn", 0) or 0) == turn:
                                continue
                        try:
                            if not transport.can_transport(unit):
                                continue
                        except Exception:
                            continue
                        if not unit_wholly_within_range_of_unit(transport, unit, range_value):
                            continue
                        enemies = list(game_map.get_enemy_units(unit) or [])
                        engaged = False
                        for enemy in enemies:
                            if enemy is None or not enemy.is_alive():
                                continue
                            if game_map.is_within_engagement_range(unit, enemy):
                                engaged = True
                                break
                        if engaged:
                            continue
                        candidates.append(unit)
                    if not candidates:
                        continue
                    self._queue_opponent_movement_embark_decision(
                        player=opp,
                        transport=transport,
                        candidates=candidates,
                        spec=spec,
                    )

    def _on_phase_end_transport_reactive_disembark(self, player=None, phase=None, **_kwargs) -> None:
        """End of opponent's Movement phase: AIRBORNE INSERTION-style embarked units can disembark."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        turn_ending_player = player
        if turn_ending_player is None:
            return
        for opp in list(self.players or []):
            if opp is None or opp is turn_ending_player:
                continue
            army = self._get_player_army(opp)
            if army is None:
                continue
            seen_transports: set[str] = set()
            for transport in list(getattr(army, "units", []) or []):
                if transport is None:
                    continue
                try:
                    transport = transport.get_attached_unit_root()
                except Exception:
                    pass
                transport_id = str(get_entity_id(transport) or "")
                if transport is None or not transport_id or transport_id in seen_transports:
                    continue
                seen_transports.add(transport_id)
                if not getattr(transport, "is_transport", False):
                    continue
                if not transport.is_alive() or not getattr(transport, "deployed", True):
                    continue
                try:
                    if transport.is_in_reserves() or transport.is_embarked:
                        continue
                except Exception:
                    pass
                if not list(getattr(transport, "transport_passengers", []) or []):
                    continue
                get_ability = getattr(transport, "get_transport_reactive_disembark_ability", None)
                ability = get_ability() if callable(get_ability) else None
                if not isinstance(ability, dict):
                    continue
                if str(ability.get("trigger", "") or "").strip().lower() != "phase_end_opponent_movement":
                    continue
                if bool(getattr(opp, "has_control", lambda: False)()):
                    es = getattr(self, "event_system", None)
                    if es is not None and hasattr(es, "publish"):
                        es.publish(
                            "transport_reactive_disembark_prompt",
                            player=opp,
                            transport=transport,
                            enemy_unit=None,
                            ability=ability,
                            game=self,
                        )
                else:
                    self._queue_transport_reactive_disembark_decisions(
                        player=opp,
                        transport=transport,
                        enemy_unit=None,
                        ability=ability,
                        trigger="phase_end_opponent_movement",
                    )

    def _on_phase_end_resurrection_orb(self, player=None, phase=None, **_kwargs) -> None:
        """End of any phase: queue Necrons Resurrection Orb decisions for both datasheet variants."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if not pname or pname == "SETUP_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        if getattr(self, "map", None) is None:
            return

        current_player = self.get_current_player()
        turn_owner_id = str(getattr(current_player, "id", "") or "")
        turn = int(getattr(self, "turn", 0) or 0)

        def _normalize_rules_text(text: str) -> str:
            cleaned = str(text or "").lower().replace("\u2019", "'").replace("\u0192?T", "'")
            cleaned = re.sub(r"'s\b", "s", cleaned)
            cleaned = re.sub(r"[^a-z0-9]+", " ", cleaned)
            return re.sub(r"\s+", " ", cleaned).strip()

        def _resurrection_orb_variant(text: str) -> str:
            tokens = _normalize_rules_text(text)
            if "while the bearer is leading a unit" in tokens and "resurrect that unit" in tokens:
                return "leading"
            if "select one friendly necrons infantry or necrons mounted unit within 6 of the bearer" in tokens:
                return "nearby"
            return ""

        def _unit_on_battlefield(unit) -> bool:
            if unit is None:
                return False
            is_alive_fn = getattr(unit, "is_alive", None)
            if callable(is_alive_fn):
                if not bool(is_alive_fn()):
                    return False
            elif getattr(unit, "is_alive", True) is False:
                return False
            if not bool(getattr(unit, "deployed", True)):
                return False
            if str(getattr(unit, "reserve_status", "deployed") or "deployed") != "deployed":
                return False
            in_reserves_fn = getattr(unit, "is_in_reserves", None)
            if callable(in_reserves_fn) and bool(in_reserves_fn()):
                return False
            if bool(getattr(unit, "embarked_in", None)) or bool(getattr(unit, "is_embarked", False)):
                return False
            return True

        def _model_is_alive(model) -> bool:
            if model is None:
                return False
            alive_attr = getattr(model, "is_alive", False)
            return bool(alive_attr() if callable(alive_attr) else alive_attr)

        def _army_used_resurrection_orb_this_turn(army) -> bool:
            if army is None:
                return False
            for unit in list(getattr(army, "units", []) or []):
                if unit is None:
                    continue
                sr = getattr(unit, "special_rules", None)
                if not isinstance(sr, dict):
                    continue
                try:
                    used_turn = int(sr.get("resurrection_orb_used_turn", -1))
                except (TypeError, ValueError):
                    continue
                if used_turn != int(turn):
                    continue
                used_owner = str(sr.get("resurrection_orb_used_turn_owner", "") or "")
                if turn_owner_id and used_owner and used_owner != turn_owner_id:
                    continue
                return True
            return False

        for p in list(self.players or []):
            if p is None:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue
            if _army_used_resurrection_orb_this_turn(army):
                continue

            seen_sources: set[str] = set()
            for source_unit in list(getattr(army, "units", []) or []):
                if source_unit is None:
                    continue
                source_unit_id = str(get_entity_id(source_unit) or "")
                if not source_unit_id or source_unit_id in seen_sources:
                    continue
                seen_sources.add(source_unit_id)
                if bool(getattr(source_unit, "has_used_unit_once_per_battle", lambda _k: False)("resurrection_orb")):
                    continue

                root_fn = getattr(source_unit, "get_attached_unit_root", None)
                source_root = root_fn() if callable(root_fn) else source_unit
                if not _unit_on_battlefield(source_root):
                    continue

                alive_models = [m for m in list(getattr(source_unit, "models", []) or []) if _model_is_alive(m)]
                if not alive_models:
                    continue
                bearer_model = alive_models[0]

                iter_abilities = getattr(source_unit, "_iter_active_possible_abilities", None)
                if callable(iter_abilities):
                    abilities = list(iter_abilities() or [])
                else:
                    abilities = list(getattr(source_unit, "possible_abilities", []) or [])

                orb_variant = ""
                ability_name = "Resurrection Orb"
                for ability in list(abilities or []):
                    if isinstance(ability, str):
                        name = str(ability or "")
                        desc = str(ability or "")
                    else:
                        name = str(getattr(ability, "name", "") or "")
                        desc = str(getattr(ability, "description", "") or "") or name
                    if _normalize_rules_text(name) != "resurrection orb":
                        continue
                    orb_variant = _resurrection_orb_variant(desc)
                    if not orb_variant:
                        continue
                    ability_name = str(name or "Resurrection Orb").strip() or "Resurrection Orb"
                    break
                if not orb_variant:
                    continue

                candidates = []
                if orb_variant == "leading":
                    if not bool(getattr(source_unit, "is_attached_leader", False)):
                        continue
                    target_root = source_root
                    if not _unit_on_battlefield(target_root):
                        continue
                    has_rp = getattr(target_root, "attached_unit_has_reanimation_protocols", None)
                    if callable(has_rp) and not bool(has_rp()):
                        continue
                    candidates = [target_root]
                else:
                    seen_targets: set[str] = set()
                    for other in list(getattr(army, "units", []) or []):
                        if other is None:
                            continue
                        other_root_fn = getattr(other, "get_attached_unit_root", None)
                        target_root = other_root_fn() if callable(other_root_fn) else other
                        target_id = str(get_entity_id(target_root) or "")
                        if not target_id or target_id in seen_targets:
                            continue
                        seen_targets.add(target_id)
                        if not _unit_on_battlefield(target_root):
                            continue
                        has_any_keyword = getattr(target_root, "has_any_keyword", None)
                        if not callable(has_any_keyword):
                            continue
                        if not bool(has_any_keyword("NECRONS")):
                            continue
                        if not bool(has_any_keyword("INFANTRY") or has_any_keyword("MOUNTED")):
                            continue
                        has_rp = getattr(target_root, "attached_unit_has_reanimation_protocols", None)
                        if callable(has_rp) and not bool(has_rp()):
                            continue
                        if not self._unit_within_range_of_model(bearer_model, target_root, range_value=6.0):
                            continue
                        candidates.append(target_root)
                    candidates.sort(key=lambda unit: str(get_entity_id(unit) or ""))
                if not candidates:
                    continue

                self._queue_resurrection_orb_decision(
                    player=p,
                    source_unit=source_unit,
                    bearer_model=bearer_model,
                    candidates=candidates,
                    ability_name=ability_name,
                    phase_label=pname.replace("_", " ").title(),
                    variant=orb_variant,
                )

    def _on_phase_end_sweeping_advance(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase end: optional Sweeping Advance move for eligible models."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        game_map = self.map
        if game_map is None:
            return

        for p in list(self.players or []):
            if p is None:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue
            for unit in list(army.units or []):
                if unit is None:
                    continue
                if not unit.is_alive() or not getattr(unit, "deployed", True):
                    continue
                try:
                    if unit.is_in_reserves():
                        continue
                except Exception:
                    pass
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None or not root.is_alive():
                    continue
                try:
                    if not bool(getattr(getattr(root, "round_state", None), "fought_this_phase", False)):
                        continue
                except Exception:
                    continue
                try:
                    models = list(getattr(unit, "models", []) or [])
                except Exception:
                    models = []
                for model in list(models or []):
                    if not getattr(model, "is_alive", True):
                        continue
                    try:
                        specs = list(unit.model_end_of_fight_sweeping_advance_specs(model) or [])
                    except Exception:
                        specs = []
                    if not specs:
                        continue
                    for spec in specs:
                        key = str(spec.get("key") or "sweeping_advance").strip().lower()
                        if not key:
                            key = "sweeping_advance"
                        if getattr(model, "has_used_once_per_battle", lambda _k: False)(key):
                            continue
                        unit_id = maybe_entity_id(root)
                        model_id = maybe_entity_id(model)
                        if not unit_id or not model_id:
                            continue
                        ability_name = str(spec.get("source", "") or "Sweeping Advance").strip() or "Sweeping Advance"
                        message = f"Use {ability_name} for {getattr(unit, 'name', 'Unit')}?"
                        ctx = {
                            "ability_name": ability_name,
                            "phase": "Fight phase",
                            "unit": getattr(unit, "name", "") or "",
                            "model": getattr(model, "name", "") or "",
                            "unit_id": unit_id,
                            "model_id": model_id,
                            "ability_key": key,
                        }
                        self._queue_optional_ability_confirmation(
                            player=p,
                            ability_key="sweeping_advance",
                            ability_name=ability_name,
                            message=message,
                            context=ctx,
                            payload={
                                "unit_id": unit_id,
                                "model_id": model_id,
                                "ability_key": key,
                            },
                            instance_key=f"{unit_id}:{model_id}",
                        )
        return

    def _on_phase_end_raid_and_run(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase end: queue reactive movement from Raid and Run style datasheet abilities."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        game_map = self.map
        if game_map is None:
            return

        def _roll_move_expr(expr: str, unit_obj=None) -> int:
            token = str(expr or "").strip().upper().replace(" ", "")
            if not token:
                return 0
            if token == "M":
                try:
                    move_val = int(float(getattr(unit_obj, "movement", 0) or 0))
                except Exception:
                    move_val = 0
                if move_val <= 0 and unit_obj is not None:
                    try:
                        models = list(getattr(unit_obj, "models", []) or [])
                    except Exception:
                        models = []
                    for model in models:
                        try:
                            move_val = int(float(getattr(model, "movement", 0) or 0))
                        except Exception:
                            move_val = 0
                        if move_val > 0:
                            break
                return int(max(0, move_val))
            if token == "D3+3":
                return int(get_roll("D3") or 0) + 3
            if token == "D6":
                return int(get_roll("D6") or 0)
            if token == "D3":
                return int(get_roll("D3") or 0)
            m = re.fullmatch(r"D(?P<sides>\d+)\+(?P<add>\d+)", token)
            if m:
                sides = int(m.group("sides") or 0)
                add = int(m.group("add") or 0)
                if sides > 0:
                    return int(get_roll(f"D{sides}") or 0) + int(add)
            m = re.fullmatch(r"D(?P<sides>\d+)", token)
            if m:
                sides = int(m.group("sides") or 0)
                if sides > 0:
                    return int(get_roll(f"D{sides}") or 0)
            if token.isdigit():
                return int(token)
            return 0

        for p in list(self.players or []):
            if p is None:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue
            processed_roots: set[str] = set()
            for unit in list(army.units or []):
                if unit is None:
                    continue
                if not unit.is_alive() or not getattr(unit, "deployed", True):
                    continue
                try:
                    if unit.is_in_reserves():
                        continue
                except Exception:
                    pass
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None or not root.is_alive():
                    continue
                root_id = maybe_entity_id(root)
                if not root_id:
                    continue
                if root_id in processed_roots:
                    continue
                processed_roots.add(root_id)
                try:
                    if not getattr(root, "deployed", True):
                        continue
                    if root.is_in_reserves() or root.is_embarked:
                        continue
                except Exception:
                    pass

                try:
                    specs = list(root.unit_end_of_fight_raid_and_run_specs() or [])
                except Exception:
                    specs = []
                if not specs:
                    continue

                round_state = getattr(root, "round_state", None)
                was_eligible = bool(getattr(round_state, "eligible_to_fight_this_phase", False))
                if not was_eligible and bool(getattr(round_state, "fought_this_phase", False)):
                    was_eligible = True

                engaged = False
                for enemy in list(game_map.get_enemy_units(root) or []):
                    if enemy is None or not enemy.is_alive():
                        continue
                    try:
                        if game_map.is_within_engagement_range(root, enemy):
                            engaged = True
                            break
                    except Exception:
                        continue

                for spec in list(specs or []):
                    requires_eligible = bool(spec.get("requires_eligible_to_fight", True))
                    if requires_eligible and not was_eligible:
                        continue
                    engaged_only = bool(spec.get("engaged_only", False))
                    if engaged_only and not engaged:
                        continue
                    if bool(spec.get("not_engaged_only", False)) and engaged:
                        continue
                    ability_name = str(spec.get("source", "") or "Raid and Run").strip() or "Raid and Run"
                    move_kind = str(spec.get("reactive_move_kind", "raid_and_run") or "raid_and_run").strip()
                    if bool(spec.get("select_movement_mode", False)):
                        normal_expr = str(spec.get("normal_move_expr", "") or "").strip() or "6"
                        fall_back_expr = str(spec.get("fall_back_move_expr", "") or "").strip() or "M"
                        options = [DecisionOption.create("Skip", payload={"choice": False})]
                        if not engaged:
                            options.append(
                                DecisionOption.create(
                                    f"Normal Move ({normal_expr})",
                                    payload={"choice": True, "retro_thrusters_mode": "normal_move"},
                                )
                            )
                        if engaged:
                            options.append(
                                DecisionOption.create(
                                    "Fall Back Move",
                                    payload={"choice": True, "retro_thrusters_mode": "fall_back_move"},
                                )
                            )
                        # No eligible mode option; nothing to queue.
                        if len(options) <= 1:
                            continue
                        mode_lines = []
                        if not engaged:
                            mode_lines.append(f"- Normal move up to {normal_expr}\".")
                        if engaged:
                            mode_lines.append("- Fall Back move.")
                        message = (
                            f"{ability_name}: choose one option:\n"
                            + "\n".join(mode_lines)
                        )
                        request = DecisionRequest.create(
                            DECISION_CONFIRM_YES_NO,
                            ability_name,
                            player_id=getattr(p, "id", None),
                            options=options,
                            context={
                                **self._reactive_move_context(
                                    kind=move_kind or "retro_thrusters",
                                    unit_id=root_id,
                                    movement_type="retro_thrusters",
                                    source=ability_name,
                                ),
                                "message": message,
                                "retro_thrusters_normal_move_expr": normal_expr,
                                "retro_thrusters_fall_back_move_expr": fall_back_expr,
                                "retro_thrusters_engaged": bool(engaged),
                            },
                        )
                        self.request_decision(request)
                        continue
                    if engaged:
                        movement_type = str(spec.get("engaged_movement_type", "fall_back") or "").strip().lower()
                    else:
                        movement_type = str(spec.get("non_engaged_movement_type", "move") or "").strip().lower()
                    if movement_type not in {"move", "fall_back"}:
                        continue
                    move_expr = str(spec.get("move_expr", "") or "D3+3").strip() or "D3+3"
                    max_distance = _roll_move_expr(move_expr, root)
                    if max_distance <= 0:
                        continue
                    self._queue_reactive_move_movement_decision(
                        player=p,
                        unit=root,
                        max_distance=int(max_distance),
                        kind=move_kind,
                        movement_type=movement_type,
                        source=ability_name,
                        allow_skip=True,
                    )
        return

    def _on_phase_end_charge_phase_bodyguard_loss(self, player=None, phase=None, **_kwargs) -> None:
        """Charge phase end: failed Leadership test can destroy a Bodyguard model while leading."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "CHARGE_PHASE":
            return
        if player is None:
            return
        if player is not self.get_current_player():
            return

        army = self._get_player_army(player)
        if army is None:
            return
        game_map = self.map
        if game_map is None:
            return

        for unit in list(army.units):
            if unit is None:
                continue
            if not unit.is_alive() or not getattr(unit, "deployed", True):
                continue
            if not unit.is_attached_leader:
                continue
            ability = unit.get_charge_phase_bodyguard_loss_ability()
            if not ability:
                continue
            bodyguard = unit.get_attached_unit_root()
            if bodyguard is None or bodyguard is unit:
                continue
            if not getattr(bodyguard, "deployed", True):
                continue
            if str(getattr(bodyguard, "reserve_status", "deployed")) != "deployed":
                continue
            if bodyguard.is_in_reserves():
                continue
            if bool(getattr(bodyguard, "embarked_in", None)) or bodyguard.is_embarked:
                continue
            if len(bodyguard.models or []) <= 0:
                continue

            engaged = False
            enemies = list(game_map.get_enemy_units(bodyguard) or [])
            for enemy in enemies:
                if enemy is None:
                    continue
                if not getattr(enemy, "deployed", True):
                    continue
                if not enemy.is_alive():
                    continue
                if not game_map.is_within_engagement_range(bodyguard, enemy):
                    continue
                engaged = True
                break
            if engaged:
                continue

            leader_model = None
            for m in list(unit.models or []):
                if not getattr(m, "is_alive", True):
                    continue
                leader_model = m
                break
            if leader_model is None:
                continue

            passed = bool(unit.pass_leadership_check_for_model(leader_model))
            if passed:
                continue

            candidates = [m for m in (bodyguard.models or []) if getattr(m, "is_alive", True)]
            if not candidates:
                continue

            ability_name = str((ability or {}).get("name", "") or "Leadership Test").strip() or "Leadership Test"
            self.queue_bodyguard_loss(
                leader_unit=unit,
                bodyguard_unit=bodyguard,
                ability_name=ability_name,
                player=player,
            )

    def _on_phase_end_the_great_wolf_watches(self, player=None, phase=None, **_kwargs) -> None:
        """Charge phase end: Champions of Fenris units can declare out-of-turn charges."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "CHARGE_PHASE":
            return
        current_player = self.get_current_player()
        if player is None or player is not current_player:
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        try:
            battle_round = int(getattr(self, "turn", 0) or 0)
        except Exception:
            battle_round = 0
        trigger_player_id = str(getattr(current_player, "id", "") or "")
        queue = getattr(self, "decision_queue", None)

        for reacting_player in list(getattr(self, "players", []) or []):
            if reacting_player is None or reacting_player is current_player:
                continue
            reacting_army = self._get_player_army(reacting_player)
            if reacting_army is None:
                continue
            sm_mgr = getattr(reacting_army, "space_marines_detachments", None)
            get_options = getattr(sm_mgr, "get_great_wolf_watches_charge_options", None)
            if not callable(get_options):
                continue
            unit_options = list(get_options(game=self) or [])
            for entry in list(unit_options or []):
                if not isinstance(entry, tuple) and not isinstance(entry, list):
                    continue
                if len(entry) != 2:
                    continue
                reacting_unit, candidates = entry
                if reacting_unit is None:
                    continue
                candidate_units = [u for u in list(candidates or []) if u is not None]
                if not candidate_units:
                    continue
                reacting_unit_id = str(get_entity_id(reacting_unit) or "")
                if not reacting_unit_id:
                    continue

                already_pending = False
                if queue is not None and hasattr(queue, "list"):
                    for req in list(queue.list() or []):
                        if str(getattr(req, "decision_type", "") or "") != DECISION_CHOOSE_QUARRY:
                            continue
                        ctx = dict(getattr(req, "context", {}) or {})
                        if str(ctx.get("ability", "") or "") != "great_wolf_watches_charge":
                            continue
                        if str(ctx.get("unit_id", "") or "") != reacting_unit_id:
                            continue
                        if int(ctx.get("battle_round", battle_round) or battle_round) != battle_round:
                            continue
                        if str(ctx.get("trigger_player_id", "") or "") != trigger_player_id:
                            continue
                        already_pending = True
                        break
                if already_pending:
                    continue

                req_options = [
                    DecisionOption.create(
                        "None",
                        payload={
                            "action": "skip",
                            "unit_id": reacting_unit_id,
                        },
                    )
                ]
                candidate_ids: list[str] = []
                used_labels: set[str] = set()
                for target_unit in list(candidate_units):
                    target_id = str(get_entity_id(target_unit) or "")
                    if not target_id:
                        continue
                    if target_id in candidate_ids:
                        continue
                    candidate_ids.append(target_id)
                    label = str(getattr(target_unit, "name", "") or "Enemy unit")
                    base = label
                    idx = 2
                    while label in used_labels:
                        label = f"{base} ({idx})"
                        idx += 1
                    used_labels.add(label)
                    req_options.append(
                        DecisionOption.create(
                            label,
                            payload={
                                "target_unit_id": target_id,
                                "unit_id": reacting_unit_id,
                            },
                        )
                    )
                if len(req_options) <= 1:
                    continue

                request = DecisionRequest.create(
                    DECISION_CHOOSE_QUARRY,
                    f"The Great Wolf Watches: Select charge target for {getattr(reacting_unit, 'name', 'Unit')} (or None).",
                    player_id=getattr(reacting_player, "id", None),
                    options=req_options,
                    context={
                        "ability": "great_wolf_watches_charge",
                        "ability_name": "The Great Wolf Watches",
                        "phase": "Charge phase",
                        "unit_id": reacting_unit_id,
                        "army_id": str(get_entity_id(reacting_army) or ""),
                        "battle_round": int(battle_round or 0),
                        "trigger_player_id": trigger_player_id,
                        "candidate_unit_ids": list(candidate_ids),
                    },
                )
                self.request_decision(request)

    def _on_charge_declared_shock_and_awe(self, unit=None, target_units=None, **_kwargs) -> None:
        """Godhammer Assault Force: charge target selection for Shock and Awe Battle-shock."""
        if unit is None:
            return
        charging_root = unit.get_attached_unit_root() if hasattr(unit, "get_attached_unit_root") else unit
        if charging_root is None:
            return
        charging_army = charging_root.get_parent_army() if hasattr(charging_root, "get_parent_army") else None
        if charging_army is None:
            return
        sm_mgr = getattr(charging_army, "space_marines_detachments", None)
        if sm_mgr is None:
            return
        is_eligible = getattr(sm_mgr, "shock_and_awe_reacting_unit_is_eligible", None)
        if not callable(is_eligible) or not bool(is_eligible(charging_root, game=self)):
            return
        get_targets = getattr(sm_mgr, "shock_and_awe_charge_target_units", None)
        if not callable(get_targets):
            return
        candidates = list(get_targets(charging_root, declared_targets=target_units, game=self) or [])
        if not candidates:
            return

        charging_unit_id = str(get_entity_id(charging_root) or "")
        if not charging_unit_id:
            return
        acting_player = getattr(charging_army, "player", None)
        if acting_player is None:
            return
        try:
            battle_round = int(getattr(self, "turn", 0) or 0)
        except Exception:
            battle_round = 0

        candidate_ids: list[str] = []
        for target in list(candidates):
            target_id = str(get_entity_id(target) or "")
            if target_id and target_id not in candidate_ids:
                candidate_ids.append(target_id)
        if not candidate_ids:
            return

        if len(candidate_ids) == 1:
            target = candidates[0]
            if target is None:
                return
            take_test = getattr(target, "take_battle_shock_test", None)
            if callable(take_test):
                take_test(current_turn=battle_round or 1)
            return

        queue = getattr(self, "decision_queue", None)
        if queue is not None and hasattr(queue, "list"):
            for req in list(queue.list() or []):
                if str(getattr(req, "decision_type", "") or "") != DECISION_CHOOSE_QUARRY:
                    continue
                ctx = dict(getattr(req, "context", {}) or {})
                if str(ctx.get("ability", "") or "") != "shock_and_awe_battleshock":
                    continue
                if str(ctx.get("unit_id", "") or "") != charging_unit_id:
                    continue
                if int(ctx.get("battle_round", battle_round) or battle_round) != battle_round:
                    continue
                return

        options = []
        used_labels: set[str] = set()
        for target in list(candidates):
            target_id = str(get_entity_id(target) or "")
            if not target_id:
                continue
            label = str(getattr(target, "name", "") or "Enemy unit")
            base = label
            idx = 2
            while label in used_labels:
                label = f"{base} ({idx})"
                idx += 1
            used_labels.add(label)
            options.append(
                DecisionOption.create(
                    label,
                    payload={
                        "unit_id": charging_unit_id,
                        "target_unit_id": target_id,
                    },
                )
            )
        if not options:
            return

        request = DecisionRequest.create(
            DECISION_CHOOSE_QUARRY,
            f"Shock and Awe: Select one charge target for {getattr(charging_root, 'name', 'Unit')} to take a Battle-shock test.",
            player_id=getattr(acting_player, "id", None),
            options=options,
            context={
                "ability": "shock_and_awe_battleshock",
                "ability_name": "Shock and Awe",
                "unit_id": charging_unit_id,
                "army_id": str(get_entity_id(charging_army) or ""),
                "battle_round": int(battle_round or 0),
                "candidate_unit_ids": list(candidate_ids),
            },
        )
        self.request_decision(request)

    def _on_phase_end_flickerjump_mortal_wounds(self, player=None, phase=None, **_kwargs) -> None:
        """Movement phase end: Flickerjump mortal wound rolls for units that used the ability."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        if player is None:
            return
        army = player.get_army() if player is not None else None
        if army is None:
            return
        from ...utility.dice import get_roll
        from ...utility.event_bus import append_action, append_dice

        for unit in list(getattr(army, "units", []) or []):
            if unit is None:
                continue
            if not unit.is_alive() or not getattr(unit, "deployed", True):
                continue
            try:
                if unit.is_in_reserves():
                    continue
            except Exception:
                pass
            sr = getattr(unit, "special_rules", None)
            if not isinstance(sr, dict):
                continue
            owner = str(sr.get("flickerjump_pending_uses_owner", "") or "")
            turn = int(sr.get("flickerjump_pending_uses_turn", 0) or 0)
            if owner and owner != str(getattr(player, "id", "") or ""):
                continue
            if int(getattr(self, "turn", 0) or 0) != turn:
                continue
            uses = int(sr.get("flickerjump_pending_uses", 0) or 0)
            if uses <= 0:
                continue
            ability_name = str(sr.get("flickerjump_source", "") or "Flickerjump").strip() or "Flickerjump"

            for _ in range(int(uses)):
                models = [m for m in list(getattr(unit, "models", []) or []) if getattr(m, "is_alive", True)]
                if not models:
                    break
                rolls = []
                ones = 0
                for _m in models:
                    r = int(get_roll("D6") or 0)
                    rolls.append(r)
                    if r == 1:
                        ones += 1
                if ones > 0:
                    unit._apply_mortal_wounds_to_unit(unit, int(ones), game_map=getattr(self, "map", None))
                append_dice(
                    player,
                    f"{ability_name}: rolls {rolls} => {int(ones)} mortal wounds to {getattr(unit, 'name', 'Unit')}.",
                )
                append_action(
                    player,
                    f"{ability_name}: {getattr(unit, 'name', 'Unit')} suffered {int(ones)} mortal wounds.",
                )

            for k in (
                "flickerjump_pending_uses",
                "flickerjump_pending_uses_turn",
                "flickerjump_pending_uses_owner",
                "flickerjump_source",
            ):
                sr.pop(k, None)
            unit.special_rules = sr

    def _on_phase_end_fight_phase_mortal_wounds(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase end: optional mortal wounds against an engaged enemy unit."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        game_map = self.map
        if game_map is None:
            return
        from ...utility.aura_utils import horizontal_distance_between_bases_2d, vertical_distance_between_bases
        from ...utility.dice import get_roll
        from ...utility.event_bus import append_action, append_dice

        def _model_in_engagement_with_unit(model, target_unit) -> bool:
            if not getattr(model, "is_alive", False):
                return False
            get_collision = getattr(target_unit, "get_models_for_collision", None)
            if callable(get_collision):
                t_models = list(get_collision() or [])
            else:
                t_models = list(target_unit.models or [])
            for t_model in t_models:
                if not getattr(t_model, "is_alive", False):
                    continue
                horizontal = float(horizontal_distance_between_bases_2d(model.model_base, t_model.model_base))
                vertical = float(vertical_distance_between_bases(model.model_base, t_model.model_base))
                if horizontal <= ENGAGEMENT_RANGE_HORIZONTAL and vertical <= ENGAGEMENT_RANGE_VERTICAL:
                    return True
            return False

        def _unit_sort_key(u):
            unit_id = str(get_entity_id(u) or "").strip()
            if unit_id:
                return unit_id
            return str(getattr(u, "name", "") or "")

        def _resolve_mortal_wounds_value(mortal_spec) -> tuple[int, str]:
            if isinstance(mortal_spec, int):
                mortal = int(mortal_spec)
                return max(0, mortal), f"flat={int(max(0, mortal))}"
            token = str(mortal_spec or "").strip().lower()
            if token == "d3":
                roll = int(get_roll("D3") or 0)
                return int(max(0, roll)), f"d3={int(roll)}"
            if token == "d6":
                roll = int(get_roll("D6") or 0)
                return int(max(0, roll)), f"d6={int(roll)}"
            if token.isdigit():
                mortal = int(token)
                return int(max(0, mortal)), f"flat={int(max(0, mortal))}"
            return 0, ""

        for p in list(self.players or []):
            if p is None:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue
            for unit in list(army.units):
                if unit is None:
                    continue
                if not unit.is_alive() or not getattr(unit, "deployed", True):
                    continue
                if unit.is_in_reserves():
                    continue
                if unit.is_embarked:
                    continue

                enemies = list(game_map.get_enemy_units(unit) or [])
                if not enemies:
                    continue

                for model in list(unit.models or []):
                    if not getattr(model, "is_alive", False):
                        continue
                    enemy_roots = []
                    seen_enemy = set()
                    for enemy in enemies:
                        if enemy is None:
                            continue
                        root = enemy.get_attached_unit_root()
                        key = str(get_entity_id(root) or "").strip()
                        if not key:
                            key = f"obj:{id(root)}"
                        if key in seen_enemy:
                            continue
                        seen_enemy.add(key)
                        if not root.is_alive() or not getattr(root, "deployed", True):
                            continue
                        if root.is_in_reserves():
                            continue
                        if root.is_embarked:
                            continue
                        enemy_roots.append(root)
                    if not enemy_roots:
                        continue
                    enemy_roots = sorted(enemy_roots, key=_unit_sort_key)

                    specs = unit.model_end_fight_phase_engagement_mortal_wounds_specs(model) or []
                    for spec in specs:
                        candidates = [root for root in enemy_roots if _model_in_engagement_with_unit(model, root)]
                        if not candidates:
                            continue
                        self._queue_mortal_wounds_target_decision(
                            player=p,
                            unit=unit,
                            model=model,
                            candidates=list(candidates),
                            spec=spec,
                            kind="fight_phase_end",
                            allow_skip=True,
                            phase="Fight phase",
                        )

                    range_specs = unit.model_fight_phase_end_enemy_within_range_mortal_threshold_specs(model) or []
                    if not range_specs:
                        continue
                    source_unit = getattr(model, "parent_unit", None) or unit
                    source_player = getattr(source_unit.get_parent_army(), "player", None)
                    if source_player is None:
                        source_player = p

                    for spec in range_specs:
                        range_token = str(spec.get("range", "") or "").strip()
                        threshold_token = str(spec.get("threshold", "") or "").strip()
                        if not range_token.isdigit() or not threshold_token.isdigit():
                            continue
                        range_value = int(range_token)
                        threshold = int(threshold_token)
                        if range_value <= 0 or threshold <= 0:
                            continue
                        mortal_spec = spec.get("mortal_wounds")
                        ability_name = str(spec.get("source", "") or "Fight phase mortals").strip() or "Fight phase mortals"
                        targets = [
                            root for root in enemy_roots
                            if self._unit_within_range_of_model(model, root, range_value=float(range_value))
                        ]
                        if not targets:
                            continue

                        for target_unit in targets:
                            trigger_roll = int(get_roll("D6") or 0)
                            mortal_wounds = 0
                            mortal_note = ""
                            if trigger_roll >= threshold:
                                mortal_wounds, mortal_note = _resolve_mortal_wounds_value(mortal_spec)
                                if mortal_wounds > 0:
                                    source_unit._apply_mortal_wounds_to_unit(
                                        target_unit,
                                        int(mortal_wounds),
                                        game_map=getattr(self, "map", None),
                                    )

                            target_name = str(getattr(target_unit, "name", "Unit") or "Unit")
                            dice_summary = f"roll {int(trigger_roll)} ({int(threshold)}+)"
                            if mortal_note:
                                dice_summary = f"{dice_summary}, {mortal_note}"
                            append_dice(
                                source_player,
                                f"{ability_name}: {target_name} {dice_summary} -> {int(mortal_wounds)} mortal wounds.",
                            )
                            if mortal_wounds > 0:
                                append_action(
                                    source_player,
                                    f"{ability_name}: {target_name} suffers {int(mortal_wounds)} mortal wounds.",
                                )
                            else:
                                append_action(
                                    source_player,
                                    f"{ability_name}: {target_name} suffers no mortal wounds.",
                                )

    def _on_phase_end_opponent_fight_phase_strategic_reserves(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase end: Dedicated Gunship may move eligible bearer units into Strategic Reserves."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        turn_ending_player = player
        if turn_ending_player is None:
            return
        game_map = self.map
        if game_map is None:
            return

        for opp in list(self.players or []):
            if opp is None or opp is turn_ending_player:
                continue
            army = self._get_player_army(opp)
            if army is None:
                continue
            seen = set()
            for unit in list(getattr(army, "units", []) or []):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                uid = get_entity_id(root)
                if not uid or uid in seen:
                    continue
                seen.add(uid)
                if not root.is_alive() or not getattr(root, "deployed", True):
                    continue
                if root.is_in_reserves() or root.is_embarked:
                    continue
                ability = root.get_end_of_opponent_turn_strategic_reserves_ability()
                if not ability:
                    continue
                ability_key = str(ability.get("ability_key") or "").strip().lower()
                trigger_phase = str(ability.get("trigger_phase", "") or "OPPONENT_TURN_END").strip().upper()
                if not trigger_phase:
                    trigger_phase = "OPPONENT_TURN_END"
                if ability_key != "dedicated_gunship" and trigger_phase != "OPPONENT_FIGHT_PHASE_END":
                    continue
                if bool(ability.get("once_per_battle")) and root.has_used_unit_once_per_battle(ability_key):
                    continue
                engaged = False
                for enemy in list(game_map.get_enemy_units(root) or []):
                    if not enemy.is_alive() or not getattr(enemy, "deployed", True):
                        continue
                    if game_map.is_within_engagement_range(root, enemy):
                        engaged = True
                        break
                if engaged:
                    continue
                ability_name = str(ability.get("name", "") or "Dedicated Gunship").strip() or "Dedicated Gunship"
                ctx = {
                    "ability_name": ability_name,
                    "unit": getattr(root, "name", "") or "",
                    "phase": "End of opponent's Fight phase",
                    "unit_id": uid,
                    "ability_key": ability_key,
                    "once_per_battle": bool(ability.get("once_per_battle")),
                }
                message = (
                    f"{getattr(root, 'name', 'Unit')} can enter Strategic Reserves at the end of the opponent's Fight phase.\n\n"
                    "Use this ability?"
                )
                self._queue_optional_ability_confirmation(
                    player=opp,
                    ability_key="opponent_turn_strategic_reserves",
                    ability_name=ability_name,
                    message=message,
                    context=ctx,
                    payload={
                        "unit_id": uid,
                        "ability_key": ability_key,
                        "once_per_battle": bool(ability.get("once_per_battle")),
                    },
                    instance_key=f"opponent_fight_phase_strat_reserves:{ability_key}:{uid}",
                )

    def _on_phase_end_nomad_strategist(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase end: Nomad Strategist offers a single spend-and-select Strategic Reserves choice."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        turn_ending_player = player
        if turn_ending_player is None:
            return
        from itertools import combinations

        try:
            current_turn = int(getattr(self, "turn", 0) or 0)
        except Exception:
            current_turn = 0

        for source_player in list(self.players or []):
            if source_player is None or source_player is turn_ending_player:
                continue
            army = self._get_player_army(source_player)
            if army is None:
                continue
            detachment_mgr = getattr(army, "leagues_of_votann_detachments", None)
            if detachment_mgr is None or not bool(getattr(detachment_mgr, "is_persecution_prospect", lambda: False)()):
                continue
            pe = getattr(army, "prioritised_efficiency", None)
            try:
                available_yp = int(getattr(pe, "yield_points", 0) or 0)
            except Exception:
                available_yp = 0

            for source_root, source_member, source_sr, _bearer in list(
                detachment_mgr._iter_enhancement_sources(
                    "enhancement_nomad_strategist",
                    require_bearer_alive=True,
                )
                or []
            ):
                if source_root is None or source_member is None or not isinstance(source_sr, dict):
                    continue
                if bool(source_sr.get("enhancement_nomad_strategist_requires_bearer_on_battlefield", True)) and not bool(
                    getattr(detachment_mgr, "_unit_is_on_battlefield", lambda _u: False)(source_root)
                ):
                    continue
                once_key = str(source_sr.get("enhancement_nomad_strategist_once_key", "") or "nomad_strategist").strip().lower()
                if not once_key:
                    once_key = "nomad_strategist"
                root_has_used = getattr(source_root, "has_used_unit_once_per_battle", None)
                if callable(root_has_used) and bool(root_has_used(once_key)):
                    continue
                member_has_used = getattr(source_member, "has_used_unit_once_per_battle", None)
                if source_member is not source_root and callable(member_has_used) and bool(member_has_used(once_key)):
                    continue
                source_unit_id = str(get_entity_id(source_root) or "")
                if not source_unit_id:
                    continue
                if detachment_mgr._pending_choose_quarry_request(
                    self,
                    abilities=("nomad_strategist",),
                    player_id=str(getattr(source_player, "id", "") or ""),
                    source_unit_id=source_unit_id,
                ):
                    continue

                candidate_units: list[Any] = []
                for candidate_root in list(detachment_mgr._iter_unique_army_roots() or []):
                    if not bool(
                        getattr(detachment_mgr, "nomad_strategist_target_eligible", lambda *_a, **_k: False)(
                            candidate_root,
                            game=self,
                            owner_id=str(getattr(source_player, "id", "") or ""),
                        )
                    ):
                        continue
                    candidate_units.append(candidate_root)
                candidate_units = sorted(candidate_units, key=lambda unit: str(get_entity_id(unit) or ""))
                if not candidate_units:
                    continue

                try:
                    configured_max_yp = int(source_sr.get("enhancement_nomad_strategist_max_yp_spend", 4) or 4)
                except Exception:
                    configured_max_yp = 4
                max_yp_spend = max(0, min(int(configured_max_yp), int(available_yp)))
                options: list[DecisionOption] = [
                    DecisionOption.create(
                        "None",
                        payload={
                            "action": "skip",
                            "source_unit_id": source_unit_id,
                            "selected_unit_ids": [],
                            "yp_spend": 0,
                        },
                    )
                ]
                for yp_spend in range(0, int(max_yp_spend) + 1):
                    max_units = 1 + int(yp_spend // 2)
                    combo_cap = min(int(max_units), len(candidate_units))
                    for count in range(1, combo_cap + 1):
                        for combo in combinations(candidate_units, count):
                            selected_ids = [
                                str(get_entity_id(unit) or "")
                                for unit in list(combo)
                                if str(get_entity_id(unit) or "")
                            ]
                            if len(selected_ids) != count:
                                continue
                            label = ", ".join(str(getattr(unit, "name", "Unit") or "Unit") for unit in list(combo))
                            options.append(
                                DecisionOption.create(
                                    f"Spend {int(yp_spend)} YP: {label}",
                                    payload={
                                        "source_unit_id": source_unit_id,
                                        "selected_unit_ids": list(selected_ids),
                                        "yp_spend": int(yp_spend),
                                        "ability_key": once_key,
                                    },
                                )
                            )
                if len(options) <= 1:
                    continue
                ability_name = str(source_sr.get("enhancement_nomad_strategist_source", "") or "Nomad Strategist").strip()
                if not ability_name:
                    ability_name = "Nomad Strategist"
                request = DecisionRequest.create(
                    DECISION_CHOOSE_QUARRY,
                    f"{ability_name}: select one or more Hernkyn units and an optional YP spend.",
                    player_id=getattr(source_player, "id", None),
                    options=options,
                    context={
                        "ability": "nomad_strategist",
                        "ability_name": ability_name,
                        "phase": "End of opponent's Fight phase",
                        "source_unit_id": source_unit_id,
                        "candidate_unit_ids": [str(get_entity_id(unit) or "") for unit in list(candidate_units)],
                        "max_yp_spend": int(max_yp_spend),
                        "once_key": once_key,
                        "turn_owner": str(getattr(source_player, "id", "") or ""),
                        "turn": int(current_turn or 0),
                    },
                )
                self.request_decision(request)

    def _on_phase_end_fight_phase_destroyed_strategic_reserves(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase end: units that destroyed enemies can enter Strategic Reserves (Warp Strike)."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        game_map = self.map
        if game_map is None:
            return
        tracked = set(self._phase_enemy_unit_destroyers.get(pname, set()) or set())
        if not tracked:
            return

        for p in list(self.players or []):
            if p is None:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue
            seen = set()
            for unit in list(getattr(army, "units", []) or []):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                uid = get_entity_id(root)
                if not uid or uid in seen:
                    continue
                seen.add(uid)
                if uid not in tracked:
                    continue
                if not root.is_alive() or not getattr(root, "deployed", True):
                    continue
                if root.is_in_reserves() or root.is_embarked:
                    continue
                round_state = getattr(root, "round_state", None)
                if not bool(getattr(round_state, "fought_this_phase", False)):
                    continue
                ability = root.get_end_of_fight_phase_destroyed_strategic_reserves_ability()
                if not ability:
                    continue
                sr = getattr(root, "special_rules", None)
                if not isinstance(sr, dict):
                    sr = {}
                sr["fight_phase_destroyed_strategic_reserves_pending"] = True
                try:
                    sr["fight_phase_destroyed_strategic_reserves_turn"] = int(getattr(self, "turn", 0) or 0)
                except Exception:
                    sr["fight_phase_destroyed_strategic_reserves_turn"] = 0
                sr["fight_phase_destroyed_strategic_reserves_turn_owner"] = str(getattr(p, "id", "") or "")
                root.special_rules = sr
                engaged = False
                for enemy in list(game_map.get_enemy_units(root) or []):
                    if not enemy.is_alive() or not getattr(enemy, "deployed", True):
                        continue
                    if game_map.is_within_engagement_range(root, enemy):
                        engaged = True
                        break
                if engaged:
                    continue
                unit_id = get_entity_id(root)
                ability_name = str(ability.get("name", "") or "Strategic Reserves").strip() or "Strategic Reserves"
                ctx = {
                    "ability_name": ability_name,
                    "unit": getattr(root, "name", "") or "",
                    "phase": "End of Fight phase",
                    "unit_id": unit_id,
                }
                message = (
                    f"{getattr(root, 'name', 'Unit')} can enter Strategic Reserves at the end of the Fight phase.\n\n"
                    "Use this ability?"
                )
                self._queue_optional_ability_confirmation(
                    player=p,
                    ability_key="fight_phase_destroyed_strategic_reserves",
                    ability_name=ability_name,
                    message=message,
                    context=ctx,
                    payload={"unit_id": unit_id},
                    instance_key=str(unit_id or ""),
                )

    def _on_phase_end_wrath_of_the_first_khan(self, player=None, phase=None, **_kwargs) -> None:
        """Fight phase end: tracked Suboden Khan units can make a Normal move up to 6"."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        game_map = self.map
        if game_map is None:
            return
        tracked = set(self._phase_enemy_unit_destroyers.get(pname, set()) or set())
        if not tracked:
            return

        seen = set()
        for p in list(self.players or []):
            if p is None:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue
            sm_mgr = getattr(army, "space_marines_detachments", None)
            applies_fn = getattr(sm_mgr, "wrath_of_the_first_khan_applies", None) if sm_mgr is not None else None
            if not callable(applies_fn):
                continue
            for unit in list(getattr(army, "units", []) or []):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                uid = get_entity_id(root)
                if not uid or uid in seen:
                    continue
                seen.add(uid)
                if uid not in tracked:
                    continue
                if not root.is_alive() or not getattr(root, "deployed", True):
                    continue
                try:
                    if root.is_in_reserves() or root.is_embarked:
                        continue
                except Exception:
                    pass
                if not bool(applies_fn(root)):
                    continue
                engaged = False
                for enemy in list(game_map.get_enemy_units(root) or []):
                    if not enemy.is_alive() or not getattr(enemy, "deployed", True):
                        continue
                    if game_map.is_within_engagement_range(root, enemy):
                        engaged = True
                        break
                if engaged:
                    continue
                queue_move = getattr(self, "_queue_reactive_move_movement_decision", None)
                if not callable(queue_move):
                    continue
                queue_move(
                    player=p,
                    unit=root,
                    max_distance=6,
                    kind="wrath_of_the_first_khan",
                    movement_type="normal",
                    source="Wrath of the First Khan",
                    allow_skip=True,
                )

    def _on_phase_end_plough_through_the_enemy(self, player=None, phase=None, **_kwargs) -> None:
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        game_map = self.map
        if game_map is None:
            return
        tracked = set(self._phase_enemy_unit_destroyers.get(pname, set()) or set())
        if not tracked:
            return
        from ...utility.aura_utils import unit_within_range_of_unit
        from ...utility.event_bus import append_action
        turn = int(getattr(self, "turn", 0) or 0)

        seen: set[str] = set()
        for p in list(self.players or []):
            if p is None:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue
            for unit in list(getattr(army, "units", []) or []):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                uid = str(get_entity_id(root) or "")
                if not uid or uid in seen:
                    continue
                seen.add(uid)
                if uid not in tracked:
                    continue
                if not root.is_alive() or not getattr(root, "deployed", True):
                    continue
                try:
                    if root.is_in_reserves() or root.is_embarked:
                        continue
                except Exception:
                    pass
                if not bool(getattr(root, "has_plough_through_the_enemy", lambda: False)()):
                    continue
                hit_any = False
                tested_targets: set[str] = set()
                for enemy in list(game_map.get_enemy_units(root) or []):
                    if enemy is None:
                        continue
                    try:
                        enemy_root = enemy.get_attached_unit_root()
                    except Exception:
                        enemy_root = enemy
                    enemy_id = str(get_entity_id(enemy_root) or "")
                    if not enemy_id or enemy_id in tested_targets:
                        continue
                    tested_targets.add(enemy_id)
                    if not enemy_root.is_alive() or not getattr(enemy_root, "deployed", True):
                        continue
                    try:
                        if enemy_root.is_in_reserves() or enemy_root.is_embarked:
                            continue
                    except Exception:
                        pass
                    if not unit_within_range_of_unit(root, enemy_root, 6.0, use_attached_aggregate=True):
                        continue
                    enemy_root.take_battle_shock_test(turn)
                    hit_any = True
                if hit_any:
                    append_action(
                        p,
                        f"Plough Through the Enemy: enemy units within 6\" of {getattr(root, 'name', 'Unit')} take Battle-shock tests.",
                    )

