    def _on_phase_end_leadership_cp_gain(self, player=None, phase=None, **_kwargs) -> None:
        """End of Shooting/Fight phase: Leadership test to gain CP after destroying enemy units."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname == "COMMAND_PHASE":
            if player is None:
                return
            if player is not self.get_current_player():
                return
            army = self._get_player_army(player)
            if army is None:
                return
            from ...utility.event_bus import append_action, append_dice

            def _unit_sort_key(u):
                try:
                    return str(get_entity_id(u))
                except Exception:
                    return str(getattr(u, "name", "") or "")

            processed_roots: set[str] = set()
            processed_models: set[str] = set()
            for unit in sorted(list(army.units or []), key=_unit_sort_key):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None:
                    continue
                root_id = str(get_entity_id(root) or "")
                if root_id and root_id in processed_roots:
                    continue
                if root_id:
                    processed_roots.add(root_id)
                if not root.is_alive() or not getattr(root, "deployed", True):
                    continue
                if root.is_in_reserves() or root.is_embarked:
                    continue
                sr = getattr(root, "special_rules", None)
                if isinstance(sr, dict):
                    end_roll_specs = list(sr.get("command_phase_end_bonus_cp_roll_specs", []) or [])
                else:
                    end_roll_specs = []
                for spec in end_roll_specs:
                    if not isinstance(spec, dict):
                        continue
                    try:
                        dice_count = int(spec.get("dice_count", 0) or 0)
                    except Exception:
                        dice_count = 0
                    try:
                        threshold = int(spec.get("threshold", 0) or 0)
                    except Exception:
                        threshold = 0
                    try:
                        cp_gain = int(spec.get("cp", 0) or 0)
                    except Exception:
                        cp_gain = 0
                    if dice_count <= 0 or threshold <= 0 or cp_gain <= 0:
                        continue
                    source = str(spec.get("source", "") or "Command phase end CP roll").strip() or "Command phase end CP roll"
                    roll_spec = f"{int(dice_count)}D6"
                    try:
                        rolled = int(get_roll(roll_spec) or 0)
                    except Exception:
                        rolled = 0
                    append_dice(
                        player,
                        f"{source}: rolled {roll_spec}={int(rolled)} (need {int(threshold)}+).",
                    )
                    if int(rolled) < int(threshold):
                        append_action(
                            player,
                            f"{source}: failed to gain CP ({int(rolled)} < {int(threshold)}).",
                        )
                        continue
                    try:
                        gained = int(player.gain_command_points(int(cp_gain), reason=source) or 0)
                    except Exception:
                        gained = 0
                    append_action(
                        player,
                        f"{source}: gained {int(gained)}CP.",
                    )
                try:
                    models = list(getattr(unit, "models", []) or [])
                except Exception:
                    models = []
                if not models:
                    continue

                def _model_sort_key(m):
                    try:
                        return str(get_entity_id(m))
                    except Exception:
                        return str(getattr(m, "name", "") or "")

                spec_fn = getattr(unit, "model_command_phase_end_leadership_cp_gain_specs", None)
                if not callable(spec_fn):
                    continue
                for model in sorted([m for m in models if getattr(m, "is_alive", True)], key=_model_sort_key):
                    mid = str(get_entity_id(model) or "")
                    if not mid or mid in processed_models:
                        continue
                    processed_models.add(mid)
                    specs = spec_fn(model) or []
                    for spec in specs:
                        if spec.get("type") != "command_phase_end_leadership_cp_gain":
                            continue
                        cp = int(spec.get("cp", 1) or 1)
                        if cp <= 0:
                            continue
                        if not bool(unit.pass_leadership_check_for_model(model)):
                            continue
                        gained = int(player.gain_command_points(cp, reason=spec.get("source_ability", "")) or 0)
                        self.event_system.publish(
                            "command_points_gained",
                            player=player,
                            amount=gained,
                            reason=spec.get("source_ability", ""),
                            unit=unit,
                        )
            return
        if pname not in ("SHOOTING_PHASE", "FIGHT_PHASE"):
            return
        if player is None:
            return
        if player is not self.get_current_player():
            return
        army = self._get_player_army(player)
        if army is None:
            return
        tracked = set(self._phase_enemy_unit_destroyers.get(pname, set()) or set())
        if not tracked:
            return

        processed: set[str] = set()
        for unit in list(army.units):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            uid = get_entity_id(root)
            if not uid or uid in processed:
                continue
            processed.add(uid)
            if uid not in tracked:
                continue
            if not root.is_alive() or not getattr(root, "deployed", True):
                continue
            if root.is_in_reserves() or root.is_embarked:
                continue

            specs = root.get_phase_end_leadership_cp_gain_specs() or []
            for spec in specs:
                if spec.get("type") != "phase_end_leadership_cp_gain":
                    continue
                cp = int(spec.get("cp", 1) or 1)
                if cp <= 0:
                    continue
                if not bool(root.pass_leadership_check()):
                    continue
                gained = int(player.gain_command_points(cp, reason=spec.get("source_ability", "")) or 0)
                self.event_system.publish(
                    "command_points_gained",
                    player=player,
                    amount=gained,
                    reason=spec.get("source_ability", ""),
                    unit=root,
                )

        self._phase_enemy_unit_destroyers[pname] = set()

    def _on_phase_end_command_phase_regain_wounds(self, player=None, phase=None, **_kwargs) -> None:
        """End of Command phase: apply passive self-heal abilities that trigger at Command phase end."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        apply_regain = getattr(self, "_apply_command_phase_regain_wounds", None)
        if callable(apply_regain):
            apply_regain(player, timing="end")

    def _on_phase_end_command_phase_mortal_table(self, player=None, phase=None, **_kwargs) -> None:
        """End of Command phase: queue optional once-per-battle mortal table abilities (e.g., Lord of the Storm)."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        army = self._get_player_army(player)
        if army is None:
            return

        def _unit_sort_key(unit):
            try:
                return str(get_entity_id(unit))
            except Exception:
                return str(getattr(unit, "name", "") or "")

        def _model_sort_key(model):
            try:
                return str(get_entity_id(model))
            except Exception:
                return str(getattr(model, "name", "") or "")

        processed_roots: set[str] = set()
        for unit in sorted(list(getattr(army, "units", []) or []), key=_unit_sort_key):
            if unit is None:
                continue
            try:
                root = unit.get_attached_unit_root()
            except Exception:
                root = unit
            if root is None:
                continue
            root_id = str(get_entity_id(root) or "")
            if not root_id or root_id in processed_roots:
                continue
            processed_roots.add(root_id)
            if not bool(getattr(root, "is_alive", lambda: False)()):
                continue
            if not bool(getattr(root, "deployed", False)):
                continue
            try:
                if root.is_in_reserves() or root.is_embarked:
                    continue
            except Exception:
                pass

            spec_fn = getattr(root, "model_command_phase_end_enemy_within_range_mortal_table_specs", None)
            if not callable(spec_fn):
                continue
            try:
                models = list(root.get_attached_unit_models() or [])
            except Exception:
                models = list(getattr(root, "models", []) or [])
            alive_models = [m for m in list(models or []) if getattr(m, "is_alive", False)]
            if not alive_models:
                continue

            for model in sorted(alive_models, key=_model_sort_key):
                model_id = str(get_entity_id(model) or "")
                if not model_id:
                    continue
                specs = list(spec_fn(model) or [])
                for spec in specs:
                    ability_key = str(spec.get("ability_key", "") or "lord_of_the_storm").strip().lower()
                    if not ability_key:
                        ability_key = "lord_of_the_storm"
                    if getattr(model, "has_used_once_per_battle", lambda _k: False)(ability_key):
                        continue
                    try:
                        range_value = int(spec.get("range", 0) or 0)
                    except Exception:
                        range_value = 0
                    if range_value <= 0:
                        continue
                    ability_name = str(spec.get("source", "") or "Command phase mortals").strip() or "Command phase mortals"
                    ctx = {
                        "ability": "lord_of_the_storm",
                        "ability_key": ability_key,
                        "ability_name": ability_name,
                        "phase": "Command phase",
                        "unit": getattr(root, "name", "") or "",
                        "unit_id": root_id,
                        "model": getattr(model, "name", "") or "",
                        "model_id": model_id,
                        "range": int(range_value),
                    }
                    self._queue_optional_ability_confirmation(
                        player=player,
                        ability_key="lord_of_the_storm",
                        ability_name=ability_name,
                        message=f"Activate {ability_name} for {getattr(model, 'name', 'Model')}?",
                        context=ctx,
                        payload={
                            "unit_id": root_id,
                            "model_id": model_id,
                            "ability_key": ability_key,
                            "range": int(range_value),
                        },
                        instance_key=f"{model_id}:{ability_key}",
                    )

    def _on_phase_start_adepta_sororitas_enhancements(self, player=None, phase=None, **_kwargs) -> None:
        """Movement phase start: Army of Faith Divine Aspect target selection."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        if player is None or player is not self.get_current_player():
            return
        army = self._get_player_army(player)
        if army is None:
            return
        mgr = getattr(army, "adepta_sororitas_detachments", None)
        queue_fn = getattr(mgr, "queue_divine_aspect_selection_requests", None) if mgr is not None else None
        if callable(queue_fn):
            queue_fn(game=self, player=player)

    def _on_phase_end_acts_of_faith_enhancements(self, player=None, phase=None, **_kwargs) -> None:
        """End of Command phase: resolve Acts of Faith enhancement effects (e.g. Chaplet of Sacrifice)."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "COMMAND_PHASE":
            return
        if player is None:
            return
        if player is not self.get_current_player():
            return
        army = self._get_player_army(player)
        if army is None:
            return
        mgr = getattr(army, "acts_of_faith", None)
        if mgr is None:
            return
        on_phase_end = getattr(mgr, "on_command_phase_end", None)
        if not callable(on_phase_end):
            return
        on_phase_end(game=self, player=player)

    def _on_phase_end_daemonic_patrons(self, player=None, phase=None, **_kwargs) -> None:
        """End of Fight phase: destroy one model if Daemonic Patrons was called and no enemy models were destroyed."""
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "FIGHT_PHASE":
            return
        tracked = set(self._phase_enemy_model_destroyers.get(pname, set()) or set())
        seen: set[str] = set()

        for p in list(self.players or []):
            if p is None:
                continue
            army = self._get_player_army(p)
            if army is None:
                continue
            for unit in list(getattr(army, "units", []) or []):
                if unit is None:
                    continue
                try:
                    root = unit.get_attached_unit_root()
                except Exception:
                    root = unit
                if root is None:
                    continue
                uid = get_entity_id(root)
                if not uid or uid in seen:
                    continue
                seen.add(uid)
                if not root.is_alive() or not getattr(root, "deployed", True):
                    continue
                if root.is_in_reserves() or root.is_embarked:
                    continue
                sr = getattr(root, "special_rules", None)
                if not isinstance(sr, dict) or not sr.get("daemonic_patrons_active"):
                    continue
                if uid in tracked:
                    continue

                ability_name = str(sr.get("daemonic_patrons_source", "") or "Daemonic Patrons").strip() or "Daemonic Patrons"
                owner = getattr(root.get_parent_army(), "player", None)
                if owner is None:
                    continue

                existing = [
                    req
                    for req in list(self.decision_queue.list() or [])
                    if getattr(req, "decision_type", None) == DECISION_ALLOCATE_DAMAGE
                    and str(getattr(req, "context", {}).get("selection_kind", "") or "") == "daemonic_patrons_loss"
                    and str(getattr(req, "context", {}).get("unit_id", "") or "") == uid
                ]
                if existing:
                    continue

                try:
                    models = list(root.get_attached_unit_models() or [])
                except Exception:
                    models = list(getattr(root, "models", []) or [])
                alive_models = []
                for m in models:
                    try:
                        alive = getattr(m, "is_alive", True)
                        alive = alive() if callable(alive) else bool(alive)
                    except Exception:
                        alive = True
                    if alive:
                        alive_models.append(m)
                if not alive_models:
                    continue
                try:
                    alive_models.sort(key=lambda m: str(get_entity_id(m) or ""))
                except Exception:
                    alive_models = list(alive_models)

                options = []
                used_labels = set()
                for model in alive_models:
                    label = str(getattr(model, "name", "") or "Model")
                    base = label
                    idx = 2
                    while label in used_labels:
                        label = f"{base} ({idx})"
                        idx += 1
                    used_labels.add(label)
                    options.append(DecisionOption.create(label, payload={"model_id": get_entity_id(model)}))
                allowed_ids = [get_entity_id(m) for m in alive_models if get_entity_id(m)]
                ctx = {
                    "selection_kind": "daemonic_patrons_loss",
                    "ability_name": ability_name,
                    "phase": "Fight phase",
                    "unit_id": uid,
                    "allowed_model_ids": allowed_ids,
                    "reason": f"{ability_name}: Destroy one model",
                }
                request = DecisionRequest.create(
                    DECISION_ALLOCATE_DAMAGE,
                    f"{ability_name}: Select model to destroy",
                    player_id=getattr(owner, "id", None),
                    options=options,
                    context=ctx,
                )
                self.request_decision(request)

        self._phase_enemy_model_destroyers[pname] = set()

    def _on_phase_end_setup_reactive_shoot_or_charge(self, player=None, phase=None, **_kwargs) -> None:
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        current_player = self.get_current_player()
        if current_player is None:
            return
        game_map = getattr(self, "map", None)
        if game_map is None:
            return

        for p in list(self.players or []):
            if p is None:
                raise RuntimeError("Setup reactive shoot/charge requires players.")
            if p is current_player:
                continue
            army = p.get_army()
            if army is None:
                raise RuntimeError(f"Setup reactive shoot/charge requires an army for {p.name}.")
            seen = set()
            for unit in list(army.units):
                if unit is None:
                    continue
                root = unit.get_attached_unit_root()
                if root is None:
                    continue
                rid = get_entity_id(root)
                if rid in seen:
                    continue
                seen.add(rid)
                rule = root.get_setup_reactive_shoot_or_charge_rule()
                if not rule:
                    continue
                if root.setup_reactive_shoot_or_charge_used_this_phase(self):
                    continue
                if not root.can_setup_reactive_shoot_or_charge(game=self, game_map=game_map):
                    root.clear_setup_reactive_shoot_or_charge_candidates(self)
                    continue
                candidate_ids = root.get_setup_reactive_shoot_or_charge_candidates(self)
                if not candidate_ids:
                    continue
                candidates = []
                for cid in candidate_ids:
                    enemy = self._resolve_unit_by_id(str(cid))
                    if enemy is None:
                        continue
                    if not enemy.is_alive():
                        continue
                    if not getattr(enemy, "deployed", True):
                        continue
                    if enemy.get_parent_army() == root.get_parent_army():
                        continue
                    candidates.append(enemy)
                if not candidates:
                    root.clear_setup_reactive_shoot_or_charge_candidates(self)
                    continue
                actionable = []
                for enemy in candidates:
                    if self._setup_reactive_available_actions(root, enemy):
                        actionable.append(enemy)
                if not actionable:
                    root.clear_setup_reactive_shoot_or_charge_candidates(self)
                    continue
                if p.has_control():
                    es = getattr(self, "event_system", None)
                    if es is None or not hasattr(es, "subscribers"):
                        raise RuntimeError("Event system missing for setup reactive prompt.")
                    subs = getattr(es, "subscribers", None)
                    if not isinstance(subs, dict):
                        raise RuntimeError("Event system subscribers not configured.")
                    if subs.get("setup_reactive_shoot_charge_prompt"):
                        es.publish(
                            "setup_reactive_shoot_charge_prompt",
                            player=p,
                            unit=root,
                            candidates=list(actionable),
                            rule=rule,
                            game=self,
                        )
                else:
                    self._queue_setup_reactive_target_decision(
                        player=p,
                        unit=root,
                        candidates=list(actionable),
                        rule=rule,
                    )
                root.clear_setup_reactive_shoot_or_charge_candidates(self)

    def _on_phase_end_hyperspace_hunters(self, player=None, phase=None, **_kwargs) -> None:
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "MOVEMENT_PHASE":
            return
        current_player = self.get_current_player()
        if current_player is None:
            return
        if player is None or player is not current_player:
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return
        game_map = getattr(self, "map", None)
        if game_map is None:
            return

        try:
            battle_round = int(getattr(self, "turn", 0) or 0)
        except Exception:
            battle_round = 0
        trigger_player_id = str(getattr(current_player, "id", "") or "")
        queue = getattr(self, "decision_queue", None)
        can_shoot_fn = getattr(self, "_setup_reactive_can_shoot_target", None)

        for reacting_player in list(self.players or []):
            if reacting_player is None or reacting_player is current_player:
                continue
            reacting_army = self._get_player_army(reacting_player)
            if reacting_army is None:
                continue
            seen = set()
            for unit in list(reacting_army.units or []):
                if unit is None:
                    continue
                root = unit.get_attached_unit_root()
                if root is None:
                    continue
                rid = str(get_entity_id(root) or "")
                if rid and rid in seen:
                    continue
                if rid:
                    seen.add(rid)

                rule = root.get_hyperspace_hunters_rule()
                if not rule:
                    continue
                if root.hyperspace_hunters_used_this_turn(self):
                    continue
                if not root.can_hyperspace_hunters(game=self, game_map=game_map):
                    root.clear_hyperspace_hunters_candidates(self)
                    continue

                candidate_ids = root.get_hyperspace_hunters_candidates(self)
                if not candidate_ids:
                    continue
                try:
                    rng = int(rule.get("range", 18) or 18)
                except Exception:
                    rng = 18
                actionable = []
                for cid in list(candidate_ids or []):
                    enemy = self._resolve_unit_by_id(str(cid))
                    if enemy is None:
                        continue
                    if not enemy.is_alive():
                        continue
                    if not getattr(enemy, "deployed", True):
                        continue
                    if enemy.get_parent_army() is root.get_parent_army():
                        continue
                    if not root.can_hyperspace_hunters(
                        game=self,
                        game_map=game_map,
                        enemy_unit=enemy,
                        range_override=rng,
                    ):
                        continue
                    if callable(can_shoot_fn) and not bool(can_shoot_fn(root, enemy)):
                        continue
                    actionable.append(enemy)
                if not actionable:
                    root.clear_hyperspace_hunters_candidates(self)
                    continue

                reacting_unit_id = str(get_entity_id(root) or "")
                if not reacting_unit_id:
                    root.clear_hyperspace_hunters_candidates(self)
                    continue

                already_pending = False
                if queue is not None and hasattr(queue, "list"):
                    for req in list(queue.list() or []):
                        if str(getattr(req, "decision_type", "") or "") != DECISION_CHOOSE_QUARRY:
                            continue
                        ctx = dict(getattr(req, "context", {}) or {})
                        if str(ctx.get("ability", "") or "") != "hyperspace_hunters":
                            continue
                        if str(ctx.get("unit_id", "") or "") != reacting_unit_id:
                            continue
                        if int(ctx.get("battle_round", battle_round) or battle_round) != battle_round:
                            continue
                        if str(ctx.get("trigger_player_id", "") or "") != trigger_player_id:
                            continue
                        already_pending = True
                        break
                if already_pending:
                    root.clear_hyperspace_hunters_candidates(self)
                    continue

                req_options = [
                    DecisionOption.create(
                        "None",
                        payload={
                            "action": "skip",
                            "unit_id": reacting_unit_id,
                        },
                    )
                ]
                candidate_unit_ids: list[str] = []
                used_labels: set[str] = set()
                for target_unit in sorted(
                    list(actionable),
                    key=lambda cand: str(get_entity_id(cand) or ""),
                ):
                    target_id = str(get_entity_id(target_unit) or "")
                    if not target_id or target_id in candidate_unit_ids:
                        continue
                    candidate_unit_ids.append(target_id)
                    label = str(getattr(target_unit, "name", "") or "Enemy unit")
                    base = label
                    idx = 2
                    while label in used_labels:
                        label = f"{base} ({idx})"
                        idx += 1
                    used_labels.add(label)
                    req_options.append(
                        DecisionOption.create(
                            label,
                            payload={
                                "target_unit_id": target_id,
                                "unit_id": reacting_unit_id,
                            },
                        )
                    )
                if len(req_options) <= 1:
                    root.clear_hyperspace_hunters_candidates(self)
                    continue

                ability_name = str(rule.get("source", "") or "Hyperspace Hunters").strip() or "Hyperspace Hunters"
                request = DecisionRequest.create(
                    DECISION_CHOOSE_QUARRY,
                    f"{ability_name}: Select shooting target for {getattr(root, 'name', 'Unit')} (or None).",
                    player_id=getattr(reacting_player, "id", None),
                    options=req_options,
                    context={
                        "ability": "hyperspace_hunters",
                        "ability_name": ability_name,
                        "phase": "Movement phase - Reinforcements step",
                        "unit_id": reacting_unit_id,
                        "army_id": str(get_entity_id(reacting_army) or ""),
                        "battle_round": int(battle_round or 0),
                        "trigger_player_id": trigger_player_id,
                        "candidate_unit_ids": list(candidate_unit_ids),
                    },
                )
                self.request_decision(request)
                root.clear_hyperspace_hunters_candidates(self)

    def _on_phase_end_miraculous_saviour(self, player=None, phase=None, **_kwargs) -> None:
        pname = str(getattr(phase, "name", "") or "").strip().upper()
        if pname != "CHARGE_PHASE":
            return
        current_player = self.get_current_player()
        if current_player is None:
            return
        if player is None or player is not current_player:
            return
        if not bool(getattr(self, "is_authoritative", True)):
            return

        try:
            battle_round = int(getattr(self, "turn", 0) or 0)
        except Exception:
            battle_round = 0
        trigger_player_id = str(getattr(current_player, "id", "") or "")
        queue = getattr(self, "decision_queue", None)

        for reacting_player in list(getattr(self, "players", []) or []):
            if reacting_player is None or reacting_player is current_player:
                continue
            reacting_army = self._get_player_army(reacting_player)
            if reacting_army is None:
                continue
            seen = set()
            for unit in list(reacting_army.units or []):
                if unit is None:
                    continue
                root = unit.get_attached_unit_root()
                if root is None:
                    continue
                rid = str(get_entity_id(root) or "")
                if rid and rid in seen:
                    continue
                if rid:
                    seen.add(rid)
                rule = root.get_miraculous_saviour_rule()
                if not rule:
                    continue
                if not root.can_miraculous_saviour(game=self):
                    continue

                reacting_unit_id = str(get_entity_id(root) or "")
                if not reacting_unit_id:
                    continue

                already_pending = False
                if queue is not None and hasattr(queue, "list"):
                    for req in list(queue.list() or []):
                        if str(getattr(req, "decision_type", "") or "") != DECISION_CHOOSE_QUARRY:
                            continue
                        ctx = dict(getattr(req, "context", {}) or {})
                        if str(ctx.get("ability", "") or "") != "miraculous_saviour":
                            continue
                        if str(ctx.get("unit_id", "") or "") != reacting_unit_id:
                            continue
                        if int(ctx.get("battle_round", battle_round) or battle_round) != battle_round:
                            continue
                        if str(ctx.get("trigger_player_id", "") or "") != trigger_player_id:
                            continue
                        already_pending = True
                        break
                if already_pending:
                    continue

                candidate_units = []
                enemy_army = self._get_player_army(current_player)
                for enemy in list(getattr(enemy_army, "units", []) or []):
                    if enemy is None:
                        continue
                    enemy_root = enemy.get_attached_unit_root()
                    if enemy_root is None:
                        continue
                    if not enemy_root.is_alive():
                        continue
                    if not getattr(enemy_root, "deployed", True):
                        continue
                    if not bool(getattr(getattr(enemy_root, "round_state", None), "charged_this_round", False)):
                        continue
                    if enemy_root.get_parent_army() is root.get_parent_army():
                        continue
                    if not root.can_miraculous_saviour(game=self, target_unit=enemy_root):
                        continue
                    candidate_units.append(enemy_root)
                if not candidate_units:
                    continue

                options = [
                    DecisionOption.create(
                        "None",
                        payload={
                            "action": "skip",
                            "unit_id": reacting_unit_id,
                        },
                    )
                ]
                candidate_ids: list[str] = []
                used_labels: set[str] = set()
                for enemy_root in sorted(
                    list(candidate_units),
                    key=lambda cand: str(get_entity_id(cand) or ""),
                ):
                    target_id = str(get_entity_id(enemy_root) or "")
                    if not target_id or target_id in candidate_ids:
                        continue
                    candidate_ids.append(target_id)
                    label = str(getattr(enemy_root, "name", "") or "Enemy unit")
                    base = label
                    idx = 2
                    while label in used_labels:
                        label = f"{base} ({idx})"
                        idx += 1
                    used_labels.add(label)
                    options.append(
                        DecisionOption.create(
                            label,
                            payload={
                                "target_unit_id": target_id,
                                "unit_id": reacting_unit_id,
                            },
                        )
                    )
                if len(options) <= 1:
                    continue

                ability_name = str(rule.get("source", "") or "Miraculous Saviour").strip() or "Miraculous Saviour"
                request = DecisionRequest.create(
                    DECISION_CHOOSE_QUARRY,
                    f"{ability_name}: Select enemy charge unit for {getattr(root, 'name', 'Unit')} (or None).",
                    player_id=getattr(reacting_player, "id", None),
                    options=options,
                    context={
                        "ability": "miraculous_saviour",
                        "ability_name": ability_name,
                        "phase": "Charge phase",
                        "unit_id": reacting_unit_id,
                        "army_id": str(get_entity_id(reacting_army) or ""),
                        "battle_round": int(battle_round or 0),
                        "trigger_player_id": trigger_player_id,
                        "candidate_unit_ids": list(candidate_ids),
                    },
                )
                self.request_decision(request)
